INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前者", "is_correct": true, "explanation": "“前者”指两项中先提到的那一项，即北京，句意成立。"}, {"text": "彼此", "is_correct": false, "explanation": "语义：“彼此”表示互相，不指一个可以去过的地方，“我去过彼此”说不通。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，不能作“去过”的对象，这里应是城市。"}, {"text": "别人", "is_correct": false, "explanation": "搭配：“去过”要求地点作宾语，不能说“去过别人”。"}], "explanations": {"前者": "“前者”指两项中先提到的那一项，即北京，句意成立。", "彼此": "语义：“彼此”表示互相，不指一个可以去过的地方，“我去过彼此”说不通。", "他们": "语义：“他们”指人，不能作“去过”的对象，这里应是城市。", "别人": "搭配：“去过”要求地点作宾语，不能说“去过别人”。"}, "sentence_index": 6, "correct_answer": "前者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前者的日子很苦，现在好多了。", "explanation": "这里应该用〈以前〉。前者只指两项中先提到的那一项，不能用来指过去的时间。"}, {"text": "排队的时候，我站在前者后面。", "explanation": "这里应该用〈前面的那个〉。前者只指两项中先提到的那一项，不能指排队时站在前面的人。"}, {"text": "老师给了两个办法，我两个都选了前者。", "explanation": "这里的“前者”不能指两项全部。“前者”只指两项中先提到的那一项；要表示两项都包括，应说〈两者〉或〈全部〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个方案，我更看好一个前者。", "corrected_sentence": "这两个方案，我更看好前者。", "error_description": "“前者”是代词，前面不能加数量词“一个”，应直接说“我更看好前者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两份工作，我觉得前者们更适合我。", "corrected_sentence": "这两份工作，我觉得前者更适合我。", "error_description": "“前者”不能加“们”表示复数，应说“前者更适合我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异国", "is_correct": true, "explanation": "异国与本土是反义关系，指外国、别的国家。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋与本土没有反义关系，指广阔的咸水区域。"}, {"text": "公园", "is_correct": false, "explanation": "公园与本土没有反义关系，指供人游玩休息的场所。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户与本土没有反义关系，指房屋墙上透光通气的开口。"}], "correct_answer": "异国", "explanations": {"异国": "异国与本土是反义关系，指外国、别的国家。", "海洋": "海洋与本土没有反义关系，指广阔的咸水区域。", "公园": "公园与本土没有反义关系，指供人游玩休息的场所。", "窗户": "窗户与本土没有反义关系，指房屋墙上透光通气的开口。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异国", "is_correct": true, "explanation": "异国与本土是反义关系，指外国、别的国家。"}, {"text": "高山", "is_correct": false, "explanation": "高山与本土没有反义关系，指海拔很高的山。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房与本土没有反义关系，指做饭的房间。"}, {"text": "钟表", "is_correct": false, "explanation": "钟表与本土没有反义关系，指计时的器具。"}], "correct_answer": "异国", "explanations": {"异国": "异国与本土是反义关系，指外国、别的国家。", "高山": "高山与本土没有反义关系，指海拔很高的山。", "厨房": "厨房与本土没有反义关系，指做饭的房间。", "钟表": "钟表与本土没有反义关系，指计时的器具。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本土就是一个人出生和长大的地方。", "primary_collocate": null, "pronunciation": "běn tǔ", "ipa": "pən˨˩˦ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在国外多年，终于回到了本土。", "target_word": "本土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开本土已经十年了，很想家。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "无论走到哪里，我都忘不了本土。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "他回到本土以后，开始教孩子说家乡话。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "在国外的日子里，他最怀念的还是本土。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "他已经很多年没有回过本土了。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "他在本土出生，长大后去了国外。", "target_word": "本土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出国以后，总是怀念本土的味道。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "他在本土度过的童年很快乐。", "target_word": "本土", "complexity_tier": "T3", "furigana": "běn tǔ", "sentence_source": "generated"}, {"text": "住在国外的人常常想念本土的生活。", "target_word": "本土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本土化", "label": "复合"}, {"form": "本土文化", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己出生和长大的国家或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本土", "is_correct": true, "explanation": "指出生和长大的国家或地方，与“国外多年”形成对照，回到本土正合语境。"}, {"text": "外国", "is_correct": false, "explanation": "语义：他已身在国外，“回到外国”与前文矛盾。"}, {"text": "海外", "is_correct": false, "explanation": "语义：“海外”同样指国外，“回到海外”与他已身在国外的语境相冲突。"}, {"text": "异国", "is_correct": false, "explanation": "语域：“异国”偏书面，与叙述口吻不协调；语义上回到异国也与他已在国外矛盾。"}], "explanations": {"本土": "指出生和长大的国家或地方，与“国外多年”形成对照，回到本土正合语境。", "外国": "语义：他已身在国外，“回到外国”与前文矛盾。", "海外": "语义：“海外”同样指国外，“回到海外”与他已身在国外的语境相冲突。", "异国": "语域：“异国”偏书面，与叙述口吻不协调；语义上回到异国也与他已在国外矛盾。"}, "sentence_index": 0, "correct_answer": "本土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这个本土住了五年，很喜欢这里的生活。", "explanation": "这里应该用〈地方〉。本土指一个人出生和长大的国家或地区，不用来泛指随便住过的地方。"}, {"text": "这个国家的本土是北京。", "explanation": "这里应该用〈首都〉。本土指人出生长大的国家或地区，国家的政治中心要用首都。"}, {"text": "学校的本土很大，每天都有很多学生。", "explanation": "这里应该用〈校园〉。本土指人出生长大的国家或地方，不能用来形容学校的占地范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本土", "is_correct": true, "explanation": "指出生和长大的国家或地方，与“在……出生”的语境吻合，是唯一合适的词。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：人一般不会在图书馆出生，与“出生”的处所不符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”不是出生的地方，这句话不成立。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“在……出生”要求具体的处所，“时间”不能作为出生的地点。"}], "explanations": {"本土": "指出生和长大的国家或地方，与“在……出生”的语境吻合，是唯一合适的词。", "图书馆": "语义：人一般不会在图书馆出生，与“出生”的处所不符。", "教室": "语义：“教室”不是出生的地方，这句话不成立。", "时间": "搭配：“在……出生”要求具体的处所，“时间”不能作为出生的地点。"}, "sentence_index": 6, "correct_answer": "本土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去本土看病，医生说没有什么大问题。", "explanation": "这里应该用〈医院〉。本土指国家或地区，不指就医的场所，看病要去医院。"}, {"text": "他下班以后就回本土吃饭。", "explanation": "这里应该用〈家〉。本土指国家或地区，不能用来指每天下班回去的住处。"}, {"text": "这座城市的本土很多，人口也很密集。", "explanation": "这里应该用〈地区〉。本土指人出生和长大的国家或地方，不能用来描述城市的面积或人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于回在本土了。", "corrected_sentence": "他终于回到本土了。", "error_description": "补语错误：“回到”是动补结构，“到”表示到达，不能换成“在”，应说“他终于回到本土了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她决定回了到本土定居。", "corrected_sentence": "她决定回到本土定居。", "error_description": "“了”位置错误：“了”不能插在“回”和“到”之间，“回到”是动补结构，应说“回到本土定居”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
