INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教练把新队员部署了到北区。", "corrected_sentence": "教练把新队员部署到了北区。", "error_description": "“了”应放在补语“到”之后。应说“部署到了北区”，不能说“部署了到北区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7238a18d-5254-4eec-bff3-31084528adc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救援队把物资部署了灾区。", "corrected_sentence": "救援队把物资部署到了灾区。", "error_description": "“部署”后漏掉处所补语“到”。应说“部署到了灾区”，不能说“部署了灾区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7238a18d-5254-4eec-bff3-31084528adc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
