INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "像拉紧的绳子或橡皮筋的那种力量。", "primary_collocate": null, "pronunciation": "zhāng lì", "ipa": "ʈʂɑŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "橡皮筋拉得越长，张力越大。", "target_word": "张力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绳子的张力太大，所以断了。", "target_word": "张力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根绳子有很大的张力。", "target_word": "张力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓皮的张力不一样，声音也不一样。", "target_word": "张力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条橡皮筋没有张力了。", "target_word": "张力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拉紧的弓有很大的张力。", "target_word": "张力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绳子变松了，张力就变小。", "target_word": "张力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "琴弦的张力太小，声音不好听。", "target_word": "张力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你感到手里绳子的张力了吗？", "target_word": "张力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子太细，受不了这么大的张力。", "target_word": "张力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面张力", "label": "复合"}, {"form": "张力计", "label": "复合"}], "register": "书面", "sense_fingerprint": "物体被拉紧时产生的拉力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "张力", "is_correct": true, "explanation": "正确：橡皮筋拉得越长，产生的拉力越大，这种拉力就是“张力”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或物存在的时间长短，橡皮筋拉得越长，年龄并不会越大。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指明暗程度，橡皮筋拉得越长，亮度并不会因此变大，这里说的是拉力。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观的色彩，和拉长橡皮筋产生的力量无关，这里说的是拉力。"}], "explanations": {"张力": "正确：橡皮筋拉得越长，产生的拉力越大，这种拉力就是“张力”。", "年龄": "语义：“年龄”指人或物存在的时间长短，橡皮筋拉得越长，年龄并不会越大。", "亮度": "语义：“亮度”指明暗程度，橡皮筋拉得越长，亮度并不会因此变大，这里说的是拉力。", "颜色": "语义：“颜色”指外观的色彩，和拉长橡皮筋产生的力量无关，这里说的是拉力。"}, "sentence_index": 0, "correct_answer": "张力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的张力很大，能举起两百斤。", "explanation": "这里应该用〈力量〉。“张力”指物体被拉紧时的拉力，说人的力气要用〈力量〉。"}, {"text": "这个队的张力很强，几乎没有对手。", "explanation": "这里应该用〈实力〉。“张力”指拉紧时的拉力，说球队的能力强要用〈实力〉。"}, {"text": "他的张力很好，能看清楚远处的字。", "explanation": "这里应该用〈视力〉。“张力”指拉力，说眼睛看得清楚要用〈视力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "张力", "is_correct": true, "explanation": "正确：绳子松了，拉力就变小，这里的拉力就是“张力”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：绳子变松不会让价格变小，这里说的是绳子被拉紧的力量。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，绳子变松和体重没有关系，这里说的是拉力。"}, {"text": "分数", "is_correct": false, "explanation": "语义：“分数”指考试成绩，绳子变松不会让分数变小，这里说的是绳子上的拉力。"}], "explanations": {"张力": "正确：绳子松了，拉力就变小，这里的拉力就是“张力”。", "价格": "语义：绳子变松不会让价格变小，这里说的是绳子被拉紧的力量。", "体重": "语义：“体重”指身体的重量，绳子变松和体重没有关系，这里说的是拉力。", "分数": "语义：“分数”指考试成绩，绳子变松不会让分数变小，这里说的是绳子上的拉力。"}, "sentence_index": 6, "correct_answer": "张力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电池储存了很多张力。", "explanation": "这里应该用〈能量〉。“张力”指拉紧物体时的拉力，不能用来说储存的能量。"}, {"text": "鞋底的张力很大，所以不容易滑倒。", "explanation": "这里应该用〈摩擦力〉。“张力”是拉紧时的拉力，防滑要用〈摩擦力〉。"}, {"text": "船的张力很大，可以浮在水上。", "explanation": "这里应该用〈浮力〉。“张力”指拉力，浮在水上要用〈浮力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "橡皮筋的一个张力让它很快缩回来。", "corrected_sentence": "橡皮筋的张力让它很快缩回来。", "error_description": "错误形式：“一个张力”；正确形式：“张力”。“个”不宜与抽象名词“张力”搭配，应去掉量词，说“橡皮筋的张力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根弦地张力太小，不能弹出好听的声音。", "corrected_sentence": "这根弦的张力太小，不能弹出好听的声音。", "error_description": "修饰“张力”要用结构助词“的”，不能用“地”，应说“这根弦的张力太小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
