INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22594, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西被压扁或拉长后，能变回原来的样子。", "primary_collocate": null, "pronunciation": "tán xìng", "ipa": "tʰan˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这根橡皮筋很有弹性。", "target_word": "弹性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条裤子弹性很好，穿起来很舒服。", "target_word": "弹性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑鞋的底有弹性，跑步时脚不太累。", "target_word": "弹性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料的弹性比较差，一拉就断了。", "target_word": "弹性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮球没有弹性了，怎么拍也不跳。", "target_word": "弹性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年纪大了，皮肤的弹性会慢慢变差。", "target_word": "弹性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包压扁后又弹回来，说明它很有弹性。", "target_word": "弹性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种弹簧弹性很强，压下去很快就能回来。", "target_word": "弹性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做运动服的布要有弹性，不然穿着不方便。", "target_word": "弹性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把弹性好的网球放进包里，准备去打球。", "target_word": "弹性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹性材料", "label": "复合"}, {"form": "弹性好", "label": "复合"}], "register": "通用", "sense_fingerprint": "物体受力变形后恢复原状的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eea9ae5a-a1c2-46b4-ba5e-281e3260ca2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹性", "is_correct": true, "explanation": "正确：“很有弹性”说的是橡皮筋被拉长后能变回原样，与句子语境相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，橡皮筋不能“很有脾气”。"}, {"text": "思想", "is_correct": false, "explanation": "语义：“思想”指人的想法，不能用来形容橡皮筋。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体占据空间的大小，不能说明橡皮筋的弹性，与句意不符。"}], "explanations": {"弹性": "正确：“很有弹性”说的是橡皮筋被拉长后能变回原样，与句子语境相符。", "脾气": "语义：“脾气”是人的性情，橡皮筋不能“很有脾气”。", "思想": "语义：“思想”指人的想法，不能用来形容橡皮筋。", "体积": "搭配：“体积”指物体占据空间的大小，不能说明橡皮筋的弹性，与句意不符。"}, "sentence_index": 0, "correct_answer": "弹性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种石头的弹性很高，很难被敲碎。", "explanation": "这里应该用〈硬度〉。“弹性”指受力后恢复原状，石头抵抗压力的能力要用“硬度”。"}, {"text": "这种木头的弹性很深，颜色也很漂亮。", "explanation": "这里应该用〈深浅〉。“弹性”指恢复原状的性质，不能用来说深浅。"}, {"text": "他的弹性很大，一下子就把箱子抬起来了。", "explanation": "这里应该用〈力气〉。“弹性”指物体的恢复性质，人的力量大要用“力气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弹性", "is_correct": true, "explanation": "正确：“很有弹性”说明面包受压后能恢复原状，与“压扁后又弹回来”相呼应。"}, {"text": "勇气", "is_correct": false, "explanation": "语义：“勇气”是人的品质，面包不能有勇气。"}, {"text": "耐心", "is_correct": false, "explanation": "语义：“耐心”指人的忍耐态度，与“弹回来”无关。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”说大小，不能说“很有尺寸”。"}], "explanations": {"弹性": "正确：“很有弹性”说明面包受压后能恢复原状，与“压扁后又弹回来”相呼应。", "勇气": "语义：“勇气”是人的品质，面包不能有勇气。", "耐心": "语义：“耐心”指人的忍耐态度，与“弹回来”无关。", "尺寸": "搭配：“尺寸”说大小，不能说“很有尺寸”。"}, "sentence_index": 6, "correct_answer": "弹性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的弹性很大，我一个人搬不动。", "explanation": "这里应该用〈重量〉。“弹性”指恢复原状的性质，箱子的轻重要用“重量”。"}, {"text": "这首歌的弹性很亮，我每天都听。", "explanation": "这里应该用〈音色〉。“弹性”不能形容声音的明亮程度。"}, {"text": "这杯水的弹性很高，喝下去会烫嘴。", "explanation": "这里应该用〈温度〉。“弹性”不能说冷热，“烫嘴”说的是温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种面料很弹性，穿起来很舒服。", "corrected_sentence": "这种面料很有弹性，穿起来很舒服。", "error_description": "漏了动词“有”：说“有弹性”要带“有”，错句“很弹性”应改为“很有弹性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块海绵垫弹性的很好，坐上去很舒服。", "corrected_sentence": "这块海绵垫弹性很好，坐上去很舒服。", "error_description": "多加了“的”：“弹性”与“很好”之间直接相连，中间不用“的”，错句“弹性的很好”应改为“弹性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示只能做一件事，没有别的选择。", "primary_collocate": null, "pronunciation": "bù dé bù", "ipa": "pu˥˩ tɤ˧˥ pu˥˩", "syllable_count": 3, "sentences": [{"text": "下雨了，我们不得不回家。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他病了，不得不请假。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车坏了，我不得不走路去学校。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱不够，他不得不少买一点。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司太远，我不得不早起。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太晚了，我们不得不坐出租车。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师生气了，他不得不说对不起。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没电了，我不得不借朋友的。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业太多，我不得不晚点睡觉。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里没有菜，妈妈不得不去超市。", "target_word": "不得不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "因情况所迫，没有别的选择，只能这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不得不", "is_correct": true, "explanation": "正确。“不得不”表示迫于情况，没有别的选择，符合“下雨了，我们只能回家”的语境。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意去做，与“下雨了”这一被迫的原因相矛盾。"}, {"text": "居然", "is_correct": false, "explanation": "语义：“居然”表示出乎意料，下雨后回家是顺理成章的事，用“居然”不合语境。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱或强调要注意的事，不能用来修饰“我们回家”这样的陈述。"}], "explanations": {"不得不": "正确。“不得不”表示迫于情况，没有别的选择，符合“下雨了，我们只能回家”的语境。", "故意": "语义：“故意”表示有意去做，与“下雨了”这一被迫的原因相矛盾。", "居然": "语义：“居然”表示出乎意料，下雨后回家是顺理成章的事，用“居然”不合语境。", "千万": "搭配：“千万”多用于叮嘱或强调要注意的事，不能用来修饰“我们回家”这样的陈述。"}, "sentence_index": 0, "correct_answer": "不得不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们有很多选择，不得不选这一个。", "explanation": "这里不这么用。“不得不”表示没有别的选择，句中却说“有很多选择”，前后矛盾。"}, {"text": "饭已经做好了，我不得不继续做饭。", "explanation": "这里不这么用。“不得不”表示被迫去做，而饭已做好，没有继续做饭的必要，前后矛盾。"}, {"text": "他没有钱，不得不买了一个大房子。", "explanation": "这里不这么用。“不得不”表示被迫去做，没有钱却被迫买大房子前后矛盾，应说“他没有钱，不可能买大房子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不得不", "is_correct": true, "explanation": "正确。“不得不”表示被迫去做，符合“老师生气了，他只能道歉”的语境。"}, {"text": "统统", "is_correct": false, "explanation": "搭配：“统统”表示全部，要修饰多个对象，不能修饰“说对不起”这一个动作。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”一般与“不”“没”连用，不能直接说“从来说对不起”。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，老师生气后道歉是顺理成章的，用“反而”不合语境。"}], "explanations": {"不得不": "正确。“不得不”表示被迫去做，符合“老师生气了，他只能道歉”的语境。", "统统": "搭配：“统统”表示全部，要修饰多个对象，不能修饰“说对不起”这一个动作。", "从来": "搭配：“从来”一般与“不”“没”连用，不能直接说“从来说对不起”。", "反而": "语义：“反而”表示与预期相反，老师生气后道歉是顺理成章的，用“反而”不合语境。"}, "sentence_index": 6, "correct_answer": "不得不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛是我自愿报名的，但我不得不参加。", "explanation": "这里不这么用。“不得不”表示被迫，句中说是“自愿报名”，前后矛盾。"}, {"text": "这里随便停车，他不得不把车停在这里。", "explanation": "这里应该用〈可以〉。“不得不”表示被迫，而这里允许停车，没有被迫的理由，应说“可以停在这里”。"}, {"text": "他有很多钱，却不得不去借钱。", "explanation": "这里不这么用。“不得不”表示被迫，句中说“有很多钱”，没有借钱的必要，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月房租太高，他不得不的搬到郊区。", "corrected_sentence": "这个月房租太高，他不得不搬到郊区。", "error_description": "助词误用：“不得不”是副词，后面不能加结构助词“的”；应说“他不得不搬到郊区”，不说“他不得不的搬到郊区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试太难，同学们不得不地重新复习。", "corrected_sentence": "这次考试太难，同学们不得不重新复习。", "error_description": "助词误用：“不得不”是固定的副词用法，后面不加结构助词“地”；应说“不得不重新复习”，不说“不得不地重新复习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热情", "is_correct": true, "explanation": "热情与“冷酷”构成反义，形容对人态度热烈友好，与冷淡相对。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，与“冷酷”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔形容面积大，与“冷酷”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容质地不平滑，与“冷酷”没有反义关系。"}], "correct_answer": "热情", "explanations": {"热情": "热情与“冷酷”构成反义，形容对人态度热烈友好，与冷淡相对。", "迅速": "迅速形容速度快，与“冷酷”没有反义关系。", "宽阔": "宽阔形容面积大，与“冷酷”没有反义关系。", "粗糙": "粗糙形容质地不平滑，与“冷酷”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温柔", "is_correct": true, "explanation": "温柔与“冷酷”相对，形容待人温和体贴，与“冷酷”的无情相反。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容清楚明白，与“冷酷”没有反义关系。"}, {"text": "松软", "is_correct": false, "explanation": "松软形容质地柔软，与“冷酷”没有反义关系。"}, {"text": "整洁", "is_correct": false, "explanation": "整洁形容干净利落，与“冷酷”没有反义关系。"}], "correct_answer": "温柔", "explanations": {"温柔": "温柔与“冷酷”相对，形容待人温和体贴，与“冷酷”的无情相反。", "清晰": "清晰形容清楚明白，与“冷酷”没有反义关系。", "松软": "松软形容质地柔软，与“冷酷”没有反义关系。", "整洁": "整洁形容干净利落，与“冷酷”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人冷淡、无情，一点也不关心别人。", "primary_collocate": null, "pronunciation": "lěng kù", "ipa": "ləŋ˨˩ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "他对邻居的态度一直很冷酷。", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对哭泣的孩子，她的表情冷酷。", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷酷的老师让学生们都不敢说话。", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个冷酷的男人看都不看我一眼。", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他冷酷地拒绝了朋友的请求。", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他冷酷地把信扔进了垃圾桶。", "target_word": "冷酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么能对生病的母亲这么冷酷？", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着，可是眼神很冷酷。", "target_word": "冷酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理冷酷地说：“这件事跟我没关系。”", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他变得冷酷，朋友们都离开了他。", "target_word": "冷酷", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷酷无情", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：待人冷淡无情，不讲感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73399449-2470-45bf-a42c-72fe9fbc4333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷酷", "is_correct": true, "explanation": "形容对人的态度冷淡无情，与“对邻居的态度”相合，符合句意。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度极高，不能用来形容对人的态度。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形或形象，不能修饰“态度”。"}, {"text": "雪亮", "is_correct": false, "explanation": "搭配：“雪亮”形容光线明亮，不能修饰“态度”。"}], "explanations": {"冷酷": "形容对人的态度冷淡无情，与“对邻居的态度”相合，符合句意。", "滚烫": "语义：“滚烫”形容温度极高，不能用来形容对人的态度。", "高大": "搭配：“高大”形容体形或形象，不能修饰“态度”。", "雪亮": "搭配：“雪亮”形容光线明亮，不能修饰“态度”。"}, "sentence_index": 0, "correct_answer": "冷酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅平时很冷酷。", "explanation": "这里应该用〈冷清〉。“冷酷”形容人对人的态度冷淡无情，不用来形容地方人少、不热闹。"}, {"text": "这杯茶已经冷酷了。", "explanation": "这里应该用〈冷却〉。“冷酷”不用来说饮料的温度下降，应说“冷却”。"}, {"text": "这块石头很冷酷。", "explanation": "这里应该用〈坚硬〉。“冷酷”不用来形容石头的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷酷", "is_correct": true, "explanation": "形容对生病的母亲态度无情，与句中的责备语气相合，符合句意。"}, {"text": "寒酸", "is_correct": false, "explanation": "语义：“寒酸”形容穷困、不体面，与对母亲的态度无关。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰人对待母亲的态度。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣诙谐，与句中责备的语气不合。"}], "explanations": {"冷酷": "形容对生病的母亲态度无情，与句中的责备语气相合，符合句意。", "寒酸": "语义：“寒酸”形容穷困、不体面，与对母亲的态度无关。", "清脆": "搭配：“清脆”形容声音，不能修饰人对待母亲的态度。", "幽默": "语义：“幽默”指风趣诙谐，与句中责备的语气不合。"}, "sentence_index": 6, "correct_answer": "冷酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏夜的风很冷酷。", "explanation": "这里应该用〈凉快〉。“冷酷”形容人的态度冷淡无情，不用来形容天气或风。"}, {"text": "阳光很冷酷。", "explanation": "这里应该用〈明亮〉。“冷酷”形容人的态度冷淡无情，不用来形容阳光。"}, {"text": "这条毛巾很冷酷。", "explanation": "这里应该用〈柔软〉。“冷酷”不用来形容织物的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他冷酷的看着我，一句话也不说。", "corrected_sentence": "他冷酷地看着我，一句话也不说。", "error_description": "“冷酷”修饰动词“看”时要用状语标志“地”，不能用“的”，应说“冷酷地看着我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冷酷地的笑了一下。", "corrected_sentence": "他冷酷地笑了一下。", "error_description": "结构助词重复：“地”与“的”不能同时修饰动词“笑”，只用“地”，应说“冷酷地笑了一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
