INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或两个公司一起出钱做一件事情。", "primary_collocate": null, "pronunciation": "hé zī", "ipa": "/xɤ˧˥ tsɹ̩˥/", "syllable_count": 2, "sentences": [{"text": "我们两个人合资开一家店。", "target_word": "合资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥和朋友合资开了一家健身房。", "target_word": "合资", "complexity_tier": "T3", "furigana": "gēge hé péngyou hézī kāi le yì jiā jiànshēnfáng.", "sentence_source": "generated"}, {"text": "两家公司想合资生产新电脑。", "target_word": "合资", "complexity_tier": "T3", "furigana": "liǎng jiā gōngsī xiǎng hézī shēngchǎn xīn diànnǎo.", "sentence_source": "generated"}, {"text": "他们合资开了一家饭馆。", "target_word": "合资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王和小李合资做生意。", "target_word": "合资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们先合资，以后再分钱。", "target_word": "合资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他和姐姐合资经营了一家网店。", "target_word": "合资", "complexity_tier": "T3", "furigana": "tā hé jiějie hézī jīngyíng le yì jiā wǎngdiàn.", "sentence_source": "generated"}, {"text": "三个同学想合资开一家小书店。", "target_word": "合资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店是两个人合资开的。", "target_word": "合资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几家小公司合资建了一个大市场。", "target_word": "合资", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "合资企业", "label": "复合"}, {"form": "合资公司", "label": "复合"}, {"form": "合資", "label": "繁体"}], "register": "中性", "sense_fingerprint": "合资：两个人或公司一起出钱做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a08370da-969c-4fbf-929d-854650f0ace1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合资", "is_correct": true, "explanation": "正确：“合资”指两人共同出钱做事，与“我们两个人”搭配，句意通顺。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“开一家店”没有联系，句意荒唐。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是水中运动，与开店不相关，句意不通。"}, {"text": "投票", "is_correct": false, "explanation": "搭配：“投票”后不能直接接“开店”这类行为，搭配不当。"}], "explanations": {"合资": "正确：“合资”指两人共同出钱做事，与“我们两个人”搭配，句意通顺。", "唱歌": "语义：“唱歌”与“开一家店”没有联系，句意荒唐。", "游泳": "语义：“游泳”是水中运动，与开店不相关，句意不通。", "投票": "搭配：“投票”后不能直接接“开店”这类行为，搭配不当。"}, "sentence_index": 0, "correct_answer": "合资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们合资了那位迷路的老人。", "explanation": "这里应该用〈帮助〉。合资指共同出钱做事，不能用来指对人的援助。"}, {"text": "我们同意合资老师的意见。", "explanation": "这里应该用〈接受〉。合资指共同出钱做事，不能用来表示接受别人的意见。"}, {"text": "我们在车站合资朋友。", "explanation": "这里应该用〈等待〉。合资指共同出钱做事，不能用来表示在某处等人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7238a18d-5254-4eec-bff3-31084528adc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合资", "is_correct": true, "explanation": "正确：“合资”指两人共同出钱做事，与“他和姐姐”的共同投入语境相合。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争吵，与两人共同经营网店的语境不合，句意荒谬。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”不能与“经营”构成并列动作，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是语言转换，与开网店无关，句意荒谬。"}], "explanations": {"合资": "正确：“合资”指两人共同出钱做事，与“他和姐姐”的共同投入语境相合。", "吵架": "语义：“吵架”是争吵，与两人共同经营网店的语境不合，句意荒谬。", "打扫": "搭配：“打扫”不能与“经营”构成并列动作，句意不通。", "翻译": "语义：“翻译”是语言转换，与开网店无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "合资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在旅途中合资了很多朋友。", "explanation": "这里应该用〈结交〉。合资指共同出钱做事，不能用来指交朋友。"}, {"text": "大家在会上认真合资方案。", "explanation": "这里应该用〈讨论〉。合资强调共同出钱做事，不能用于共同商议方案。"}, {"text": "士兵合资边境。", "explanation": "这里应该用〈守卫〉。合资指共同出钱做事，不能用来表示军人守护边境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7238a18d-5254-4eec-bff3-31084528adc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆旧车是我们两个人合资了买的。", "corrected_sentence": "这辆旧车是我们两个人合资买的。", "error_description": "错误形式：“合资了买的”；正确形式：“合资买的”。在“是……的”句式中强调已发生的动作，“了”多余，且不能插在“合资”与“买”之间，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7238a18d-5254-4eec-bff3-31084528adc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们几个人正在合资了开一家茶馆。", "corrected_sentence": "他们几个人正在合资开一家茶馆。", "error_description": "错误形式：“正在合资了开”；正确形式：“正在合资开”。“正在”表示进行，不能与“了”同用，“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7238a18d-5254-4eec-bff3-31084528adc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负责任", "is_correct": true, "explanation": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”形容说话风趣，与“不负责任”不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容环境或状态平静，与“不负责任”没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "“诚实”指不说谎，与“不负责任”不是反义词。"}], "correct_answer": "负责任", "explanations": {"负责任": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。", "幽默": "“幽默”形容说话风趣，与“不负责任”不构成反义关系。", "安静": "“安静”形容环境或状态平静，与“不负责任”没有反义关系。", "诚实": "“诚实”指不说谎，与“不负责任”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负责任", "is_correct": true, "explanation": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。"}, {"text": "富有", "is_correct": false, "explanation": "“富有”指钱财多或内容丰富，与“不负责任”没有反义关系。"}, {"text": "寂寞", "is_correct": false, "explanation": "“寂寞”形容心情孤单，与“不负责任”不构成反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”形容品性仁厚，与“不负责任”不是反义词。"}], "correct_answer": "负责任", "explanations": {"负责任": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。", "富有": "“富有”指钱财多或内容丰富，与“不负责任”没有反义关系。", "寂寞": "“寂寞”形容心情孤单，与“不负责任”不构成反义关系。", "善良": "“善良”形容品性仁厚，与“不负责任”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情不认真，不想承担后果的样子。", "primary_collocate": null, "pronunciation": "bù fù zé rèn", "ipa": "pu˥˩ fu˥˩ tsɤ˧˥ ɻən˥˩", "syllable_count": 4, "sentences": [{"text": "他对自己说的话一点也不负责任。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样不负责任的回答，客户当然不满意。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作出了问题，他却说跟自己没关系，真不负责任。", "target_word": "不负责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得很突然，这样做太不负责任了。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子做错了事，家长却不管，这很不负责任。", "target_word": "不负责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不负责任的态度，让同事很失望。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业不写完就去玩，这样不负责任。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你答应了别人却不去做，这是不负责任。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理不负责任，出了错就怪别人。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子没修好就收钱，这家公司太不负责任了。", "target_word": "不负责任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不負責任", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：做事不认真，出了问题也不想承担后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73399449-2470-45bf-a42c-72fe9fbc4333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不负责任", "is_correct": true, "explanation": "正确。“一点也不负责任”指说话不认真，不愿为自己的话承担后果。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”形容面积或空间大，不能用来修饰“说的话”。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”形容含水分的状态，不能用来修饰“说的话”。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容建筑、山峰等向上突出，不能用来修饰“说的话”。"}], "explanations": {"不负责任": "正确。“一点也不负责任”指说话不认真，不愿为自己的话承担后果。", "宽阔": "搭配：“宽阔”形容面积或空间大，不能用来修饰“说的话”。", "湿润": "搭配：“湿润”形容含水分的状态，不能用来修饰“说的话”。", "高耸": "搭配：“高耸”形容建筑、山峰等向上突出，不能用来修饰“说的话”。"}, "sentence_index": 0, "correct_answer": "不负责任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个服务员对客人很不负责任，总是耐心地解答每个问题。", "explanation": "这里应该用〈耐心〉。耐心形容细致、不急躁；“不负责任”指做事不尽责，与“耐心地解答每个问题”矛盾。"}, {"text": "他做事很不负责任，每次都把工作做得一丝不苟。", "explanation": "这里应该用〈细致〉。细致形容做事周到、不粗心；“不负责任”指做事不尽责，与“一丝不苟”矛盾。"}, {"text": "他很不负责任，每次工作都提前完成。", "explanation": "这里应该用〈尽职〉。尽职形容认真履行职责；“不负责任”与“每次工作都提前完成”的语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不负责任", "is_correct": true, "explanation": "正确。“作业不写完就去玩”正是不认真做事、不承担后果的表现，“这样不负责任”语气连贯。"}, {"text": "公平", "is_correct": false, "explanation": "语义：“公平”是正面评价，与“作业不写完就去玩”的批评语境相反。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”是正面评价，与“作业不写完就去玩”的做法相反。"}, {"text": "耐心", "is_correct": false, "explanation": "语义：“耐心”形容做事细致、不急躁，与“作业不写完就去玩”的做法不相符。"}], "explanations": {"不负责任": "正确。“作业不写完就去玩”正是不认真做事、不承担后果的表现，“这样不负责任”语气连贯。", "公平": "语义：“公平”是正面评价，与“作业不写完就去玩”的批评语境相反。", "认真": "语义：“认真”是正面评价，与“作业不写完就去玩”的做法相反。", "耐心": "语义：“耐心”形容做事细致、不急躁，与“作业不写完就去玩”的做法不相符。"}, "sentence_index": 6, "correct_answer": "不负责任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师对学生很不负责任，每次考试都仔细出题。", "explanation": "这里应该用〈严格〉。严格形容要求高、标准严；“不负责任”形容做事不尽责，与“仔细出题”的语境矛盾。"}, {"text": "这家餐厅的服务很不负责任，客人们都很满意。", "explanation": "这里应该用〈热情〉。热情形容服务态度友好积极；“不负责任”是贬义，与“客人们都很满意”的结果不符。"}, {"text": "他花钱很不负责任，从不乱买东西。", "explanation": "这里应该用〈节俭〉。节俭形容不浪费、省着用；“不负责任”指做事不尽责，与“从不乱买东西”的语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次任务交给他，真是太不负责任地了。", "corrected_sentence": "这次任务交给他，真是太不负责任了。", "error_description": "结构助词错误：“地”用于状语后面，形容词作谓语时不加“地”。应写成“太不负责任了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他修车修很不负责任，结果又坏了。", "corrected_sentence": "他修车修得很不负责任，结果又坏了。", "error_description": "补语标记错误：动词后带程度补语，要用“得”引出，写成“修得很不负责任”。“修很不负责任”缺少“得”，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
