INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22604, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管大家的人。", "primary_collocate": null, "pronunciation": "guǎn lǐ zhě", "ipa": "kwan˨˩ li˨˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "工地的管理者是王师傅。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的管理者每天都很忙。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个仓库有两位管理者。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理者应该公平对待大家。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的管理者人很好。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想做一个好的管理者。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的管理者开了一个会。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把问题告诉管理者。", "target_word": "管理者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理者让大家早点回家。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队的管理者买了新球衣。", "target_word": "管理者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "管着大家、负责安排事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c3d54eb-37c5-4193-8809-1266ef82ae7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理者", "is_correct": true, "explanation": "管理者指管大家的人，与“工地的……是王师傅”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是坐车的人，不管理工地，与句子的身份相反。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生是学习的人，不会管理工地。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是人，不能说“工地的桌子是王师傅”。"}], "explanations": {"管理者": "管理者指管大家的人，与“工地的……是王师傅”相符。", "乘客": "语义：乘客是坐车的人，不管理工地，与句子的身份相反。", "小学生": "语义：小学生是学习的人，不会管理工地。", "桌子": "语义：桌子是家具，不是人，不能说“工地的桌子是王师傅”。"}, "sentence_index": 0, "correct_answer": "管理者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们工地的管理者是一座小山。", "explanation": "这里应该用〈地形〉。管理者指管大家的人，不能指地貌。"}, {"text": "这把锤子是我的管理者。", "explanation": "这里应该用〈工具〉。管理者指管大家的人，不能指器具。"}, {"text": "管理者正在小学读书。", "explanation": "这里应该说〈学生〉。管理者负责安排事情，不指正在读书的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理者", "is_correct": true, "explanation": "管理者指管大家的人，与“工厂的……开了一个会”相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是参观的人，不会在工厂召集会议。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是买东西的人，不会以工厂的身份开会。"}, {"text": "作家", "is_correct": false, "explanation": "搭配：“工厂的作家”不能与“开了一个会”搭配。"}], "explanations": {"管理者": "管理者指管大家的人，与“工厂的……开了一个会”相符。", "游客": "语义：游客是参观的人，不会在工厂召集会议。", "顾客": "语义：顾客是买东西的人，不会以工厂的身份开会。", "作家": "搭配：“工厂的作家”不能与“开了一个会”搭配。"}, "sentence_index": 6, "correct_answer": "管理者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "管理者在树上唱歌，声音很好听。", "explanation": "这里应该用〈小鸟〉。管理者指管大家的人，不会在树上唱歌。"}, {"text": "管理者每天在公路上跑，每小时能跑一百公里。", "explanation": "这里应该用〈汽车〉。管理者指管大家的人，不能指能在公路上跑的车辆。"}, {"text": "这个书架是我们的管理者。", "explanation": "这里应该用〈家具〉。管理者指管大家的人，不能指物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个工地有三只管理者。", "corrected_sentence": "这个工地有三位管理者。", "error_description": "量词错误。管理者指人，量词应用“位”，错误形式用了“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂有两张管理者，他们每周开一次会。", "corrected_sentence": "工厂有两位管理者，他们每周开一次会。", "error_description": "量词错误：管理者指人，量词应用“位”或“个”，不能用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
