INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究人类的人。", "primary_collocate": null, "pronunciation": "rén lèi xué jiā", "ipa": "ɻən˧˥ lei˥˩ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "人类学家是研究人类的人。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的人类学家。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家跟当地人一起吃住。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位人类学家对古代人的生活很感兴趣。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家在博物馆里看了很多老东西。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐学了四年，想当人类学家。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家想知道人是怎么生活的。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有一位人类学家来我们学校讲课。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学家带着笔记本去了小村子。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人类学家都喜欢旅行。", "target_word": "人类学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究人类的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律师", "is_correct": false, "explanation": "语义：律师并非研究人类的人，“律师是研究人类的人”与定义不符。"}, {"text": "人类学家", "is_correct": true, "explanation": "人类学家：研究人类的人，与“研究人类的人”的定义相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师从事烹饪，不是研究人类的人，与定义不符。"}, {"text": "学霸", "is_correct": false, "explanation": "语义：“学霸”指成绩优秀的学生，并不研究人类，与“研究人类的人”的定义不符。"}], "explanations": {"律师": "语义：律师并非研究人类的人，“律师是研究人类的人”与定义不符。", "人类学家": "人类学家：研究人类的人，与“研究人类的人”的定义相符。", "厨师": "语义：厨师从事烹饪，不是研究人类的人，与定义不符。", "学霸": "语义：“学霸”指成绩优秀的学生，并不研究人类，与“研究人类的人”的定义不符。"}, "sentence_index": 0, "correct_answer": "人类学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的专业是人类学家，不是医学。", "explanation": "这里应该用〈人类学〉。“人类学”是学科名，作专业要说“人类学”，“人类学家”指从事研究的人。"}, {"text": "这位人类学家在森林里观察蝴蝶的迁徙路线。", "explanation": "这里应该用〈生物学家〉。观察蝴蝶迁徙属于生物学家的工作，人类学家研究的是人类的文化与社会。"}, {"text": "这位人类学家正在实验室研究一种新药。", "explanation": "这里应该用〈医学家〉。研究新药属于医学家的工作，人类学家研究的是人类的文化与社会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白菜", "is_correct": false, "explanation": "搭配：“白菜”是蔬菜，不能作“想知道”的主语。"}, {"text": "人类学家", "is_correct": true, "explanation": "人类学家：研究人类的人，能够想知道人类的生活方式，与语境相符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”是建筑部件，不能作“想知道”的主语。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是时间词，不能有“想知道”的心理活动。"}], "explanations": {"白菜": "搭配：“白菜”是蔬菜，不能作“想知道”的主语。", "人类学家": "人类学家：研究人类的人，能够想知道人类的生活方式，与语境相符。", "窗户": "搭配：“窗户”是建筑部件，不能作“想知道”的主语。", "夏天": "语义：“夏天”是时间词，不能有“想知道”的心理活动。"}, "sentence_index": 6, "correct_answer": "人类学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人类学家的出现比文字还要早。", "explanation": "这里应该用〈人类〉。“人类”指全体人，表示出现的主体要用“人类”，“人类学家”指研究人的专业人员。"}, {"text": "人类学家在山区勘探了一条断层，以判断地震的风险。", "explanation": "这里应该用〈地质学家〉。勘探断层、判断地震风险属于地质学家的工作，人类学家研究的是人类的文化与社会。"}, {"text": "人类学家用望远镜追踪了一颗彗星。", "explanation": "这里应该用〈天文学家〉。追踪彗星属于天文学家的工作，人类学家研究的是人类的文化与社会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥大学毕业后成了一只人类学家。", "corrected_sentence": "我表哥大学毕业后成了一名人类学家。", "error_description": "指人的名词要用“名”或“位”，不能用“只”。“只”多用于动物，正确形式是“一名人类学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老教授很人类学家，退休后还在写书。", "corrected_sentence": "那位老教授是人类学家，退休后还在写书。", "error_description": "名词“人类学家”不能被“很”修饰，应用判断动词“是”。正确形式是“那位老教授是人类学家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
