INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家做事情时心里很兴奋、很勇敢的感觉。", "primary_collocate": null, "pronunciation": "shì qì", "ipa": "ʂʅ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "听了老师的话，全班同学士气十足。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队赢了比赛，大家的士气很高。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨，可是工人们的士气还是很高。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱起队歌后，队员们的士气更足了。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑话让大家的士气好了很多。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，我们要想办法提高士气。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士气高的队伍，常常能赢得比赛。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长带头加油，全班的士气很旺。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离比赛只剩一天，队里的士气非常好。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到观众这么多，运动员们士气大增。", "target_word": "士气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "士气高涨", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家做事时兴奋勇敢的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "士气", "is_correct": true, "explanation": "士气（shìqì）：大家做事时兴奋、勇敢的感觉。"}, {"text": "湿气", "is_correct": false, "explanation": "湿气（shīqì）与士气的第一个音节声调不同：湿为第一声，士为第四声，意思是潮湿的气。"}, {"text": "志气", "is_correct": false, "explanation": "志气（zhìqì）与士气只有第一个音节的声母不同：zh 与 sh 不同，意思是远大的理想和抱负。"}, {"text": "死气", "is_correct": false, "explanation": "死气（sǐqì）与士气的第一个音节声调不同：死为第三声，士为第四声，意思是没有生气。"}], "explanations": {"士气": "士气（shìqì）：大家做事时兴奋、勇敢的感觉。", "湿气": "湿气（shīqì）与士气的第一个音节声调不同：湿为第一声，士为第四声，意思是潮湿的气。", "志气": "志气（zhìqì）与士气只有第一个音节的声母不同：zh 与 sh 不同，意思是远大的理想和抱负。", "死气": "死气（sǐqì）与士气的第一个音节声调不同：死为第三声，士为第四声，意思是没有生气。"}, "sentence_index": null, "correct_answer": "士气"}, "level_3": {"options": [{"text": "士气", "is_correct": true, "explanation": "士气：大家兴奋、勇敢的状态，与“十足”搭配，符合“听了老师的话”的语境。"}, {"text": "水分", "is_correct": false, "explanation": "语义：“水分十足”指含水多，与人的精神状态不符。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“十足”修饰劲头、情绪，不修饰墨水，“墨水十足”不成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温十足”不成立，与“听了老师的话”的语境无关。"}], "explanations": {"士气": "士气：大家兴奋、勇敢的状态，与“十足”搭配，符合“听了老师的话”的语境。", "水分": "语义：“水分十足”指含水多，与人的精神状态不符。", "墨水": "搭配：“十足”修饰劲头、情绪，不修饰墨水，“墨水十足”不成立。", "体温": "语义：“体温十足”不成立，与“听了老师的话”的语境无关。"}, "sentence_index": 0, "correct_answer": "士气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的士气很快，打开文件很迅速。", "explanation": "这里应该用〈速度〉。士气指人的精神状态，电脑运行的快慢要用速度。"}, {"text": "这首歌的士气很动人，大家都听哭了。", "explanation": "这里应该用〈旋律〉。旋律指音乐的音高组合，士气是集体做事时的精神状态，不能用来形容歌曲。"}, {"text": "跑完五公里，他的士气已经不够用了。", "explanation": "这里应该用〈体力〉。体力指身体的力量，士气是集体的精神状态，不用于表示身体的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "士气", "is_correct": true, "explanation": "士气：大家做事时兴奋、勇敢的感觉，可以说“士气高”。"}, {"text": "电压", "is_correct": false, "explanation": "语义：“电压高的队伍”没有意义，与比赛的语境无关。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：“灯光高”不是描述队伍的说法，与语境不符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教具，不能修饰队伍，“黑板高的队伍”不成立。"}], "explanations": {"士气": "士气：大家做事时兴奋、勇敢的感觉，可以说“士气高”。", "电压": "语义：“电压高的队伍”没有意义，与比赛的语境无关。", "灯光": "语义：“灯光高”不是描述队伍的说法，与语境不符。", "黑板": "语义：“黑板”是教具，不能修饰队伍，“黑板高的队伍”不成立。"}, "sentence_index": 6, "correct_answer": "士气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的士气很大，怎么砸也砸不碎。", "explanation": "这里应该用〈硬度〉。士气指人的精神状态，形容石头有多硬要用硬度。"}, {"text": "这位选手的士气很大，一拳就把对手打倒了。", "explanation": "这里应该用〈力气〉。士气指人的精神状态，一拳打倒对手靠的是力气。"}, {"text": "饭菜的士气飘满了整个屋子。", "explanation": "这里应该用〈香气〉。士气指人的精神状态，飘出来的饭菜味道要用香气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到胜利的消息，球员们的士气高涨下来了。", "corrected_sentence": "听到胜利的消息，球员们的士气高涨起来了。", "error_description": "趋向补语错误：士气由低向高发展，应说“高涨起来”；“下来”表示向下，与“高涨”的方向相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支队伍曾经有过一只很高的士气，赢了不少比赛。", "corrected_sentence": "这支队伍曾经有过很高的士气，赢了不少比赛。", "error_description": "量词错误：“只”用于动物或单个物件，不能修饰抽象名词“士气”；“士气”前不用个体量词，应去掉“一只”，说“有过很高的士气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
