INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在公司里工作的人。", "primary_collocate": null, "pronunciation": "yuán gōng", "ipa": "ɥɛn˧˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这家公司有三百多名员工。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工今天第一次来上班。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对员工很好，常请大家吃饭。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每位员工发了一份礼物。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工们下班后一起去吃饭。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们公司最努力的员工。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位员工在公司做了五年，大家都认识他。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在会议室和员工开会。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的员工上班时都要穿工作服。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，公司的员工都很忙。", "target_word": "员工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名员工", "label": "量词"}, {"form": "一位员工", "label": "量词"}, {"form": "新员工", "label": "复合"}, {"form": "老员工", "label": "复合"}, {"form": "員工", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：在公司工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "员工", "is_correct": true, "explanation": "员工：指在公司工作的人，与“三百多名”搭配且语义相符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指就医的人，不是公司的工作人员。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘车的人，公司里不会有“乘客”。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：量词“名”只用于人，不能用“名”来数“电脑”。"}], "explanations": {"员工": "员工：指在公司工作的人，与“三百多名”搭配且语义相符。", "病人": "语义：“病人”指就医的人，不是公司的工作人员。", "乘客": "语义：“乘客”指乘车的人，公司里不会有“乘客”。", "电脑": "搭配：量词“名”只用于人，不能用“名”来数“电脑”。"}, "sentence_index": 0, "correct_answer": "员工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用员工煮咖啡。", "explanation": "这里应该用〈咖啡机〉。“员工”指在单位工作的人，不能用来煮咖啡。"}, {"text": "他每天骑员工上班。", "explanation": "这里应该用〈自行车〉。“员工”指在单位工作的人，是人，不能骑，骑的应是自行车。"}, {"text": "这个村子里种着很多员工。", "explanation": "这里应该用〈树〉。“员工”指在单位工作的人，不能种，种的应是树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "员工", "is_correct": true, "explanation": "员工：指在公司工作的人，与“在公司做了五年”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”在校读书，不会“在公司做了五年”。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“位”只用于人，猫应该用“只”。"}, {"text": "产品", "is_correct": false, "explanation": "语义：“产品”是物品，不能在公司工作。"}], "explanations": {"员工": "员工：指在公司工作的人，与“在公司做了五年”相符。", "学生": "语义：“学生”在校读书，不会“在公司做了五年”。", "猫": "搭配：量词“位”只用于人，猫应该用“只”。", "产品": "语义：“产品”是物品，不能在公司工作。"}, "sentence_index": 6, "correct_answer": "员工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的员工都很努力。", "explanation": "这里应该用〈同学〉。“员工”指在单位工作的人，班里的学生不是员工。"}, {"text": "我喜欢吃员工。", "explanation": "这里应该用〈苹果〉。“员工”指在单位工作的人，是人，不能吃，要吃的应说苹果。"}, {"text": "他会唱很多员工。", "explanation": "这里应该用〈歌〉。“员工”指在单位工作的人，不能唱，唱的应是歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅有五十名员工们。", "corrected_sentence": "这家餐厅有五十名员工。", "error_description": "“五十名”已经表示数量，“员工”后面不能再加“们”表示复数，应说“五十名员工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司很努力员工都得到了奖金。", "corrected_sentence": "我们公司很努力的员工都得到了奖金。", "error_description": "“很努力”修饰“员工”，中间要用“的”连接，应说“很努力的员工”，不能说“很努力员工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
