INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发现就是第一次看到或知道一个东西。", "primary_collocate": null, "pronunciation": "fā xiàn", "ipa": "fa˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我在书包里发现了一把旧钥匙。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈发现孩子不在房间里。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很快就发现自己走错路了。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在她的血液里发现了问题。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明发现桌子下面有只小猫。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们发现这家店的菜很好吃。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有发现他今天很高兴？", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现我没有带作业本。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现了一种新的花。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开门，发现外面下雪了。", "target_word": "发现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发现了", "label": "体标"}, {"form": "发现过", "label": "体标"}, {"form": "發現", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第一次看到或知道某个东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发现", "is_correct": true, "explanation": "发现：表示第一次看到“一把旧钥匙”，与句意相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能以“钥匙”作宾语。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指花钱换东西，“在书包里买了钥匙”说不通。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”接门、箱子等，不能以“钥匙”作宾语。"}], "explanations": {"发现": "发现：表示第一次看到“一把旧钥匙”，与句意相符。", "煮": "搭配：“煮”的对象是食物，不能以“钥匙”作宾语。", "买": "语义：“买”指花钱换东西，“在书包里买了钥匙”说不通。", "打开": "搭配：“打开”接门、箱子等，不能以“钥匙”作宾语。"}, "sentence_index": 0, "correct_answer": "发现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古代中国人发现了造纸术。", "explanation": "这里应该用〈发明〉。发现指第一次看到或知道本来就存在的东西，造纸术是人创造出来的，要用发明。"}, {"text": "这件事发现了大家的注意。", "explanation": "这里应该用〈引起〉。“引起注意”是固定搭配，注意不是能被发现的东西。"}, {"text": "这家工厂每天发现五百台电脑。", "explanation": "这里应该用〈制造〉。发现指找到已经存在的东西，工厂生产的电脑要用制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发现", "is_correct": true, "explanation": "发现：表示察觉到“他今天很高兴”这件事，与句意相符。"}, {"text": "决定", "is_correct": false, "explanation": "搭配：“决定”后面接要作出的决策，不能接“他今天很高兴”这样的状态。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示让正在进行的动作结束，与“高兴”这种状态不搭。"}, {"text": "赞成", "is_correct": false, "explanation": "配价：“赞成”的宾语须是提议或看法，不能是“他今天很高兴”。"}], "explanations": {"发现": "发现：表示察觉到“他今天很高兴”这件事，与句意相符。", "决定": "搭配：“决定”后面接要作出的决策，不能接“他今天很高兴”这样的状态。", "停止": "语义：“停止”表示让正在进行的动作结束，与“高兴”这种状态不搭。", "赞成": "配价：“赞成”的宾语须是提议或看法，不能是“他今天很高兴”。"}, "sentence_index": 6, "correct_answer": "发现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于发现了这场比赛的胜利。", "explanation": "这里应该用〈取得〉。发现指找到本来就存在的东西，比赛的胜利要靠努力取得，不能说“发现”。"}, {"text": "两国发现了一场战争。", "explanation": "这里应该用〈爆发〉。发现指找到已经存在的东西，战争是突然爆发的，不能说“发现了一场战争”。"}, {"text": "我们班发现了一次很好的考试。", "explanation": "这里应该用〈举行〉。发现指找到已经存在的东西，考试是组织举行的，不能说“发现了一次考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在抽屉里发现到了一张照片。", "corrected_sentence": "我在抽屉里发现了一张照片。", "error_description": "错误：“发现到了”；正确：“发现了”。“发现”本身已表示找到，后面不需要再加结果补语“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在桌子下面发现着一只小猫。", "corrected_sentence": "我在桌子下面发现了一只小猫。", "error_description": "错误形式：“发现着”；正确形式：“发现了”。“发现”是一下子完成的动作，不能用表示持续的“着”，应当用表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
