INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根植就是像树的根一样，深深扎在土里。", "primary_collocate": null, "pronunciation": "gēn zhí", "ipa": "kən˥ ʈʂɹ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这棵老树深深根植于山边的土里。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子根植于湿湿的泥土中。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的柳树根植于水边的土里，长得很高。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的松树根植于石头中间，很多年都没有倒。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片草根植于深深的土里，所以冬天也不会死。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树根植于地下，风再大也不会倒。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树根植于院子里已经三年了，长得很快。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的小草根植于干土中，却一直活着。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红树林根植于海边的泥里，可以挡住大风。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花根植于花园的土里，不怕风吹。", "target_word": "根植", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "根植：树木等的根深深扎在土里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22620, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根植", "is_correct": true, "explanation": "根植：像树根一样深深扎在土里。"}, {"text": "根治", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，“根治”指从根本上彻底治愈。"}, {"text": "分值", "is_correct": false, "explanation": "fēn（第一声）与 gēn 只差声母，“分值”指分数的数值。"}, {"text": "真值", "is_correct": false, "explanation": "zhēn（第一声）与 gēn 只差声母，“真值”指命题的真假取值，是逻辑学用语。"}], "explanations": {"根植": "根植：像树根一样深深扎在土里。", "根治": "zhì（第四声）与 zhí（第二声）声调不同，“根治”指从根本上彻底治愈。", "分值": "fēn（第一声）与 gēn 只差声母，“分值”指分数的数值。", "真值": "zhēn（第一声）与 gēn 只差声母，“真值”指命题的真假取值，是逻辑学用语。"}, "sentence_index": null, "correct_answer": "根植"}, "level_3": {"options": [{"text": "根植", "is_correct": true, "explanation": "根植：树根深深扎入土中，与“深深”和“土里”搭配，说明树的生长状态。"}, {"text": "悬挂", "is_correct": false, "explanation": "语义：“悬挂”指吊在空中，与“山边的土里”的位置矛盾。"}, {"text": "散落", "is_correct": false, "explanation": "搭配：“散落”多指零散的东西，不能用来形容一棵老树。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：“漂浮”指浮在液体或空中，与“深深”扎入土里的意思相反。"}], "explanations": {"根植": "根植：树根深深扎入土中，与“深深”和“土里”搭配，说明树的生长状态。", "悬挂": "语义：“悬挂”指吊在空中，与“山边的土里”的位置矛盾。", "散落": "搭配：“散落”多指零散的东西，不能用来形容一棵老树。", "漂浮": "语义：“漂浮”指浮在液体或空中，与“深深”扎入土里的意思相反。"}, "sentence_index": 0, "correct_answer": "根植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子根植于山坡上，视野很好。", "explanation": "这里应该用〈坐落〉。根植指植物的根扎进土里，房屋应说坐落。"}, {"text": "这把椅子根植于客厅的中央。", "explanation": "这里应该用〈摆放〉。根植指植物的根扎进土里，椅子应说摆放。"}, {"text": "这台冰箱根植于厨房的墙角。", "explanation": "这里应该用〈放在〉。根植指植物的根扎进土里，冰箱没有根，不能根植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根植", "is_correct": true, "explanation": "根植：树根扎进土里，与“已经三年了”和“长得很快”的稳定生长状态一致。"}, {"text": "倒伏", "is_correct": false, "explanation": "搭配：“倒伏”多指庄稼或草被吹倒，不用来形容小树的生长状态。"}, {"text": "溶解", "is_correct": false, "explanation": "语义：“溶解”指溶入液体中，与院子里的土地和树木的生长不符。"}, {"text": "漂流", "is_correct": false, "explanation": "语义：“漂流”指随水流移动，与“已经三年了”的稳定扎根状态相反。"}], "explanations": {"根植": "根植：树根扎进土里，与“已经三年了”和“长得很快”的稳定生长状态一致。", "倒伏": "搭配：“倒伏”多指庄稼或草被吹倒，不用来形容小树的生长状态。", "溶解": "语义：“溶解”指溶入液体中，与院子里的土地和树木的生长不符。", "漂流": "语义：“漂流”指随水流移动，与“已经三年了”的稳定扎根状态相反。"}, "sentence_index": 6, "correct_answer": "根植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他根植了一个支架。", "explanation": "这里应该用〈植入〉。根植指植物的根扎进土里，医疗器械放入体内应说植入。"}, {"text": "小猫根植于窗台上。", "explanation": "这里应该用〈趴〉。根植只用于植物的根扎进土里，小猫不能根植，应说趴在窗台上。"}, {"text": "河水根植于湖里。", "explanation": "这里应该用〈流入〉。根植指植物扎根，河水没有根，应说流入湖里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片岩石根植于湖边的泥里。", "corrected_sentence": "这片芦苇根植于湖边的泥里。", "error_description": "错误在于主语：根植指植物的根扎进土里，岩石没有根，不能用“根植”。应把主语换成植物，如“芦苇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小树深深根植了于院子里。", "corrected_sentence": "小树深深根植于院子里。", "error_description": "“根植于”是固定结构，“根植”与“于”之间不能加“了”，应去掉“了”，说“深深根植于院子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高涨", "is_correct": true, "explanation": "反义：“低落”指情绪下降，“高涨”指情绪上升，二者相对。"}, {"text": "清澈", "is_correct": false, "explanation": "无关：“清澈”形容水或眼神等透明明亮，与“低落”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：“陡峭”形容地势，与情绪无关。"}, {"text": "干燥", "is_correct": false, "explanation": "无关：“干燥”形容含水量少，与“低落”没有反义关系。"}], "correct_answer": "高涨", "explanations": {"高涨": "反义：“低落”指情绪下降，“高涨”指情绪上升，二者相对。", "清澈": "无关：“清澈”形容水或眼神等透明明亮，与“低落”没有反义关系。", "陡峭": "无关：“陡峭”形容地势，与情绪无关。", "干燥": "无关：“干燥”形容含水量少，与“低落”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高涨", "is_correct": true, "explanation": "反义：“低落”指情绪下降，“高涨”指情绪上升，二者构成反义。"}, {"text": "松软", "is_correct": false, "explanation": "无关：“松软”形容质地，与情绪无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：“粗糙”形容表面质感，与“低落”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：“寒冷”形容温度，与情绪、心情无关。"}], "correct_answer": "高涨", "explanations": {"高涨": "反义：“低落”指情绪下降，“高涨”指情绪上升，二者构成反义。", "松软": "无关：“松软”形容质地，与情绪无关。", "粗糙": "无关：“粗糙”形容表面质感，与“低落”没有反义关系。", "寒冷": "无关：“寒冷”形容温度，与情绪、心情无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心情不好，像气球漏了气。", "primary_collocate": null, "pronunciation": "dī luò", "ipa": "ti˥ lu̯ɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他今天心情低落，一句话也不想说。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友走了以后，我一直很低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到成绩，她的情绪立刻低落了。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么低落？有什么事吗？", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天他总是有点低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生病，我这几天情绪很低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟丢了玩具，整天都很低落。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她考试失败后，情绪低落了好几天。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别低落了，我们去吃好吃的吧。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很低落，大概没睡好。", "target_word": "低落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情绪低落", "label": "复合"}], "register": "中性", "sense_fingerprint": "心情不好像气球漏气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高涨", "is_correct": false, "explanation": "语义：“高涨”表示情绪昂扬，与“一句话也不想说”的语境矛盾。"}, {"text": "低落", "is_correct": true, "explanation": "低落：心情不好、情绪下降，与“一句话也不想说”的语境相符。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用来修饰心情。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的体态，不能用来形容心情。"}], "explanations": {"高涨": "语义：“高涨”表示情绪昂扬，与“一句话也不想说”的语境矛盾。", "低落": "低落：心情不好、情绪下降，与“一句话也不想说”的语境相符。", "宽敞": "搭配：“宽敞”形容空间，不能用来修饰心情。", "苗条": "体貌：“苗条”形容人的体态，不能用来形容心情。"}, "sentence_index": 0, "correct_answer": "低落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的高度低落了两米。", "explanation": "这里应该用〈降低〉。低落多形容情绪、士气或业绩，不用于建筑的高度。"}, {"text": "这个小区的住户低落了许多。", "explanation": "这里应该用〈减少〉。低落用于情绪，住户数量减少要用减少。"}, {"text": "这台机器的噪音低落了一半。", "explanation": "这里应该用〈减弱〉。低落多形容情绪、士气或业绩，不用于噪音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度，不能用来说心情。"}, {"text": "低落", "is_correct": true, "explanation": "低落：心情不好、情绪下降，与“弟弟丢了玩具”的语境相符。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”形容线条或姿态，不能修饰心情。"}, {"text": "清秀", "is_correct": false, "explanation": "体貌：“清秀”形容人的相貌，不能用来形容心情。"}], "explanations": {"滚烫": "搭配：“滚烫”形容温度，不能用来说心情。", "低落": "低落：心情不好、情绪下降，与“弟弟丢了玩具”的语境相符。", "笔直": "搭配：“笔直”形容线条或姿态，不能修饰心情。", "清秀": "体貌：“清秀”形容人的相貌，不能用来形容心情。"}, "sentence_index": 6, "correct_answer": "低落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的风力低落了很多。", "explanation": "这里应该用〈减弱〉。低落用于情绪、心情，风力、力度减弱要用减弱。"}, {"text": "这辆汽车的时速低落了一半。", "explanation": "这里应该用〈减慢〉。低落用于情绪、心情，车速降低要用减慢。"}, {"text": "这盏灯的亮度低落了一半。", "explanation": "这里应该用〈减弱〉。低落多形容情绪、士气或业绩，不用于亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这个消息，她的心情低落了得不想说话。", "corrected_sentence": "听到这个消息，她的心情低落得不想说话。", "error_description": "错误：“低落”作程度补语时，“得”之前不能再加“了”。正确说法：“她的心情低落得不想说话。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近他总是把心情低落，谁也不理。", "corrected_sentence": "最近他总是心情低落，谁也不理。", "error_description": "错误：“低落”是形容词，不能作“把”字句的谓语，句中多出了“把”。正确说法：“最近他总是心情低落，谁也不理。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
