INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "想法，对东西的认识。", "primary_collocate": null, "pronunciation": "gài niàn", "ipa": "kaɪ˥˩ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个概念很难懂。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了时间的概念。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对钱没有什么概念。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还没有数字的概念。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个新概念。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太清楚这个概念的意思。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里先说明了几个重要的概念。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对安全的概念很清楚。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用简单的话解释这个概念。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概念来自国外。", "target_word": "概念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "概念化", "label": "复合"}, {"form": "概念图", "label": "复合"}], "register": "中性", "sense_fingerprint": "概念：对事物的认识和基本想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概念", "is_correct": true, "explanation": "正确：概念指对事物的认识，是可以被理解的内容，与“很难懂”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感官感受，不是需要理解的内容，不能说“难懂”。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：长相描写外表，与“难懂”的语义不合。"}, {"text": "外套", "is_correct": false, "explanation": "语义：外套是衣物，不是需要理解的对象。"}], "explanations": {"概念": "正确：概念指对事物的认识，是可以被理解的内容，与“很难懂”搭配。", "味道": "语义：味道是感官感受，不是需要理解的内容，不能说“难懂”。", "长相": "体貌：长相描写外表，与“难懂”的语义不合。", "外套": "语义：外套是衣物，不是需要理解的对象。"}, "sentence_index": 0, "correct_answer": "概念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对未来充满概念。", "explanation": "这里应该用〈信念〉。概念指对事物的认识，对未来坚定的相信要用信念。"}, {"text": "他把概念放进了冰箱里。", "explanation": "这里应该用〈食物〉。概念是抽象的认识，不能放进冰箱，能放进冰箱的是食物。"}, {"text": "妈妈在厨房里做了一个概念。", "explanation": "这里应该用〈蛋糕〉。概念是抽象的认识，不能做出来，能做出来的是蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概念", "is_correct": true, "explanation": "正确：概念是可以被说明的认识内容，与“重要的”和“说明”搭配。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是哭时流出的液体，不能被“说明”为概念。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色描写人的外表神情，不能作为书里要说明的内容。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指是身体的部位，书里不能把它说明成“重要的”内容。"}], "explanations": {"概念": "正确：概念是可以被说明的认识内容，与“重要的”和“说明”搭配。", "眼泪": "语义：眼泪是哭时流出的液体，不能被“说明”为概念。", "脸色": "体貌：脸色描写人的外表神情，不能作为书里要说明的内容。", "手指": "语义：手指是身体的部位，书里不能把它说明成“重要的”内容。"}, "sentence_index": 6, "correct_answer": "概念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气把这个概念喝完了。", "explanation": "这里应该用〈牛奶〉。概念是抽象的认识，不能喝，能喝的是牛奶。"}, {"text": "我们去超市买了一个概念。", "explanation": "这里应该用〈东西〉。概念是抽象的认识，不能像东西一样买。"}, {"text": "他每天在厨房里用概念做饭。", "explanation": "这里应该用〈食材〉。概念是抽象的认识，不能当作做饭的材料，做饭用的是食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚学会一把新概念。", "corrected_sentence": "他刚学会一个新概念。", "error_description": "“把”用于有柄或有把手的东西，“概念”应该用量词“个”，应说“一个新概念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对国家的概念们很模糊。", "corrected_sentence": "他对国家的概念很模糊。", "error_description": "“们”只用于指人的名词，“概念”是抽象名词，不能加“们”表示复数，应说“国家的概念”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
