INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让东西变得更新、更好的过程。", "primary_collocate": null, "pronunciation": "xiàn dài huà", "ipa": "ɕjɛn⁵¹ taɪ⁵¹ xwa⁵¹", "syllable_count": 3, "sentences": [{"text": "这个国家正在走向现代化。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代化需要很多时间。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的现代化让生活更方便。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想实现农业现代化。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府大力推动农村的现代化。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代化不是一天就能完成的。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的现代化离不开教育。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的现代化速度很快。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，现代化带来了很多变化。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究中国的现代化。", "target_word": "现代化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现代化建设", "label": "复合"}, {"form": "现代化的", "label": "复合"}, {"form": "現代化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使国家、城市、行业变得新而先进的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代化", "is_correct": true, "explanation": "正确：「现代化」指国家变得新而先进的过程，可以“走向”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：国家不能走向“厨房”这样的房间。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「走向」后接方向或状态，不能接“数学”这类学科。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：「冰箱」是家用电器，国家不能走向冰箱。"}], "explanations": {"现代化": "正确：「现代化」指国家变得新而先进的过程，可以“走向”。", "厨房": "语义：国家不能走向“厨房”这样的房间。", "数学": "搭配：「走向」后接方向或状态，不能接“数学”这类学科。", "冰箱": "语义：「冰箱」是家用电器，国家不能走向冰箱。"}, "sentence_index": 0, "correct_answer": "现代化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的现代化很快。", "explanation": "这里应该用〈成长〉。现代化用于国家、社会和行业，个人身体与能力的发展要说“成长”。"}, {"text": "他买了一台现代化。", "explanation": "语义：「现代化」指变革的过程，不是可以用“台”计量的物品。"}, {"text": "我们每天都要现代化作业。", "explanation": "搭配：「现代化」不与“作业”搭配，应说“完成作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代化", "is_correct": true, "explanation": "正确：「现代化」是国家发展的过程，与“离不开教育”搭配，符合句意。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：国家的发展不能“离不开”一只小猫。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：「红绿灯」是交通设施，与国家发展的条件无关。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：「离不开」多与“经济、科技、人才”等搭配，“足球”不用这样搭配。"}], "explanations": {"现代化": "正确：「现代化」是国家发展的过程，与“离不开教育”搭配，符合句意。", "小猫": "语义：国家的发展不能“离不开”一只小猫。", "红绿灯": "语义：「红绿灯」是交通设施，与国家发展的条件无关。", "足球": "搭配：「离不开」多与“经济、科技、人才”等搭配，“足球”不用这样搭配。"}, "sentence_index": 6, "correct_answer": "现代化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喝了一杯现代化。", "explanation": "语义：「现代化」是变革的过程，不可饮用，不能用“杯”计量。"}, {"text": "他看了一场现代化。", "explanation": "语义：这里把“现代化”当成了可以观看的演出或节目，“现代化”指让东西变得更新、更好的过程，不是可以观看的演出。"}, {"text": "这把椅子的现代化很快。", "explanation": "语义：「现代化」用于国家、社会和行业，不能用于一把椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家正在进行了现代化。", "corrected_sentence": "这个国家正在进行现代化。", "error_description": "错误：“正在进行了现代化”。正确：“正在进行现代化”。“正在”表示动作进行中，不能与“了”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都关心农村的一只现代化。", "corrected_sentence": "我们都关心农村的现代化。", "error_description": "错误：“一只现代化”。正确：“现代化”。“现代化”是抽象的过程，不能用量词“只”来计量，应说“我们都关心农村的现代化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
