INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22628, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个国家的人到别的地方住下来，管那里的人。", "primary_collocate": null, "pronunciation": "zhí mín", "ipa": "ʈʂʐ̩˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "很多欧洲人坐船到美洲殖民，管着当地人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来到这里殖民，让当地人听自己的。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，有些国家的人到海外殖民，住下来管那里的人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来到这个岛上殖民，还管着当地人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王派了一千人去远方殖民，管那里的人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些人去南方殖民，想管那里的人。", "target_word": "殖民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几百年前，有人到这片海边殖民过，还管过当地人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么有的国家的人要去别处殖民，还要管别人呢？", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先在海边殖民，住下来后开始管当地人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百年前，这个国家的人到别的大陆殖民，管着当地人。", "target_word": "殖民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殖民了", "label": "体标"}, {"form": "殖民过", "label": "体标"}, {"form": "殖民地", "label": "复合"}, {"form": "殖民者", "label": "复合"}], "register": "书面", "sense_fingerprint": "一国的人迁到别处定居并管理当地人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殖民", "is_correct": true, "explanation": "殖民：迁到别处定居并管理当地人，与“管着当地人”相符。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”是短暂拜访，与“还管着当地人”的持续管理矛盾。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”是观光行为，与“管着当地人”的统治义不符。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”后接的是权利、机会等，不能用来表示“到美洲去做某事”。"}], "explanations": {"殖民": "殖民：迁到别处定居并管理当地人，与“管着当地人”相符。", "访问": "语义：“访问”是短暂拜访，与“还管着当地人”的持续管理矛盾。", "游览": "语义：“游览”是观光行为，与“管着当地人”的统治义不符。", "放弃": "搭配：“放弃”后接的是权利、机会等，不能用来表示“到美洲去做某事”。"}, "sentence_index": 0, "correct_answer": "殖民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一家人殖民到了郊区，那里的环境很好。", "explanation": "这里应该用〈搬迁〉。殖民除了迁居，还要管理当地人；一家人搬到郊区不涉及管理。"}, {"text": "学生们殖民了科技馆，认真地看了每一件展品。", "explanation": "这里应该用〈参观〉。殖民指迁入并管理当地人，参观场馆要用参观。"}, {"text": "他在那家公司殖民了十年，一直很努力。", "explanation": "这里应该用〈工作〉。殖民强调迁入并管理当地人，在公司任职要用工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殖民", "is_correct": true, "explanation": "殖民：迁到别处并管理当地人，与“还管过当地人”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是闲逛的行为，与“还管过当地人”的管理义不符。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”指弄脏环境，与句中管理当地人的内容不相合。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：“逃避”后接的应是责任、困难，不能直接接地点“这片海边”。"}], "explanations": {"殖民": "殖民：迁到别处并管理当地人，与“还管过当地人”相符。", "散步": "语义：“散步”是闲逛的行为，与“还管过当地人”的管理义不符。", "污染": "语义：“污染”指弄脏环境，与句中管理当地人的内容不相合。", "逃避": "搭配：“逃避”后接的应是责任、困难，不能直接接地点“这片海边”。"}, "sentence_index": 6, "correct_answer": "殖民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外交官殖民了那个国家，待了三天就回来了。", "explanation": "这里应该用〈访问〉。殖民需要迁入并管理当地人，外交官的短暂到访不属于殖民。"}, {"text": "他在国外殖民了二十年，很习惯那里的饮食。", "explanation": "这里应该用〈生活〉。殖民强调迁入并管理当地人，一般的长期居住要用生活。"}, {"text": "他在街角殖民了一家小店，每天都很忙。", "explanation": "这里应该用〈开〉。殖民的对象是地区，不能用于一家小店这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一批英国人来到印度殖民了过，还管着当地的百姓。", "corrected_sentence": "一批英国人来到印度殖民，还管着当地的百姓。", "error_description": "“殖民”后面不能同时用“了”和“过”两个体标，应去掉“了过”，说“来到印度殖民，还管着当地的百姓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几十年前，有的国家派人到南亚殖民者，管理当地的人。", "corrected_sentence": "几十年前，有的国家派人到南亚殖民，管理当地的人。", "error_description": "“殖民者”是名词，指施行殖民的人；这里要用动词“殖民”，应说“派人到南亚殖民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
