INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22630, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人非要给你一个你不想要的东西。", "primary_collocate": null, "pronunciation": "qiáng jiā", "ipa": "tɕʰjɑŋ˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "同事把他的工作强加给我，我一点也不想做。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把你不喜欢的活儿强加给我。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想接受，他却一直强加给我。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把很多不合理的要求强加给我们。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都不喜欢别人强加的东西。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有问我愿不愿意，就把工作强加给我了。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居把自己的规矩强加给我们，大家很不满。", "target_word": "强加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是你强加给我的责任，我不想要。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拒绝了朋友强加给她的安排。", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经说不要了，你为什么还强加给我？", "target_word": "强加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "强加了", "label": "体标"}, {"form": "强加过", "label": "体标"}], "register": "中性", "sense_fingerprint": "别人硬把你不想要的工作、责任等推给你", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强加", "is_correct": true, "explanation": "强加：把工作硬推给我，与“我一点也不想做”相符。"}, {"text": "归还", "is_correct": false, "explanation": "语义：“归还”指把原本属于对方的东西还回去，与“他的工作”的所属关系矛盾。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的对象是申请、计划，不能用来表示把工作交给我。"}, {"text": "欣赏", "is_correct": false, "explanation": "配价：“欣赏”是及物动词，不能组成“把……给我”的转移结构。"}], "explanations": {"强加": "强加：把工作硬推给我，与“我一点也不想做”相符。", "归还": "语义：“归还”指把原本属于对方的东西还回去，与“他的工作”的所属关系矛盾。", "批准": "搭配：“批准”的对象是申请、计划，不能用来表示把工作交给我。", "欣赏": "配价：“欣赏”是及物动词，不能组成“把……给我”的转移结构。"}, "sentence_index": 0, "correct_answer": "强加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢这本书，朋友却把它强加给了我。", "explanation": "这里应该用〈借给〉。强加指硬加给人不想要的东西，与“我很喜欢这本书”矛盾。"}, {"text": "老师在课堂上推荐了这本书，同学们都很喜欢，老师把它强加给大家。", "explanation": "这里应该用〈介绍〉。强加指硬加给人不想要的东西，与“同学们都很喜欢”矛盾。"}, {"text": "这份工作很有挑战，我很想接手，经理却把它强加给了我。", "explanation": "这里应该用〈交给〉。强加指硬加给人不想要的东西，“我很想接手”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强加", "is_correct": true, "explanation": "强加：把规矩硬加给我们，与“大家很不满”相符。"}, {"text": "放弃", "is_correct": false, "explanation": "配价：“放弃”不能带“给”引出接受者，不能用来转交规矩。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”的对象是活动、仪式，不能说“把规矩举行给我们”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，与“把规矩……给我们”的动作不相合。"}], "explanations": {"强加": "强加：把规矩硬加给我们，与“大家很不满”相符。", "放弃": "配价：“放弃”不能带“给”引出接受者，不能用来转交规矩。", "举行": "搭配：“举行”的对象是活动、仪式，不能说“把规矩举行给我们”。", "忘记": "语义：“忘记”指记不住，与“把规矩……给我们”的动作不相合。"}, "sentence_index": 6, "correct_answer": "强加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想学习，老师却把这个机会强加给了我。", "explanation": "这里应该用〈给予〉。强加指硬加给人不想要的东西，与“我很想学习”矛盾。"}, {"text": "朋友很想听他的心里话，他却把它强加给了朋友。", "explanation": "这里应该用〈倾诉〉。强加指硬加给人不想要的东西，朋友很想听，与之矛盾。"}, {"text": "我们把这个计划强加给了大家，大家都同意了。", "explanation": "这里应该用〈讨论〉。强加指硬加给人不想要的东西，与“大家都同意了”矛盾，计划应经讨论再定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈不管我的想法，总是把她的安排强加对我。", "corrected_sentence": "妈妈不管我的想法，总是把她的安排强加给我。", "error_description": "“强加”引出接受者要用“给”，不能用“对”，应说“强加给我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把任务强加了给我，大家都没有意见。", "corrected_sentence": "老师把任务强加给了我，大家都没有意见。", "error_description": "“了”表示完成，应放在“给”之后，说“强加给了我”，不能插在“强加”与“给”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
