INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一段时间。", "primary_collocate": null, "pronunciation": "shí duàn", "ipa": "ʂʐ̩˧˥ twan˥˩", "syllable_count": 2, "sentences": [{"text": "早上这个时段，公园里有很多老人。", "target_word": "时段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时段孩子们都在学校。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你喜欢在哪个时段去健身房？", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中午是一天里最热的时段。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上的这个时段，路上的人不多。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家电影院每个时段的票价都不同。", "target_word": "时段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时段我有空，你可以来找我。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我你方便的时段。", "target_word": "时段", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一天有三个时段，我最喜欢晚上。", "target_word": "时段", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午两点到四点这个时段，我最想睡觉。", "target_word": "时段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "高峰时段", "label": "复合"}, {"form": "時段", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一天里某一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时段", "is_correct": true, "explanation": "时段指一段时间，“早上这个时段”指早晨的这一段时间，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“早上”是时间，“价格”不是时间范围，“早上这个价格”句意不通。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”不表示时间，不能用“早上这个方向”来指一段时间。"}, {"text": "型号", "is_correct": false, "explanation": "搭配：“这个型号”不能与“早上”搭配，型号不能用来指一段时间。"}], "explanations": {"时段": "时段指一段时间，“早上这个时段”指早晨的这一段时间，符合句意。", "价格": "语义：“早上”是时间，“价格”不是时间范围，“早上这个价格”句意不通。", "方向": "语义：“方向”不表示时间，不能用“早上这个方向”来指一段时间。", "型号": "搭配：“这个型号”不能与“早上”搭配，型号不能用来指一段时间。"}, "sentence_index": 0, "correct_answer": "时段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车八点整开车，这个时段正好是八点整。", "explanation": "这里应该用〈时刻〉。时刻指一个具体的时间点，“八点整”是一个点；时段指一段时间范围，不能说“这个时段正好是八点整”。"}, {"text": "我每天花很多时段散步。", "explanation": "这里应该用〈时间〉。时段指划分出来的某段时间范围，不用来泛指散步所花的时间；“花很多时段”不自然。"}, {"text": "她的青春时段是在国外度过的，很充实。", "explanation": "这里应该用〈时期〉。时期指较长、有特点的一段阶段，如青春时期；时段指较短、划分出来的时间范围，不能指一个人整段青春。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时段", "is_correct": true, "explanation": "时段指一段时间，“这个时段我有空”指这段时间我有空闲，符合句意。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“有空”说的是时间，“地址”不是时间范围，“地址我有空”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“有空”所说的时间无关，句意不通。"}, {"text": "尺码", "is_correct": false, "explanation": "搭配：“这个尺码我有空”无法成立，尺码不能与“有空”搭配。"}], "explanations": {"时段": "时段指一段时间，“这个时段我有空”指这段时间我有空闲，符合句意。", "地址": "语义：“有空”说的是时间，“地址”不是时间范围，“地址我有空”句意不通。", "颜色": "语义：“颜色”与“有空”所说的时间无关，句意不通。", "尺码": "搭配：“这个尺码我有空”无法成立，尺码不能与“有空”搭配。"}, "sentence_index": 6, "correct_answer": "时段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要抓住时段，尽快签约。", "explanation": "这里应该用〈时机〉。“抓住”搭配的是机会或时机；时段指时间范围，不能被“抓住”。"}, {"text": "这条路的第二时段最窄。", "explanation": "这里应该用〈路段〉。路段指道路上划分出来的一段，是空间范围；时段指时间上的一段范围，不能用来说道路的一段。"}, {"text": "他按下快门的时段，阳光正好照在脸上。", "explanation": "这里应该用〈瞬间〉。按快门是一个瞬间的动作，指一个时间点；时段指一段时间范围，不能用于指瞬间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条时段我们都在图书馆学习。", "corrected_sentence": "那个时段我们都在图书馆学习。", "error_description": "量词错误：“时段”的量词应用“个”，不能用“条”（“条”多用于河、路、鱼等）；应说“那个时段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚这个的时段，街上很热闹。", "corrected_sentence": "傍晚这个时段，街上很热闹。", "error_description": "语法错误：“这个”与名词之间不能加“的”，应说“这个时段”；“的”加在“这个”后面会破坏量词短语的结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
