INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事生产或经营的单位，如工厂、公司。", "primary_collocate": null, "pronunciation": "qǐ yè", "ipa": "tɕʰi˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这家企业有两百个工人。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家大企业工作。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市有很多企业。", "target_word": "企业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家企业做衣服，也卖衣服。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小企业也需要好的工人。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸想自己开一家企业。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家企业的东西卖到了国外。", "target_word": "企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后进了一家汽车企业。", "target_word": "企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业的老板对工人很好。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些企业每年都招新人。", "target_word": "企业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "企业家", "label": "复合"}, {"form": "国有企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "从事生产或经营的单位，如工厂、公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企业", "is_correct": true, "explanation": "正确：“企业”指从事生产或经营的单位，这里说这家单位有两百个工人。"}, {"text": "家庭", "is_correct": false, "explanation": "语义：家庭里的成员不叫工人，家庭不会“有两百个工人”。"}, {"text": "文章", "is_correct": false, "explanation": "搭配：“这家”用于店铺、公司等，不能指文章，应说“这篇文章”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是人，不是单位，不能说“这家学生有两百个工人”。"}], "explanations": {"企业": "正确：“企业”指从事生产或经营的单位，这里说这家单位有两百个工人。", "家庭": "语义：家庭里的成员不叫工人，家庭不会“有两百个工人”。", "文章": "搭配：“这家”用于店铺、公司等，不能指文章，应说“这篇文章”。", "学生": "语义：“学生”是人，不是单位，不能说“这家学生有两百个工人”。"}, "sentence_index": 0, "correct_answer": "企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家企业制定了全市的法律。", "explanation": "这里应该用〈政府〉。“企业”指从事生产或经营的单位，不能制定法律；制定全市的法律要用〈政府〉。"}, {"text": "这家企业判了很多案子。", "explanation": "这里应该用〈法院〉。“企业”不做审判工作，判案子要用〈法院〉。"}, {"text": "这个企业的人口超过了一千万。", "explanation": "这里应该用〈城市〉。“企业”指经营单位，不能说人口；说一个地方的人口多要用〈城市〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企业", "is_correct": true, "explanation": "正确：“企业”是生产或卖东西的单位，这里说这家单位的东西卖到了国外。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不生产也不卖东西，也不能用“家”来计量，这句话说的是卖到国外的商品。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不会卖东西，也不是一家单位，不能说“这家动物的东西”。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“这家”用于店铺、单位，不用于诗歌，应说“这首诗歌”。"}], "explanations": {"企业": "正确：“企业”是生产或卖东西的单位，这里说这家单位的东西卖到了国外。", "天空": "语义：天空不生产也不卖东西，也不能用“家”来计量，这句话说的是卖到国外的商品。", "动物": "语义：动物不会卖东西，也不是一家单位，不能说“这家动物的东西”。", "诗歌": "搭配：“这家”用于店铺、单位，不用于诗歌，应说“这首诗歌”。"}, "sentence_index": 6, "correct_answer": "企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个企业的冬天特别冷。", "explanation": "这里应该用〈地方〉。“企业”指从事生产或经营的单位，不能用来说气候；说哪里的冬天冷要用〈地方〉。"}, {"text": "他一辈子的企业就是教书。", "explanation": "这里应该用〈事业〉。“企业”指经营性单位，不表示一生追求的事业；说一生的追求要用〈事业〉。"}, {"text": "这家企业派了很多士兵去前线。", "explanation": "这里应该用〈军队〉。“企业”指经营单位，不能派兵上前线；派士兵作战要用〈军队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在一条外贸企业工作。", "corrected_sentence": "我姐姐在一家外贸企业工作。", "error_description": "“企业”要用量词“家”，“条”只用于长的东西，应说“一家外贸企业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈在一家国有企业的当会计。", "corrected_sentence": "我妈妈在一家国有企业当会计。", "error_description": "“企业”后面不能加“的”再接动词，“的”多余，应说“在一家国有企业当会计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
