INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人住在一起的地方。", "primary_collocate": null, "pronunciation": "shè qū", "ipa": "ʂɤ˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "我家住在一个大社区里。", "target_word": "社区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "社区里有很多老人。", "target_word": "社区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们社区有一个小公园。", "target_word": "社区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末社区有活动，我想去看看。", "target_word": "社区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区的医院离我家很近。", "target_word": "社区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "社区的孩子们放学后都在公园里玩。", "target_word": "社区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区的人都很喜欢这位新来的医生。", "target_word": "社区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我们社区里有很多人在一起包饺子。", "target_word": "社区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚搬来这个社区，还不认识邻居。", "target_word": "社区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区门口新开了一家超市，买东西很方便。", "target_word": "社区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个社区", "label": "量词（个）"}, {"form": "社区医院", "label": "复合"}, {"form": "社区服务", "label": "复合"}, {"form": "社区活动", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多人住在一起、互相来往的生活区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "社区", "is_correct": true, "explanation": "社区（shè qū）：很多人住在一起的地方，即目标词。"}, {"text": "市区", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），意思是城市的中心区域，不是社区。"}, {"text": "舍去", "is_correct": false, "explanation": "shě qù 与 shè qū 声母韵母相同，两个音节的声调都不同，意思是丢掉，不是社区。"}, {"text": "摄取", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是吸收，不是社区。"}], "explanations": {"社区": "社区（shè qū）：很多人住在一起的地方，即目标词。", "市区": "shì 与 shè 韵母不同（i 与 e），意思是城市的中心区域，不是社区。", "舍去": "shě qù 与 shè qū 声母韵母相同，两个音节的声调都不同，意思是丢掉，不是社区。", "摄取": "qǔ（第三声）与 qū（第一声）声调不同，意思是吸收，不是社区。"}, "sentence_index": null, "correct_answer": "社区"}, "level_3": {"options": [{"text": "社区", "is_correct": true, "explanation": "正确：「社区」是居民居住的地方，「住在一个大社区里」通顺。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的场所，不是住处，「住在公园里」不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不是住处，「住在教室里」不通。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，不能用来住人。"}], "explanations": {"社区": "正确：「社区」是居民居住的地方，「住在一个大社区里」通顺。", "公园": "语义：公园是供人游玩的场所，不是住处，「住在公园里」不通。", "教室": "语义：教室是上课的地方，不是住处，「住在教室里」不通。", "图书馆": "语义：图书馆是借阅书籍的地方，不能用来住人。"}, "sentence_index": 0, "correct_answer": "社区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的新邻居住在一条社区里。", "explanation": "这里应该用〈个〉。社区是地方，量词用「个」，「条」用于河流、道路等。"}, {"text": "我的社区昨天生病了，我们带它去了医院。", "explanation": "这里应该用〈狗〉。「社区」是地方，不能生病；指动物要说「狗」。"}, {"text": "这项政策帮助社区长高了。", "explanation": "这里应该用〈孩子〉。「社区」指居住的地方，不能长高；说人长高要用指人的「孩子」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社区", "is_correct": true, "explanation": "正确：「社区」是地点，可以作「的人」的修饰语，「社区的人都很喜欢」通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，「石头的人」不通，也没有人群可以喜欢医生。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人群，「空气的人」不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是地点或人群，不能作「的人」的修饰语。"}], "explanations": {"社区": "正确：「社区」是地点，可以作「的人」的修饰语，「社区的人都很喜欢」通顺。", "石头": "语义：石头是无生命的物体，「石头的人」不通，也没有人群可以喜欢医生。", "空气": "语义：空气不是人群，「空气的人」不通。", "声音": "语义：声音不是地点或人群，不能作「的人」的修饰语。"}, "sentence_index": 6, "correct_answer": "社区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天用社区写了作业。", "explanation": "这里应该用〈本子〉。「社区」指居住的地方，不能用来写字；写作业要用「本子」。"}, {"text": "他是我的社区。", "explanation": "这里应该用〈邻居〉。社区指居住的地方，不能指人；指人要说「邻居」。"}, {"text": "我们社区吃了一个苹果。", "explanation": "这里应该用〈居民〉。「社区」是地点，不能做「吃」的主语，要用指人的「居民」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近有一家社区。", "corrected_sentence": "我家附近有一个社区。", "error_description": "错误：「一家社区」量词用错，「家」用于企业、商店等单位；正确：「一个社区」，社区是地方，量词用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些社区们都很大。", "corrected_sentence": "这些社区都很大。", "error_description": "错误：「社区们」，后缀「们」只用于指人，社区不能加「们」；正确：「这些社区都很大」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
