INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22640, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22640, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容时间非常准，一点都没有错。", "primary_collocate": null, "pronunciation": "fēn miǎo bù chā", "ipa": "fən˥ miɑʊ˨˩ pu˥˩ tʂʰa˥", "syllable_count": 4, "sentences": [{"text": "公交车每次到站都分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回家的时间总是分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下课就下课，分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台的广告时间分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把煮蛋的时间算得分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落的时间分秒不差，大家很满意。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个闹钟每天都响得分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对好表之后，行动分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁发车时间分秒不差，上班族很放心。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长每天到校的时间分秒不差。", "target_word": "分秒不差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "时间非常准，一点错也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分秒不差", "is_correct": true, "explanation": "“都”之后接形容词谓语，“分秒不差”说到站时间极其准确，与“每次”相呼应。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：“到站”指时刻，不能说“漫长”，句子不成立。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”指不加约束，与公交车准时到站的意思相反。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：“混乱”指无序，与“每次都”体现的规律性相矛盾。"}], "explanations": {"分秒不差": "“都”之后接形容词谓语，“分秒不差”说到站时间极其准确，与“每次”相呼应。", "漫长": "搭配：“到站”指时刻，不能说“漫长”，句子不成立。", "随意": "语义：“随意”指不加约束，与公交车准时到站的意思相反。", "混乱": "语义：“混乱”指无序，与“每次都”体现的规律性相矛盾。"}, "sentence_index": 0, "correct_answer": "分秒不差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份证据分秒不差，无可辩驳。", "explanation": "这里应该用〈确凿〉。分秒不差只形容时间非常准，证据不是时间，应说确凿。"}, {"text": "这篇论文的论证分秒不差。", "explanation": "这里应该用〈严谨〉。分秒不差只形容时间，论证的周密要说严谨。"}, {"text": "这家工厂的零件尺寸分秒不差。", "explanation": "这里应该用〈精确〉。分秒不差限于时间，零件尺寸是数量，要说精确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分秒不差", "is_correct": true, "explanation": "“响得”后接补语，说明闹钟响的精确程度，“分秒不差”与“每天都”相呼应。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不出声，与闹钟准时响的意思不符，句意矛盾。"}, {"text": "狡猾", "is_correct": false, "explanation": "搭配：“狡猾”只用于形容人或动物的性格，不能形容闹钟的响声。"}, {"text": "慵懒", "is_correct": false, "explanation": "语义：“慵懒”指懒散，与按时响铃的精确性不符。"}], "explanations": {"分秒不差": "“响得”后接补语，说明闹钟响的精确程度，“分秒不差”与“每天都”相呼应。", "沉默": "语义：“沉默”指不出声，与闹钟准时响的意思不符，句意矛盾。", "狡猾": "搭配：“狡猾”只用于形容人或动物的性格，不能形容闹钟的响声。", "慵懒": "语义：“慵懒”指懒散，与按时响铃的精确性不符。"}, "sentence_index": 6, "correct_answer": "分秒不差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对朋友的感情分秒不差。", "explanation": "这里应该用〈真挚〉。分秒不差只形容时间，感情的诚恳要说真挚。"}, {"text": "这位工匠的手艺分秒不差。", "explanation": "这里应该用〈精湛〉。分秒不差只形容时间，手艺的高超要说精湛。"}, {"text": "这段话的表达分秒不差。", "explanation": "这里应该用〈清晰〉。分秒不差只形容时间，表达的明白程度要说清晰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这班列车分秒不差运行时间让乘客很满意。", "corrected_sentence": "这班列车分秒不差的运行时间让乘客很满意。", "error_description": "“分秒不差运行时间”缺少定语标记“的”。四字形容词修饰名词时要加“的”，应说“分秒不差的运行时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这班高铁每天都开分秒不差，乘客很放心。", "corrected_sentence": "这班高铁每天都开得分秒不差，乘客很放心。", "error_description": "“开分秒不差”缺少补语标记“得”。应说“开得分秒不差”，“得”引出补语，说明行车的准确程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
