INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指很远的地方。", "primary_collocate": null, "pronunciation": "yuǎn chéng", "ipa": "ɥɛn˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这架飞机适合远程飞行。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆卡车专门跑远程运输。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是跑远程的司机。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢开车跑远程。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远程旅行前，要先检查汽车。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种导弹可以打到远程目标。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就梦想当一名跑远程的卡车司机。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车只适合跑近程，不适合跑远程。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车司机常常要跑远程，很少回家。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一条远程航线，要飞十个小时。", "target_word": "远程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远程教育", "label": "复合"}, {"form": "遠程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "路途遥远的地方或距离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a94ae4-79af-4eab-97ed-f48899b3b919') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远程", "is_correct": true, "explanation": "远程：指很远的路途，此处修饰“飞行”，指长距离的飞行。"}, {"text": "水下", "is_correct": false, "explanation": "语义：水下指水面以下，与飞机在空中的飞行相矛盾。"}, {"text": "地底", "is_correct": false, "explanation": "语义：地底指地面以下，与飞机飞行的意思相悖。"}, {"text": "赛车", "is_correct": false, "explanation": "搭配：“赛车”指车辆比赛，不能与“飞行”搭配。"}], "explanations": {"远程": "远程：指很远的路途，此处修饰“飞行”，指长距离的飞行。", "水下": "语义：水下指水面以下，与飞机在空中的飞行相矛盾。", "地底": "语义：地底指地面以下，与飞机飞行的意思相悖。", "赛车": "搭配：“赛车”指车辆比赛，不能与“飞行”搭配。"}, "sentence_index": 0, "correct_answer": "远程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里保存着远程的文明遗迹。", "explanation": "这里应该用〈远古〉。远程指空间距离很远，不能用来形容时间久远。"}, {"text": "这项决定对社会有远程的影响。", "explanation": "这里应该用〈深远〉。远程只说距离遥远，不能用来形容影响的深远。"}, {"text": "我们的友谊远程而深厚。", "explanation": "这里应该用〈长久〉。远程指空间距离，不能用来形容友谊存在的时间长久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远程", "is_correct": true, "explanation": "远程：指很远的路途，“跑远程”指开车跑长距离运输。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“跑体育”不成立，卡车司机跑的是路线或路程。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸张是物品，不是路程，不能说“跑纸张的司机”。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，“跑电话的卡车司机”不成话。"}], "explanations": {"远程": "远程：指很远的路途，“跑远程”指开车跑长距离运输。", "体育": "搭配：“跑体育”不成立，卡车司机跑的是路线或路程。", "纸张": "语义：纸张是物品，不是路程，不能说“跑纸张的司机”。", "电话": "语义：电话是通讯工具，“跑电话的卡车司机”不成话。"}, "sentence_index": 6, "correct_answer": "远程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他远程赶来参加婚礼。", "explanation": "这里应该用〈远道〉。远程形容的是很远的地方，不能用来描述人从远方赶来，应说远道赶来。"}, {"text": "这件事的远程后果十分严重。", "explanation": "这里应该用〈深远〉。远程只说距离很远，不能用来形容后果影响的深远。"}, {"text": "这座古城的远程历史已经有两千年了。", "explanation": "这里应该用〈悠久〉。远程指空间距离很远，不能用来形容历史存续的时间长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一架很远程客机，可以飞到欧洲。", "corrected_sentence": "这是一架远程客机，可以飞到欧洲。", "error_description": "“远程”直接作定语修饰“客机”，表示能飞很远距离的客机，前面不能加程度副词“很”。去掉“很”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们开始了一次很远程旅行。", "corrected_sentence": "他们开始了一次远程旅行。", "error_description": "“远程”直接作定语修饰“旅行”，表示路途遥远的旅行，前面不能加程度副词“很”。去掉“很”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
