INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "要求别人做到很难的事。", "primary_collocate": null, "pronunciation": "kē qiú", "ipa": "kʰɤ˥ tɕʰiou˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈从不苛求我，只希望我健康。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板苛求员工一天写完一百页报告。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他苛求过家人，现在觉得很后悔。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要苛求一个孩子像大人一样安静。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练苛求球员每场都进三个球。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她苛求丈夫记得每一个纪念日。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别苛求我，我真的做不到。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不苛求别人，对大家都很温和。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人苛求饭店半小时内上完二十道菜。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能苛求演员一个人演好所有角色。", "target_word": "苛求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "苛求了", "label": "体标"}, {"form": "苛求着", "label": "体标"}, {"form": "苛求过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "要求他人完成很难做到的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '382a3983-b0b3-4d55-b760-74b0ee0cab2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苛求", "is_correct": true, "explanation": "苛求指要求别人做到很难的事，“妈妈从不苛求我”指妈妈没有对我提出很难做到的要求，符合句意。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能用于“我”，句子不通。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”针对可以量化的事物，不指向对人提出的要求，与句意不符。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，不能用于人，与“只希望我健康”的语境不合。"}], "explanations": {"苛求": "苛求指要求别人做到很难的事，“妈妈从不苛求我”指妈妈没有对我提出很难做到的要求，符合句意。", "翻译": "搭配：“翻译”的对象是语言或文字，不能用于“我”，句子不通。", "测量": "语义：“测量”针对可以量化的事物，不指向对人提出的要求，与句意不符。", "种植": "语义：“种植”指栽培植物，不能用于人，与“只希望我健康”的语境不合。"}, "sentence_index": 0, "correct_answer": "苛求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我苛求老师再给我一次机会。", "explanation": "这里应该用〈恳求〉。恳求是诚恳地请求别人，语气谦和；苛求含贬义，指对别人提出过高要求，不能用于请人给机会。"}, {"text": "大家苛求春天的到来。", "explanation": "这里应该用〈期盼〉。苛求指提出过高、过严的要求，带批评意味；盼望春天到来是期待，应说“期盼”。"}, {"text": "他苛求友谊，希望有朋友陪伴。", "explanation": "这里应该用〈渴求〉。渴求表示迫切地想得到；苛求指提出过高、过严的要求，带批评意味，不能表达对友谊的向往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苛求", "is_correct": true, "explanation": "苛求指要求别人做到很难的事，“别苛求我”是请对方不要对我提出做不到的要求，符合句意。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”的对象是物品，不能用于“我”，“别包装我”句意不通。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指养育动物或幼儿，与“我真的做不到”的语境不符。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品或场所，不用于人，句意不通。"}], "explanations": {"苛求": "苛求指要求别人做到很难的事，“别苛求我”是请对方不要对我提出做不到的要求，符合句意。", "包装": "搭配：“包装”的对象是物品，不能用于“我”，“别包装我”句意不通。", "喂养": "语义：“喂养”指养育动物或幼儿，与“我真的做不到”的语境不符。", "装饰": "搭配：“装饰”的对象是物品或场所，不用于人，句意不通。"}, "sentence_index": 6, "correct_answer": "苛求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在教堂里苛求平安。", "explanation": "这里应该用〈祈求〉。祈求是恳切地向神明请求，不含对他人施加过高要求的意思；苛求不用于向神明请求平安。"}, {"text": "我们正在苛求合作的机会。", "explanation": "这里应该用〈寻求〉。寻求指努力去找，用于机会、办法等；“苛求”指对他人提出过高要求，不能用于找机会。"}, {"text": "我衷心苛求你的支持。", "explanation": "这里应该用〈感谢〉。感谢是对别人的支持表示谢意，“苛求”含贬义，不能用来表达对支持的感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不应该苛求了老师每天都完美。", "corrected_sentence": "我们不应该苛求老师每天都完美。", "error_description": "“了”误加在动词“苛求”后。“了”表示动作已完成，与“不应该”表达的劝诫语境不符，应删去，说“我们不应该苛求老师每天都完美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门课很难，老师不该苛求了学生全部答对。", "corrected_sentence": "这门课很难，老师不该苛求学生全部答对。", "error_description": "“了”误加在动词“苛求”后，与“不该”表达的劝诫语境不符，应删去，说“老师不该苛求学生全部答对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b275380-cafb-4960-9efa-403fbabb1a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
