INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让很多人知道或使用。", "primary_collocate": null, "pronunciation": "tuī guǎng", "ipa": "tʰweɪ̯˥ kwaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司想推广这种新手机。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正在推广普通话。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用网络推广新产品。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好办法值得推广。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生把新方法推广到了全国。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在推广垃圾分类。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先在小城市推广，再去大城市。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好产品也需要推广，别人才知道。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里推广新咖啡，第一杯半价。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件推广得很快，用的人很多。", "target_word": "推广", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推广了", "label": "体标"}, {"form": "推广过", "label": "体标"}, {"form": "推广活动", "label": "复合"}, {"form": "推廣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把产品、方法等扩大范围，让更多人知道或使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“吃这种新手机”说不通。"}, {"text": "推广", "is_correct": true, "explanation": "正确。推广指扩大范围、让更多人知道或使用，与“想让更多人用这种新手机”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于食物或液体，“煮新手机”不合逻辑。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带宾语“这种新手机”。"}], "explanations": {"吃": "语义：“吃”的对象是食物，“吃这种新手机”说不通。", "推广": "正确。推广指扩大范围、让更多人知道或使用，与“想让更多人用这种新手机”相符。", "煮": "语义：“煮”用于食物或液体，“煮新手机”不合逻辑。", "睡": "配价：“睡”是不及物动词，后面不能带宾语“这种新手机”。"}, "sentence_index": 0, "correct_answer": "推广"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "革命者推广了旧政权。", "explanation": "这里应该用〈推翻〉。推广是扩大范围，不能用来表示推倒旧政权。"}, {"text": "他用力推广了大门。", "explanation": "这里应该用〈推开〉。推广指扩大使用范围，推门的动作要说“推开”。"}, {"text": "这次会议推广到了晚上。", "explanation": "这里应该用〈延长〉。推广指让更多人知道或使用，时间延长要说“延长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩小", "is_correct": false, "explanation": "语义：“缩小”是缩减规模，与“再去大城市”的扩展思路不符。"}, {"text": "推广", "is_correct": true, "explanation": "正确。“推广”指先在小范围让人使用，再扩大，与“先在小城市……再去大城市”的顺序相符。"}, {"text": "消灭", "is_correct": false, "explanation": "搭配：“消灭”需要消灭的对象，如“消灭害虫”，“小城市”不能作它的对象。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“去大城市”的计划无关，句子不通。"}], "explanations": {"缩小": "语义：“缩小”是缩减规模，与“再去大城市”的扩展思路不符。", "推广": "正确。“推广”指先在小范围让人使用，再扩大，与“先在小城市……再去大城市”的顺序相符。", "消灭": "搭配：“消灭”需要消灭的对象，如“消灭害虫”，“小城市”不能作它的对象。", "哭": "语义：“哭”与“去大城市”的计划无关，句子不通。"}, "sentence_index": 6, "correct_answer": "推广"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们推广了公司规模。", "explanation": "这里应该用〈扩大〉。推广是让更多人知道或使用，“规模”要用“扩大”。"}, {"text": "这次努力推广了成绩。", "explanation": "这里应该用〈提高〉。成绩说的是水平，推广只用于产品、方法等让人使用的事物。"}, {"text": "他推广了工作速度。", "explanation": "这里应该用〈加快〉。速度要用“加快”，推广不能用于速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把新产品推广的农村。", "corrected_sentence": "我们要把新产品推广到农村。", "error_description": "错误：“推广”后面接表示范围的地点时要用介词“到”，这里误用了“的”。应说“推广到农村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款软件推广了得很快。", "corrected_sentence": "这款软件推广得很快。", "error_description": "错误：“了”放错了位置。“推广”后面带补语“得很快”时不能加“了”，应说“推广得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
