INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22652, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指在不知不觉中，没有特意去做，但事情就发生了。", "primary_collocate": null, "pronunciation": "wú xíng zhōng", "ipa": "u³⁵ ɕiŋ³⁵ ʈʂʊŋ⁵⁵", "syllable_count": 3, "sentences": [{"text": "我没有特意背，无形中就记住了很多句子。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没想学画画，无形中却爱上了画画。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听着音乐收拾屋子，无形中屋子就变干净了。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶没教我做饭，无形中我也学会了。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们天天一起走路上学，无形中成了好朋友。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有特意减肥，无形中瘦了五公斤。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在海边，我无形中爱上了大海。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一路上大家说说笑笑，无形中就忘了疲劳。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常看他写字，无形中字也写得好看了。", "target_word": "无形中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天天和他说中文，我的中文无形中进步了很多。", "target_word": "无形中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "没有特意去做，事情不知不觉就发生了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无形中", "is_correct": true, "explanation": "正确：作状语，表示不知不觉地记住，与前半句“没有特意背”形成对照。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”与前半句的“没有特意背”直接矛盾，句子无法成立。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意而为，与“没有特意背”的语境矛盾。"}, {"text": "当面", "is_correct": false, "explanation": "语义：“当面”指当着面，与“记住很多句子”的过程无关，句意不通。"}], "explanations": {"无形中": "正确：作状语，表示不知不觉地记住，与前半句“没有特意背”形成对照。", "特意": "语义：“特意”与前半句的“没有特意背”直接矛盾，句子无法成立。", "故意": "语义：“故意”表示有意而为，与“没有特意背”的语境矛盾。", "当面": "语义：“当面”指当着面，与“记住很多句子”的过程无关，句意不通。"}, "sentence_index": 0, "correct_answer": "无形中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我特意无形中去超市买了一箱水果。", "explanation": "这里的“无形中”表示不知不觉，与有意识安排的行动相矛盾，应去掉“无形中”。"}, {"text": "请你无形中帮我关灯。", "explanation": "这里的“无形中”表示不知不觉，与要求他人有意去做的事相矛盾，应去掉“无形中”。"}, {"text": "他决定无形中辞职去国外。", "explanation": "这里的“无形中”表示不知不觉，而重大的人生选择必须有意识地做出，二者矛盾，应去掉“无形中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无形中", "is_correct": true, "explanation": "正确：作状语，表示不知不觉地爱上，与“住在海边”的长期生活呼应。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“爱上大海”的长期变化矛盾。"}, {"text": "亲手", "is_correct": false, "explanation": "语义：“亲手”指亲自动手，与“爱上大海”这种情感变化无关，句意不通。"}, {"text": "连夜", "is_correct": false, "explanation": "语义：“连夜”指整夜、当夜，不能修饰“爱上大海”这种情感变化，句意不通。"}], "explanations": {"无形中": "正确：作状语，表示不知不觉地爱上，与“住在海边”的长期生活呼应。", "偶尔": "语义：“偶尔”表示不常发生，与“爱上大海”的长期变化矛盾。", "亲手": "语义：“亲手”指亲自动手，与“爱上大海”这种情感变化无关，句意不通。", "连夜": "语义：“连夜”指整夜、当夜，不能修饰“爱上大海”这种情感变化，句意不通。"}, "sentence_index": 6, "correct_answer": "无形中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他无形中决定把这份计划做得非常详细。", "explanation": "这里的“无形中”表示不知不觉，而“决定”是有意识的选择，二者矛盾，应去掉“无形中”。"}, {"text": "我故意无形中把杯子打碎了。", "explanation": "这里的“无形中”表示不知不觉，与有意而为的做法相矛盾，应去掉“无形中”。"}, {"text": "老板打算无形中提高我们的工资。", "explanation": "这里的“无形中”表示不知不觉，与有计划的意图相矛盾，应去掉“无形中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年我一直练跑步，无形中地身体好了很多。", "corrected_sentence": "这几年我一直练跑步，无形中身体好了很多。", "error_description": "多余的“地”：“无形中”是副词，后面不能再加“地”。正确说法是“无形中身体好了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天加班，我无形中地瘦了很多。", "corrected_sentence": "这几天加班，我无形中瘦了很多。", "error_description": "多余的“地”：“无形中”是副词，后面不能再加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "清楚与模糊构成反义，指看得明白、轮廓分明。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈形容情绪或气氛高涨，与模糊无反义关系。"}, {"text": "富有", "is_correct": false, "explanation": "富有形容拥有很多或充足，与模糊无反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与模糊无反义关系。"}], "correct_answer": "清楚", "explanations": {"清楚": "清楚与模糊构成反义，指看得明白、轮廓分明。", "热烈": "热烈形容情绪或气氛高涨，与模糊无反义关系。", "富有": "富有形容拥有很多或充足，与模糊无反义关系。", "柔软": "柔软形容质地，与模糊无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清晰", "is_correct": true, "explanation": "清晰与模糊构成反义，指看得分明、轮廓明确。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，与模糊无反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢形容性格，与模糊无反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "宽广形容面积或范围大，与模糊无反义关系。"}], "correct_answer": "清晰", "explanations": {"清晰": "清晰与模糊构成反义，指看得分明、轮廓明确。", "迅速": "迅速形容速度快，与模糊无反义关系。", "勇敢": "勇敢形容性格，与模糊无反义关系。", "宽广": "宽广形容面积或范围大，与模糊无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "看不清楚的样子。", "primary_collocate": null, "pronunciation": "mó hu", "ipa": "mwɔ˧˥ xu", "syllable_count": 2, "sentences": [{"text": "窗户上有雾，外面的树看起来很模糊。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没戴眼镜，黑板上的字都很模糊。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片拍得太模糊了，看不清他的脸。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，远处的山变得模糊了。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛进了水，周围的东西变得很模糊。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里没有灯，路上的人影很模糊。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧照片已经模糊，人的样子看不清了。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕摔坏了，上面的字很模糊。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾里，远处的楼只剩一个模糊的影子。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得太快，窗外的花都变得模糊了。", "target_word": "模糊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模模糊糊", "label": "重叠"}], "register": "中性", "sense_fingerprint": "形容词；视觉上看不清楚，轮廓不分明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "模糊", "is_correct": true, "explanation": "正确答案。模糊指看不清楚，轮廓不分明。"}, {"text": "蘑菇", "is_correct": false, "explanation": "第二音节声母不同：蘑菇的 g 与模糊的 h 不同。蘑菇指食用菌。"}, {"text": "磨合", "is_correct": false, "explanation": "第二音节声调不同：磨合的 hé 为第二声，模糊的 hu 为轻声。磨合指互相适应。"}, {"text": "魔盒", "is_correct": false, "explanation": "第二音节不同：魔盒的 hé 韵母、声调都与模糊的轻声 hu 不同。魔盒指有魔力的盒子。"}, {"text": "墨盒", "is_correct": false, "explanation": "声调和韵母不同：墨盒读 mò hé，模糊读 mó hu。墨盒指打印机装墨的盒子。"}], "explanations": {"模糊": "正确答案。模糊指看不清楚，轮廓不分明。", "蘑菇": "第二音节声母不同：蘑菇的 g 与模糊的 h 不同。蘑菇指食用菌。", "磨合": "第二音节声调不同：磨合的 hé 为第二声，模糊的 hu 为轻声。磨合指互相适应。", "魔盒": "第二音节不同：魔盒的 hé 韵母、声调都与模糊的轻声 hu 不同。魔盒指有魔力的盒子。", "墨盒": "声调和韵母不同：墨盒读 mò hé，模糊读 mó hu。墨盒指打印机装墨的盒子。"}, "sentence_index": null, "correct_answer": "模糊"}, "level_3": {"options": [{"text": "模糊", "is_correct": true, "explanation": "模糊：视线受雾影响而看不清，与“窗户上有雾”相合。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“窗户上有雾”说明看不清，与“清楚”矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”多用于玻璃、水等，不用来形容树的外观。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，树看不清并不是因为陌生，与雾的语境不合。"}], "explanations": {"模糊": "模糊：视线受雾影响而看不清，与“窗户上有雾”相合。", "清楚": "语义：“窗户上有雾”说明看不清，与“清楚”矛盾。", "透明": "搭配：“透明”多用于玻璃、水等，不用来形容树的外观。", "陌生": "语义：“陌生”指不熟悉，树看不清并不是因为陌生，与雾的语境不合。"}, "sentence_index": 0, "correct_answer": "模糊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑得很模糊，一下子就冲过了终点。", "explanation": "模糊不用来形容动作的快慢，这里应该说〈快〉。"}, {"text": "这次考试的分数很模糊，老师很快就算出来了。", "explanation": "这里应该用〈准确〉。模糊指看不清楚的样子，分数是确定的数字，不存在看不清的问题；把分数说成模糊，是把“结果不确定”误当成了它的意思。"}, {"text": "这杯咖啡很模糊，喝起来特别甜。", "explanation": "这里应该说〈香〉。模糊指看不清楚的样子，不用来形容饮品的香气或味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模糊", "is_correct": true, "explanation": "模糊：照片已经褪色、不清，与“人的样子看不清了”相合。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”与后句“人的样子看不清了”矛盾。"}, {"text": "光亮", "is_correct": false, "explanation": "搭配：“光亮”多形容光线或物体表面，不用来描述照片的状态。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来形容照片。"}], "explanations": {"模糊": "模糊：照片已经褪色、不清，与“人的样子看不清了”相合。", "清晰": "语义：“清晰”与后句“人的样子看不清了”矛盾。", "光亮": "搭配：“光亮”多形容光线或物体表面，不用来描述照片的状态。", "响亮": "搭配：“响亮”形容声音，不能用来形容照片。"}, "sentence_index": 6, "correct_answer": "模糊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个司机很模糊，开车总是走错路。", "explanation": "这里应该用〈糊涂〉。糊涂形容人头脑不清、办事不明白，模糊不用来形容人的头脑。"}, {"text": "我的书包很模糊，老师让我再整理一遍。", "explanation": "这里应该用〈乱〉。模糊指看不清楚的样子，不能用来形容书包；这里说的是书包没整理好，应说“乱”。"}, {"text": "这件衣服很模糊，我们都觉得很暖和。", "explanation": "这里应该说〈厚〉。模糊指看不清楚，不用来形容衣服的厚薄；衣服的保暖性应说“厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没戴眼镜，远处的人看很模糊。", "corrected_sentence": "我没戴眼镜，远处的人看得很模糊。", "error_description": "错误：“看很模糊”，正确：“看得很模糊”。动词后描述程度要用“得”引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远处的路灯看起来很模糊地，我看不清路。", "corrected_sentence": "远处的路灯看起来很模糊，我看不清路。", "error_description": "错误：“很模糊地”；正确：“很模糊”。“地”用于修饰其后的动词，这里“模糊”作谓语，不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
