INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22658, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22658, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "几个人或几方互相配合，一起完成一件事。", "primary_collocate": null, "pronunciation": "xié zuò", "ipa": "ɕjɛ˧˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "我和同学协作完成了这个小组作业。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人协作得很好。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个实验，大家需要互相协作。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们两个人协作画一张画。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的时候，同事们要多协作，不能各做各的。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们协作了三个月，终于做好了新网站。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和小红协作做了一个大蛋糕。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们协作过很多次，所以很了解对方。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司协作开发了一种新手机。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有大家一起协作，工作才能完成得快。", "target_word": "协作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协作了", "label": "体标"}, {"form": "协作过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "人与人配合起来一起完成一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22658, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协作", "is_correct": true, "explanation": "“协作”（xié zuò）是本词，表示人与人配合着一起完成事情。"}, {"text": "杰作", "is_correct": false, "explanation": "jié（第二声）与 xié（第二声）声母不同（j 与 x），意思是杰出的作品。"}, {"text": "写作", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写文章、写作品。"}, {"text": "习作", "is_correct": false, "explanation": "xí（第二声）与 xié 韵母不同（没有 e），意思是练习性的写作或作品。"}], "explanations": {"协作": "“协作”（xié zuò）是本词，表示人与人配合着一起完成事情。", "杰作": "jié（第二声）与 xié（第二声）声母不同（j 与 x），意思是杰出的作品。", "写作": "xiě（第三声）与 xié（第二声）声调不同，意思是写文章、写作品。", "习作": "xí（第二声）与 xié 韵母不同（没有 e），意思是练习性的写作或作品。"}, "sentence_index": null, "correct_answer": "协作"}, "level_3": {"options": [{"text": "协作", "is_correct": true, "explanation": "“协作”表示双方配合，与“我和同学一起完成作业”的语境相合。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：“竞争”指争胜，与“一起完成”的配合意思矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，不能用来描述一起完成作业。"}, {"text": "指挥", "is_correct": false, "explanation": "配价：“指挥”需要一方发令、另一方受令，“我和同学”并列作主语不构成指挥关系。"}], "explanations": {"协作": "“协作”表示双方配合，与“我和同学一起完成作业”的语境相合。", "竞争": "语义：“竞争”指争胜，与“一起完成”的配合意思矛盾。", "反对": "语义：“反对”表示不同意，不能用来描述一起完成作业。", "指挥": "配价：“指挥”需要一方发令、另一方受令，“我和同学”并列作主语不构成指挥关系。"}, "sentence_index": 0, "correct_answer": "协作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我协作他的才华，常常夸他。", "explanation": "这里应该用〈欣赏〉。协作指两人共同配合做事，不能用来表示对才华的赞赏，应说欣赏。"}, {"text": "没有人帮忙，这个孩子一个人协作完成了作业。", "explanation": "这里应该用〈独立〉。协作至少需要两方互相配合，一个人自己完成要说独立完成。"}, {"text": "士兵协作上级的命令。", "explanation": "这里应该用〈服从〉。协作指双方平等配合，听从上级的命令是下级的服从。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协作", "is_correct": true, "explanation": "“协作”表示两人配合，与“一起做了一个大蛋糕”相合。"}, {"text": "争夺", "is_correct": false, "explanation": "搭配：“争夺”接地位、资源等，不接“做蛋糕”这类动作。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“做了一个大蛋糕”的完成结果矛盾。"}, {"text": "对抗", "is_correct": false, "explanation": "语义：“对抗”表示对立，与两人一起做蛋糕的意思不合。"}], "explanations": {"协作": "“协作”表示两人配合，与“一起做了一个大蛋糕”相合。", "争夺": "搭配：“争夺”接地位、资源等，不接“做蛋糕”这类动作。", "拒绝": "语义：“拒绝”与“做了一个大蛋糕”的完成结果矛盾。", "对抗": "语义：“对抗”表示对立，与两人一起做蛋糕的意思不合。"}, "sentence_index": 6, "correct_answer": "协作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他协作了老师的规定，结果被罚了。", "explanation": "这里应该用〈违反〉。协作指双方共同配合，不遵守规定要说违反。"}, {"text": "我们协作了一扇大门。", "explanation": "这里应该用〈安装〉。协作指多人共同配合做事，装门要用安装。"}, {"text": "老师协作学生考试。", "explanation": "这里应该用〈监督〉。协作是平等配合，监考是一方管理另一方，应说监督。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们对物流公司协作开发了新系统。", "corrected_sentence": "我们和物流公司协作开发了新系统。", "error_description": "介词用错：“协作”的合作对象应由“和”引出，“对”不能引出协作的对象，应说“和物流公司协作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明和小红协作很好，很快就做完了。", "corrected_sentence": "小明和小红协作得很好，很快就做完了。", "error_description": "漏掉了“得”：动词后接程度补语要用“动词+得+补语”，应说“协作得很好”，不能说“协作很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人叫你做什么，你就去做。", "primary_collocate": null, "pronunciation": "xiǎng yìng", "ipa": "ɕiɑŋ˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "全班同学都响应了老师的号召。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多市民响应政府的号召，少用塑料袋。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要响应环保号召，出门坐地铁。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校号召大家捐书，同学们都积极响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一个响应了队长的号召。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发出通知后，没有几个人响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区号召大家打扫公园，很多邻居马上响应。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区号召大家节约用电，可是响应的人不多。", "target_word": "响应", "complexity_tier": "T3", "furigana": "xiǎng yìng", "sentence_source": "generated"}, {"text": "为了响应节约用水的号召，我家装了新水龙头。", "target_word": "响应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意响应你的倡议，明天一起去植树。", "target_word": "响应", "complexity_tier": "T3", "furigana": "xiǎng yìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "响应了", "label": "体标"}, {"form": "响应过", "label": "体标"}], "register": "中性", "sense_fingerprint": "听到号召或呼吁后照着去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“响应了老师的号召”指照着号召去做，与句意相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用来指照着号召去做，“都唱了老师的号召”读起来不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，与“号召”无关，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象应是器物，不能与“号召”搭配。"}], "explanations": {"响应": "正确。“响应了老师的号召”指照着号召去做，与句意相合。", "唱": "语义：“唱”不能用来指照着号召去做，“都唱了老师的号召”读起来不通。", "煮": "语义：“煮”指加热食物，与“号召”无关，句子不通。", "修理": "搭配：“修理”的对象应是器物，不能与“号召”搭配。"}, "sentence_index": 0, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开车要响应交通规则。", "explanation": "这里应该用〈遵守〉。“遵守”用于规则、制度，“响应”用于号召、倡议，不用于交通规则。"}, {"text": "我们要响应公共秩序。", "explanation": "这里应该用〈维护〉。“维护”用于秩序、利益，“响应”用于号召、倡议，不用于秩序。"}, {"text": "他很快响应了这门语言。", "explanation": "这里应该用〈掌握〉。“掌握”用于语言、技术、知识，“响应”用于号召、倡议，不用于语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "响应", "is_correct": true, "explanation": "正确。“很多邻居马上响应”指邻居照着号召马上去做，与句意相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与打扫公园的号召无关，“马上睡觉”读起来不合语境。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”不是人能按号召采取的行动，句子不通。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”不用于描述邻居的行动，“邻居马上冻结”不能这样搭配。"}], "explanations": {"响应": "正确。“很多邻居马上响应”指邻居照着号召马上去做，与句意相合。", "睡觉": "语义：“睡觉”与打扫公园的号召无关，“马上睡觉”读起来不合语境。", "下雨": "语义：“下雨”不是人能按号召采取的行动，句子不通。", "冻结": "搭配：“冻结”不用于描述邻居的行动，“邻居马上冻结”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "响应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快响应了这次考试。", "explanation": "这里应该用〈参加〉。“参加”用于考试、活动，“响应”用于号召、倡议，不用于考试。"}, {"text": "这道数学题很难，他响应了半天。", "explanation": "这里应该用〈解答〉。“解答”用于解决问题、习题，“响应”不能用于题目。"}, {"text": "面对网友的批评，他很快响应了错误。", "explanation": "这里应该用〈承认〉。“承认”用于承认错误、事实，“响应”不能用于错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "居民们明天响应了社区的号召。", "corrected_sentence": "居民们昨天响应了社区的号召。", "error_description": "错误：“明天响应了”。“明天”表示将来，不能与表示完成的“响应了”连用；把“明天”改为“昨天”，说“居民们昨天响应了社区的号召”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没有响应掉大家的倡议。", "corrected_sentence": "我们没有响应大家的倡议。", "error_description": "错误：“响应掉”。“响应”后不能接结果补语“掉”，应去掉“掉”，说“没有响应大家的倡议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球表面按经度划分的区域，同一区域内使用相同的标准时间。", "primary_collocate": null, "pronunciation": "shí qū", "ipa": "ʂɻ̩³⁵ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "我家和奶奶家不在一个时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个时区的钟表时间都不一样。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国外前，我查了那里的时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机会自动换成新的时区。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同一个时区的人，用同样的钟表时间。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球分成很多时区，所以各地时间不同。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在哪个时区工作？", "target_word": "时区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他飞到另一个时区，白天变成了晚上。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把电脑的时区改成北京时间。", "target_word": "时区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时区不同，所以我们不能同时吃饭。", "target_word": "时区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "使用同一个钟表时间的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：时区指地球上使用相同钟表时间的地方。"}, {"text": "市区", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是市区，即城市内部的区域。"}, {"text": "时期", "is_correct": false, "explanation": "qī 与 qū 的韵母不同（ī 与 ū），意思是时期，即一段时间。"}, {"text": "识趣", "is_correct": false, "explanation": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是懂得分寸。"}, {"text": "时局", "is_correct": false, "explanation": "jú（第二声）与 qū（第一声）声母与声调不同，意思是时局，即当时的局势。"}], "explanations": {"时区": "正确：时区指地球上使用相同钟表时间的地方。", "市区": "shì（第四声）与 shí（第二声）声调不同，意思是市区，即城市内部的区域。", "时期": "qī 与 qū 的韵母不同（ī 与 ū），意思是时期，即一段时间。", "识趣": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是懂得分寸。", "时局": "jú（第二声）与 qū（第一声）声母与声调不同，意思是时局，即当时的局势。"}, "sentence_index": null, "correct_answer": "时区"}, "level_3": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：“不在一个时区”指两地用的钟表时间不同。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能划分两个地方的位置关系，“不在一个颜色”说不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”不是地点或范围，不能说“不在一个乐器”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“不在一个……”后接地点或范围，“歌曲”不能这样用。"}], "explanations": {"时区": "正确：“不在一个时区”指两地用的钟表时间不同。", "颜色": "语义：“颜色”不能划分两个地方的位置关系，“不在一个颜色”说不通。", "乐器": "语义：“乐器”不是地点或范围，不能说“不在一个乐器”。", "歌曲": "搭配：“不在一个……”后接地点或范围，“歌曲”不能这样用。"}, "sentence_index": 0, "correct_answer": "时区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家和奶奶家的时区是三个小时。", "explanation": "这里应该用〈时差〉。时差指两地时间相差的小时数，时区不能表示相差几小时。"}, {"text": "客厅的时区停了。", "explanation": "这里应该用〈挂钟〉。挂钟会走会停，时区是地区的划分，不会停。"}, {"text": "手机会自动换成一只新的时区。", "explanation": "这里应该用〈个〉。时区是抽象的区域概念，量词用“个”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：时区指地球上使用相同钟表时间的地方。"}, {"text": "社区", "is_correct": false, "explanation": "shè（第四声）与 shí（第二声）的韵母与声调都不同，意思是社区，即居民聚居的地区。"}, {"text": "石器", "is_correct": false, "explanation": "qì（第四声）与 qū（第一声）的韵母与声调不同，意思是石器，即石头制成的工具。"}, {"text": "食具", "is_correct": false, "explanation": "shí 相同，jù（第四声）与 qū（第一声）声母与声调不同，意思是食具，即饮食用具。"}, {"text": "识趣", "is_correct": false, "explanation": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是识趣，即懂得分寸。"}], "explanations": {"时区": "正确：时区指地球上使用相同钟表时间的地方。", "社区": "shè（第四声）与 shí（第二声）的韵母与声调都不同，意思是社区，即居民聚居的地区。", "石器": "qì（第四声）与 qū（第一声）的韵母与声调不同，意思是石器，即石头制成的工具。", "食具": "shí 相同，jù（第四声）与 qū（第一声）声母与声调不同，意思是食具，即饮食用具。", "识趣": "shí 相同，qù（第四声）与 qū（第一声）只有声调不同，意思是识趣，即懂得分寸。"}, "sentence_index": null, "correct_answer": "时区"}, "level_3": {"options": [{"text": "时区", "is_correct": true, "explanation": "正确：“哪个时区”询问工作所在的时区，符合句子语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能指工作的地方，“哪个味道”说不通。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“哪个”之后接地点或单位，“音乐”不能这样用。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”是文字的样式，不能指工作的地方，句子不通。"}], "explanations": {"时区": "正确：“哪个时区”询问工作所在的时区，符合句子语境。", "味道": "语义：“味道”不能指工作的地方，“哪个味道”说不通。", "音乐": "搭配：“哪个”之后接地点或单位，“音乐”不能这样用。", "字体": "语义：“字体”是文字的样式，不能指工作的地方，句子不通。"}, "sentence_index": 6, "correct_answer": "时区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议的时区定在下午三点。", "explanation": "这里应该用〈时刻〉。时刻指具体的时间点，可以定在下午三点；时区是地区划分，不能定在某个钟点。"}, {"text": "我们吃饭的时区定在晚上七点。", "explanation": "这里应该用〈时间〉。吃饭的时间可以定在晚上七点，时区不是钟点，不能这样说。"}, {"text": "这个时区很短。", "explanation": "这里应该用〈时段〉。时段指一段时间，可以很短；时区是地区划分，不能用“很短”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行跨过了两只时区。", "corrected_sentence": "这次旅行跨过了两个时区。", "error_description": "量词错误：时区应使用量词“个”，不能用“只”。正确说法是“跨过了两个时区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "手机上有二十四只时区可以选。", "corrected_sentence": "手机上有二十四个时区可以选。", "error_description": "量词错误：时区用量词“个”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
