INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个东西有两个，或者一个事有两个方面。", "primary_collocate": null, "pronunciation": "shuāng chóng", "ipa": "ʂwɑŋ˥ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事具有双重性质，好坏很难分。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè jiàn shì jù yǒu shuāng chóng xìng zhì, hǎo huài hěn nán fēn.", "sentence_source": "generated"}, {"text": "他的笑容有双重意思，我猜不到。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套方案有双重好处，既省钱又省时间。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè tào fāng àn yǒu shuāng chóng hǎo chu, jì shěng qián yòu shěng shíjiān.", "sentence_source": "generated"}, {"text": "这个任务有双重目的，一是学习，二是赚钱。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过着双重生活，白天上班，晚上写书。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剪刀有双重功能，既能剪纸又能开瓶。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè bǎ jiǎn dāo yǒu shuāng chóng gōng néng, jì néng jiǎn zhǐ yòu néng kāi píng.", "sentence_source": "generated"}, {"text": "老师对我的要求是双重的。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话有双重意义，大家都明白。", "target_word": "双重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有双重作用，既能过车又能过人。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè zuò qiáo yǒu shuāng chóng zuò yòng, jì néng guò chē yòu néng guò rén.", "sentence_source": "generated"}, {"text": "这次旅行有双重收获，既长见识又交了朋友。", "target_word": "双重", "complexity_tier": "T3", "furigana": "zhè cì lǚ xíng yǒu shuāng chóng shōu huò, jì zhǎng jiàn shi yòu jiāo le péng you.", "sentence_source": "generated"}], "morphological_forms": [{"form": "雙重", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个东西有两层，或一件事有两个方面、两种用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双重", "is_correct": true, "explanation": "正确：“双重性质”指事物兼有两个方面的性质，所以好坏很难分。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多修饰声音、笑容，不修饰“性质”。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”指形状，不能说明事情的性质。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”描述场所或气氛，不修饰“性质”。"}], "explanations": {"双重": "正确：“双重性质”指事物兼有两个方面的性质，所以好坏很难分。", "甜美": "搭配：“甜美”多修饰声音、笑容，不修饰“性质”。", "圆形": "语义：“圆形”指形状，不能说明事情的性质。", "冷清": "搭配：“冷清”描述场所或气氛，不修饰“性质”。"}, "sentence_index": 0, "correct_answer": "双重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场双重比赛很精彩。", "explanation": "这里应该用〈双打〉。双打指两人一组的比赛，如网球双打；双重表示两层或两个方面，不能指比赛形式。"}, {"text": "他们是双重兄弟。", "explanation": "这里应该用〈双胞胎〉。双胞胎指同时出生的两个人；双重不能指人。"}, {"text": "她每次都买双重的菜。", "explanation": "这里应该用〈双份〉。双份指两份，表示分量加倍；双重表示两层或两个方面，不能表示份量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双重", "is_correct": true, "explanation": "正确：“双重的要求”指要求包含两个方面。"}, {"text": "绿色", "is_correct": false, "explanation": "体貌：“绿色”描述外观颜色，不能形容“要求”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多修饰声音，不修饰“要求”。"}, {"text": "方形", "is_correct": false, "explanation": "语义：“方形”指形状，不能说明要求的性质。"}], "explanations": {"双重": "正确：“双重的要求”指要求包含两个方面。", "绿色": "体貌：“绿色”描述外观颜色，不能形容“要求”。", "清脆": "搭配：“清脆”多修饰声音，不修饰“要求”。", "方形": "语义：“方形”指形状，不能说明要求的性质。"}, "sentence_index": 6, "correct_answer": "双重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双重的朋友都来了。", "explanation": "这里应该用〈双方〉。双方指两个人或两个团体；双重指两层或两个方面，不能指代人，也不能作主语。"}, {"text": "他一个人吃了双重的米饭。", "explanation": "这里应该用〈双倍〉。双倍指数量加倍；双重表示两层或两个方面，不能表示分量翻倍。"}, {"text": "她用双重的手接住了杯子。", "explanation": "这里应该用〈双手〉。双手指两只手，是名词；双重不能指手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动有很双重意义，既能娱乐又能学习。", "corrected_sentence": "这次活动有双重意义，既能娱乐又能学习。", "error_description": "程度错误：“双重”表示两层或两个方面，是非等级形容词，不能受“很”修饰。正确说法是“双重意义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个房间有双重了用途，白天学习，晚上睡觉。", "corrected_sentence": "这个房间有双重用途，白天学习，晚上睡觉。", "error_description": "语法错误：“了”插在“双重”和“用途”之间，应说“双重用途”，不能说“双重了用途”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地球上的地方和样子。", "primary_collocate": null, "pronunciation": "dì lǐ", "ipa": "ti˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里的地理很特别，三面都是山。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这一带的地理很熟，从不会迷路。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老司机知道各地的地理和天气。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛的地理很简单，只有一座山。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同国家的地理不一样，生活也不同。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书写的是中国的地理。", "target_word": "地理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从地图上可以看出这个国家的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走遍了全国，所以很熟悉各地的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游先给大家介绍了这座城市的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，他年轻时就熟悉这一带的地理。", "target_word": "地理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地理位置", "label": "复合"}, {"form": "地理环境", "label": "复合"}], "register": "通用", "sense_fingerprint": "某地的山水地形等地理情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eea9ae5a-a1c2-46b4-ba5e-281e3260ca2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：地理（dì lǐ），指地球上的地方和样子。"}, {"text": "地利", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是地理上的有利条件。"}, {"text": "地力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是土地的肥力。"}, {"text": "地址", "is_correct": false, "explanation": "zhǐ（第三声）与 lǐ（第三声）只有声母不同（zh 与 l），意思是住址或所在的位置。"}], "explanations": {"地理": "正确：地理（dì lǐ），指地球上的地方和样子。", "地利": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是地理上的有利条件。", "地力": "lì（第四声）与 lǐ（第三声）只有声调不同，意思是土地的肥力。", "地址": "zhǐ（第三声）与 lǐ（第三声）只有声母不同（zh 与 l），意思是住址或所在的位置。"}, "sentence_index": null, "correct_answer": "地理"}, "level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“地理”指地球上的地方和样子，与“三面都是山”的描写相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指买卖的钱数，与“三面都是山”讲的地形不搭。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”多用于人，不说“这里的脾气”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指劳动报酬，与“三面都是山”的描写无关。"}], "explanations": {"地理": "正确：“地理”指地球上的地方和样子，与“三面都是山”的描写相符。", "价格": "语义：“价格”指买卖的钱数，与“三面都是山”讲的地形不搭。", "脾气": "搭配：“脾气”多用于人，不说“这里的脾气”。", "工资": "语义：“工资”指劳动报酬，与“三面都是山”的描写无关。"}, "sentence_index": 0, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的地理很干净，空气也好。", "explanation": "这里应该用〈环境〉。地理指地形地貌等自然状况，不能说干净；描写卫生和空气要用环境。"}, {"text": "明天的地理很好，适合出门。", "explanation": "这里应该用〈天气〉。地理指地形地貌等自然状况的总体情况，不指某一天的晴雨冷暖；说天气好坏要用天气。"}, {"text": "会议的地理在二楼。", "explanation": "这里应该用〈地点〉。地理是泛指地形地貌的名词，不能指会议的具体场所；说在某处要用地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "正确：“地理”指国家的地形地貌，可以从地图上看出。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”指上学交的钱，地图上看不出。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来说一个国家。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学生的课后练习，与地图和国家无关。"}], "explanations": {"地理": "正确：“地理”指国家的地形地貌，可以从地图上看出。", "学费": "语义：“学费”指上学交的钱，地图上看不出。", "身高": "体貌：“身高”指人的身体高矮，不能用来说一个国家。", "作业": "语义：“作业”指学生的课后练习，与地图和国家无关。"}, "sentence_index": 6, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一带的地理很重，一头牛都拉不动。", "explanation": "这里应该用〈重量〉。“地理”指地形地貌，不能用来形容轻重。"}, {"text": "这一带的地理很热情，见了外地人都打招呼。", "explanation": "这里应该用〈居民〉。“地理”指地形地貌，不能形容性格，“热情”说的是人。"}, {"text": "这一带的地理很少，只有几十户。", "explanation": "这里应该用〈人口〉。地理指地形地貌，不能用来说户数多少；说人数要用人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇的地理位子很好，交通方便。", "corrected_sentence": "这个小镇的地理位置很好，交通方便。", "error_description": "用词错误：“地理位置”是固定的复合词，末尾是“置”，不能写成“位子”。“位子”指座位或职位，不能与“地理”组合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在调查这一带得地理。", "corrected_sentence": "我们正在调查这一带的地理。", "error_description": "用词错误：“这一带的地理”中修饰语的标记应为“的”，写成“得”错误。“得”作补语的标记，用在动词或形容词后，这里应使用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
