INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两个东西分开的地方。", "primary_collocate": null, "pronunciation": "jiè xiàn", "ipa": "tɕjɛ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "河是两个村子的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线是两个院子的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙是我家和邻居家的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶就是两个省的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在田里放了石头当界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片树林是两个国家的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这排树是两块地的界限。", "target_word": "界限", "complexity_tier": "T3", "furigana": "zhè pái shù shì liǎng kuài dì de jiè xiàn", "sentence_source": "generated"}, {"text": "请不要越过这条界限，那边是别人家的地。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两块地中间的小路就是界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的白线是比赛场地的界限。", "target_word": "界限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "土地、场所等两个具体事物分开的地方或线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22668, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "界限", "is_correct": true, "explanation": "正确。界限读作 jiè xiàn，指两个事物分开的地方。"}, {"text": "接线", "is_correct": false, "explanation": "jiē（第二声）与 jiè（第四声）声调不同，意思是连接线路。"}, {"text": "基线", "is_correct": false, "explanation": "jī 去掉了 jiè 的韵母 e，声调也不同，意思是作为依据的起始线。"}, {"text": "极限", "is_correct": false, "explanation": "jí 去掉了 jiè 的韵母 e，声调也不同，意思是最大限度。"}, {"text": "界面", "is_correct": false, "explanation": "miàn 与 xiàn 声母不同（m 与 x），意思是界面、表面。"}], "explanations": {"界限": "正确。界限读作 jiè xiàn，指两个事物分开的地方。", "接线": "jiē（第二声）与 jiè（第四声）声调不同，意思是连接线路。", "基线": "jī 去掉了 jiè 的韵母 e，声调也不同，意思是作为依据的起始线。", "极限": "jí 去掉了 jiè 的韵母 e，声调也不同，意思是最大限度。", "界面": "miàn 与 xiàn 声母不同（m 与 x），意思是界面、表面。"}, "sentence_index": null, "correct_answer": "界限"}, "level_3": {"options": [{"text": "界限", "is_correct": true, "explanation": "正确。河是两个村子之间的分界，用“界限”。"}, {"text": "道路", "is_correct": false, "explanation": "语义：河不是供人行走的路，“道路”与分界的意思不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：河是地理事物，不是颜色，句意不通。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“距离”要说“两村之间的距离”，不能直接说“河是距离”。"}], "explanations": {"界限": "正确。河是两个村子之间的分界，用“界限”。", "道路": "语义：河不是供人行走的路，“道路”与分界的意思不符。", "颜色": "语义：河是地理事物，不是颜色，句意不通。", "距离": "搭配：“距离”要说“两村之间的距离”，不能直接说“河是距离”。"}, "sentence_index": 0, "correct_answer": "界限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个仓库的界限是五百箱。", "explanation": "这里应该用〈容量〉。界限指两个东西之间的分界处，不表示容纳的数量；应说“仓库的容量是五百箱”。"}, {"text": "两省交界处立着一块界限。", "explanation": "这里应该用〈界碑〉。界碑是立在地上的标志物，界限是线，不能“立”。"}, {"text": "我们沿着这条界限开车去了北京。", "explanation": "这里应该用〈公路〉。公路是可以开车走的路；界限是两个地方分开的地方，不是用来通行的道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "界限", "is_correct": true, "explanation": "正确。这排树是两块地之间的分界，用“界限”。"}, {"text": "收成", "is_correct": false, "explanation": "语义：收成指农作物的产量，不表示两块地的分界。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不能用于描述一排树。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：价钱是交易的数额，与地块之间的分界无关。"}], "explanations": {"界限": "正确。这排树是两块地之间的分界，用“界限”。", "收成": "语义：收成指农作物的产量，不表示两块地的分界。", "身材": "体貌：身材指人的体型，不能用于描述一排树。", "价钱": "语义：价钱是交易的数额，与地块之间的分界无关。"}, "sentence_index": 6, "correct_answer": "界限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条界限流经山谷。", "explanation": "这里应该用〈河流〉。界限是分界，不能“流经”某地；应说“河流流经山谷”。"}, {"text": "农场四周立着一圈界限。", "explanation": "这里应该用〈栅栏〉。栅栏是围起来的实物，界限是分界，不能“立”在农场四周。"}, {"text": "城里有一条界限通往山区。", "explanation": "这里应该用〈铁路〉。铁路可以通往某地，界限不能“通往”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两块地之间有一座界限。", "corrected_sentence": "两块地之间有一条界限。", "error_description": "量词错误：“界限”应用量词“条”，不用“座”；“座”多用于山、桥、楼等大型固定物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人在地上出划一条界限。", "corrected_sentence": "工人在地上划出一条界限。", "error_description": "补语位置错误：“出”是“划”的结果补语，应紧跟“划”，说“划出一条界限”，不说“出划一条界限”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
