INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大家在一起做一件事的一群人。", "primary_collocate": null, "pronunciation": "tuán duì", "ipa": "tʰwan˧˥ twei˥˩", "syllable_count": 2, "sentences": [{"text": "我们是一个很好的团队。", "target_word": "团队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个团队有十个人。", "target_word": "团队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "团队里每个人都很努力。", "target_word": "团队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚加入我们的团队。", "target_word": "团队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这个项目需要团队合作。", "target_word": "团队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的经理很会带团队。", "target_word": "团队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们团队昨天完成了工作。", "target_word": "团队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找一个年轻的团队一起工作。", "target_word": "团队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团队的成功需要大家一起努力。", "target_word": "团队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支团队去年得了第一名。", "target_word": "团队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "团队合作", "label": "复合"}, {"form": "团队精神", "label": "复合"}, {"form": "團隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为同一个目标一起工作的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮料", "is_correct": false, "explanation": "语义：“我们”指人，不能是饮料。"}, {"text": "团队", "is_correct": true, "explanation": "大家在一起做一件事的一群人，这里指“我们”是一个合作良好的群体。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的身体，不能说“我们是一个很好的身高”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，与指人的“我们”不符。"}], "explanations": {"饮料": "语义：“我们”指人，不能是饮料。", "团队": "大家在一起做一件事的一群人，这里指“我们”是一个合作良好的群体。", "身高": "体貌：“身高”描述人的身体，不能说“我们是一个很好的身高”。", "课本": "语义：“课本”是书，与指人的“我们”不符。"}, "sentence_index": 0, "correct_answer": "团队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的团队有三百万，比其他城市都多。", "explanation": "这里应该用〈人口〉。团队指为同一目标合作的一群人，城市的居民总数要用人口。"}, {"text": "我们团队有五口人，每天一起吃饭。", "explanation": "这里应该用〈家庭〉。团队强调为共同目标合作，家人一起生活应说家庭。"}, {"text": "今天的团队很好，阳光明媚。", "explanation": "这里应该用〈天气〉。团队指为同一目标合作的一群人，不能描述气候，今天的气候要用天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：“我们”指人，不能是窗户，句子不成立。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不能完成工作。"}, {"text": "团队", "is_correct": true, "explanation": "为同一目标一起工作的一群人，正好作“我们团队”的中心词并完成工作。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：“蔬菜”不能作为主语去“完成工作”。"}], "explanations": {"窗户": "语义：“我们”指人，不能是窗户，句子不成立。", "河流": "语义：河流是自然景物，不能完成工作。", "团队": "为同一目标一起工作的一群人，正好作“我们团队”的中心词并完成工作。", "蔬菜": "搭配：“蔬菜”不能作为主语去“完成工作”。"}, "sentence_index": 6, "correct_answer": "团队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上的团队很多，把路都挡住了。", "explanation": "这里应该用〈人群〉。团队指为同一目标合作的群体，不指随意聚集在街上的人。"}, {"text": "这个小镇的团队很美，很多游客来拍照。", "explanation": "这里应该用〈风景〉。团队指为同一目标合作的一群人，景色的美丽要用风景。"}, {"text": "这个公园的团队很大，里面种满了花。", "explanation": "这里应该用〈花园〉。团队指为同一目标合作的一群人，不能指种花的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这条团队很有活力。", "corrected_sentence": "我们这支团队很有活力。", "error_description": "量词错误：“团队”应用“支”或“个”计量，“条”用于长条形事物，应说“这支团队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张团队工作很认真。", "corrected_sentence": "那支团队工作很认真。", "error_description": "量词错误：“团队”应用“支”或“个”计量，“张”用于纸、桌子等平面物，应说“那支团队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
