INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人提出的希望、条件或标准。", "primary_collocate": null, "pronunciation": "yāo qiú", "ipa": "jau˥ tɕʰjou˧˥", "syllable_count": 2, "sentences": [{"text": "老师对我们的要求很高。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提了一个小要求。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的要求是八点上班。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个要求我做不到。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的要求不多，只想我早点睡。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有一个要求：不能带狗进去。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么要求，可以告诉我。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会按你的要求去做。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的要求我已经知道了。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的要求不应该都答应。", "target_word": "要求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "提出的希望、条件或标准（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要求", "is_correct": true, "explanation": "“要求”指对人提出的标准，与“很高”搭配，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高度，不能用来说老师对学生的标准。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与老师对学生的标准无关，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不说“很高”，应说“很热”“很冷”之类。"}], "explanations": {"要求": "“要求”指对人提出的标准，与“很高”搭配，符合句意。", "身高": "语义：“身高”指身体的高度，不能用来说老师对学生的标准。", "颜色": "语义：“颜色”与老师对学生的标准无关，句子不成立。", "天气": "搭配：“天气”不说“很高”，应说“很热”“很冷”之类。"}, "sentence_index": 0, "correct_answer": "要求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的要求很明亮。", "explanation": "这里应该用〈光线〉。“明亮”用于光线，不能用来形容“要求”。“要求”是提出的希望、条件或标准。"}, {"text": "这件衣服的要求很便宜。", "explanation": "这里应该用〈价格〉。“便宜”用于价格，不能用来形容要求。"}, {"text": "这种饮料的要求很甜。", "explanation": "这里应该用〈口味〉。“甜”用于口味，不能用来形容要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要求", "is_correct": true, "explanation": "“要求”指提出的希望或条件，询问对方的希望时用它，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能用来询问对方的希望或条件。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“有什么价格”不是常见说法，询问对方的条件时不能用“价格”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与提出希望或条件无关。"}], "explanations": {"要求": "“要求”指提出的希望或条件，询问对方的希望时用它，符合句意。", "味道": "语义：“味道”指气味或滋味，不能用来询问对方的希望或条件。", "价格": "搭配：“有什么价格”不是常见说法，询问对方的条件时不能用“价格”。", "体重": "语义：“体重”指身体的重量，与提出希望或条件无关。"}, "sentence_index": 6, "correct_answer": "要求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋的要求很大。", "explanation": "这里应该用〈尺寸〉。“大”用于尺寸，不能用来形容要求。"}, {"text": "这辆车的要求很快。", "explanation": "这里应该用〈速度〉。“快”用于速度，不能用来形容要求。"}, {"text": "这壶水的要求很烫。", "explanation": "这里应该用〈温度〉。“烫”用于温度，不能用来形容要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了一只要求。", "corrected_sentence": "他提出了一项要求。", "error_description": "“要求”的量词应用“项”或“条”，“只”用于动物或小件物品，不能用来计量“要求”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他又提了一把新要求。", "corrected_sentence": "他又提了一条新要求。", "error_description": "“要求”的量词应用“条”或“项”，“把”用于有柄的物品，不能用来计量“要求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
