INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西自己不想动，或者本来在动的东西没有别人推它，它就会一直保持原来的样子。", "primary_collocate": null, "pronunciation": "guàn xìng", "ipa": "kwan⁵¹ ɕiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "球离开手后还在滚，是因为有惯性。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车刹车了，人却往前倒，这就是惯性。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的箱子很重，惯性大，推不动。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "惯性让跑步的人一下子停不下来。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人推，小车还会靠惯性走一会儿。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车转弯的时候，人会因为惯性往一侧倾斜。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰面很滑，惯性让车滑得很远。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用小球给学生讲惯性。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车不用蹬，也能靠惯性往前走。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不动的东西也有惯性，不推就不动。", "target_word": "惯性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惯性力", "label": "复合"}, {"form": "惯性定律", "label": "复合"}, {"form": "惯性思维", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西没有外力就保持原来样子的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电力", "is_correct": false, "explanation": "语义：电力不能使滚动的球继续运动，与句中的物理现象不合。"}, {"text": "惯性", "is_correct": true, "explanation": "惯性指没有外力时物体保持原来状态的性质，正是球继续滚动的原因。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：“阻力”会让球停下来，与“还在滚”的现象相反。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能作为物体滚动的原因，“有温度”在此不成立。"}], "explanations": {"电力": "语义：电力不能使滚动的球继续运动，与句中的物理现象不合。", "惯性": "惯性指没有外力时物体保持原来状态的性质，正是球继续滚动的原因。", "阻力": "语义：“阻力”会让球停下来，与“还在滚”的现象相反。", "温度": "搭配：“温度”不能作为物体滚动的原因，“有温度”在此不成立。"}, "sentence_index": 0, "correct_answer": "惯性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的惯性很强，一踩油门就窜出去了。", "explanation": "这里应该用〈动力〉。动力能推动车加速；惯性是保持运动状态的性质，不能使车加速。"}, {"text": "子弹的惯性很快，击中目标后穿了过去。", "explanation": "这里应该用〈速度〉。速度说物体运动的快慢，可以说“快”；惯性是保持运动状态的性质，不能用快慢来形容。"}, {"text": "鞋底惯性大，跑步的人一下子就能停下来。", "explanation": "这里应该用〈摩擦力〉。鞋底摩擦力大，人才能迅速停下；惯性是物体保持运动的性质，不能使人停下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦", "is_correct": false, "explanation": "语义：“摩擦”会阻碍滑动，与“冰面很滑，车滑得很远”的原因相反。"}, {"text": "惯性", "is_correct": true, "explanation": "惯性让车在没有足够摩擦时继续滑行，符合“冰面很滑”的语境。"}, {"text": "平衡", "is_correct": false, "explanation": "语义：“平衡”指各方力量相等、不动的状态，不能让车滑得更远。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能让车滑行，与“冰面很滑”的语境不合。"}], "explanations": {"摩擦": "语义：“摩擦”会阻碍滑动，与“冰面很滑，车滑得很远”的原因相反。", "惯性": "惯性让车在没有足够摩擦时继续滑行，符合“冰面很滑”的语境。", "平衡": "语义：“平衡”指各方力量相等、不动的状态，不能让车滑得更远。", "颜色": "语义：颜色不能让车滑行，与“冰面很滑”的语境不合。"}, "sentence_index": 6, "correct_answer": "惯性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "惯性让球落向地面。", "explanation": "这里应该用〈重力〉。重力使物体向地面下落；惯性是物体保持原有运动或静止状态的性质，不会使物体下落。"}, {"text": "刹车时要消耗很多惯性。", "explanation": "这里应该用〈能量〉。能量可以被消耗；惯性是物体的性质，不能被消耗。"}, {"text": "车在冰上滑得远，是因为惯性太小。", "explanation": "这里应该用〈阻力〉。惯性太小反而容易停下，与“滑得远”的结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物体很惯性，所以不会马上停。", "corrected_sentence": "物体有惯性，所以不会马上停。", "error_description": "“惯性”是名词，表示物体具有的性质，应说“物体有惯性”。“物体很惯性”缺少“有”，是错误用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车是很大的惯性，松开油门还会往前滑。", "corrected_sentence": "车有很大的惯性，松开油门还会往前滑。", "error_description": "错误形式：“车是很大的惯性”；正确形式：“车有很大的惯性”。表示物体具有某种性质要用动词“有”，不能用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
