INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22676, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "别人通过电脑或手机发给你的信。", "primary_collocate": null, "pronunciation": "yóu jiàn", "ipa": "joʊ̯˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我今天收到了一封邮件。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把邮件发给经理。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封邮件是谁发来的？", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上先看邮件。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户发来的邮件里有一份合同。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮件里有会议的时间。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的邮件我已经看过了。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没收到你的邮件，请再发一次。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在地铁上用手机回复邮件。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮件太多，我一天看不完。", "target_word": "邮件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一封邮件", "label": "量词"}, {"form": "电子邮件", "label": "复合"}, {"form": "邮件地址", "label": "复合"}, {"form": "郵件", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通过电脑或手机收发的电子信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "量词：“封”用于信件，工资不是信件，不能说“一封工资”。"}, {"text": "邮件", "is_correct": true, "explanation": "正确。“封”用于信件，“邮件”是电子信件，可以用“一封”计量。"}, {"text": "钥匙", "is_correct": false, "explanation": "量词：“封”用于信件，钥匙应用“把”计量，不能说“一封钥匙”。"}, {"text": "包裹", "is_correct": false, "explanation": "搭配：量词“封”用于信件，不能说“一封包裹”，包裹应用“个”来计量。"}], "explanations": {"工资": "量词：“封”用于信件，工资不是信件，不能说“一封工资”。", "邮件": "正确。“封”用于信件，“邮件”是电子信件，可以用“一封”计量。", "钥匙": "量词：“封”用于信件，钥匙应用“把”计量，不能说“一封钥匙”。", "包裹": "搭配：量词“封”用于信件，不能说“一封包裹”，包裹应用“个”来计量。"}, "sentence_index": 0, "correct_answer": "邮件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天收到了一本邮件。", "explanation": "这里应该用〈封〉。邮件按“封”计量，“本”用于书册。"}, {"text": "他每天早上先吃邮件。", "explanation": "“吃”的对象是食物，邮件是信件，不能吃，应与“看”“回复”等动作搭配。"}, {"text": "他在邮件工作，每天很忙。", "explanation": "这里应该用〈邮局〉。“邮件”是信件，不是工作地点，说工作的地方要用“邮局”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "语义：音乐是用耳朵听的，“看过了音乐”说不通，与“看”的对象不符。"}, {"text": "邮件", "is_correct": true, "explanation": "正确。邮件是可以阅读的信件，“看过了”的对象是邮件，与句意相符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音是用耳朵听的，“看过了声音”说不通，与“看”不搭配。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“看”不搭配“歌声”，歌声只能用耳朵听，不能说“看过”。"}], "explanations": {"音乐": "语义：音乐是用耳朵听的，“看过了音乐”说不通，与“看”的对象不符。", "邮件": "正确。邮件是可以阅读的信件，“看过了”的对象是邮件，与句意相符。", "声音": "搭配：声音是用耳朵听的，“看过了声音”说不通，与“看”不搭配。", "歌声": "搭配：“看”不搭配“歌声”，歌声只能用耳朵听，不能说“看过”。"}, "sentence_index": 6, "correct_answer": "邮件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天收到了一台邮件。", "explanation": "这里应该用〈封〉。“台”用于机器和设备，邮件应按“封”计量。"}, {"text": "邮件太多，我一天喝不完。", "explanation": "“喝”与“邮件”不搭配，邮件要看、回复、处理，不能喝。"}, {"text": "我每天早上先给邮件浇水。", "explanation": "“浇水”的对象是植物，邮件是信件，不能浇水。邮件应与“看”“回复”“处理”等动作搭配，例如“我每天早上先看邮件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚刚给老板发了一张邮件。", "corrected_sentence": "我刚刚给老板发了一封邮件。", "error_description": "错误：“邮件”用错了量词“张”。“张”用于纸张等平面物，邮件应该用量词“封”，说“一封邮件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天给我发了一本邮件。", "corrected_sentence": "他昨天给我发了一封邮件。", "error_description": "错误：“本”用于书册，“邮件”应该用量词“封”，说“一封邮件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
