INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个地方的时间不一样。", "primary_collocate": null, "pronunciation": "shí chā", "ipa": "ʂʅ˧˥ ʈʂʰa˥", "syllable_count": 2, "sentences": [{"text": "俄罗斯的时区很多，各地之间都有时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在澳大利亚打电话回家，要先算一下时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是中午，那里是半夜，时差真大。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有时差，所以她这个时候还没起床。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你那儿现在几点？我们有时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开视频会议前，请先算好时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本和中国只有一个小时的时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为时差，他说早上好，我这里却是晚上。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行前，最好先查一下两地的时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在国外的朋友和我有五个小时的时差。", "target_word": "时差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒时差", "label": "复合"}, {"form": "时差反应", "label": "复合"}, {"form": "時差", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个地方的钟点不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时差", "is_correct": true, "explanation": "正确：“各地之间都有时差”指各地钟点不同，与前句“时区很多”的说明相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是按地区分布的时间差，“各地之间都有天气”句意不通。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“各地之间都有”后应接可以分布在各地的具体事物，小说不能这样用。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学与地区间的钟点差异无关，句意不通。"}], "explanations": {"时差": "正确：“各地之间都有时差”指各地钟点不同，与前句“时区很多”的说明相符。", "天气": "语义：天气不是按地区分布的时间差，“各地之间都有天气”句意不通。", "小说": "搭配：“各地之间都有”后应接可以分布在各地的具体事物，小说不能这样用。", "数学": "语义：数学与地区间的钟点差异无关，句意不通。"}, "sentence_index": 0, "correct_answer": "时差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国划分了五个时差。", "explanation": "这里应该用〈时区〉。时差指两地钟点之差，中国划分的区域要用时区。"}, {"text": "这班火车的发车时差是早上八点。", "explanation": "这里应该用〈时刻〉。时差是两地钟点的差距，火车的发车时间点要用时刻。"}, {"text": "晚上七点到九点是最忙的时差。", "explanation": "这里应该用〈时段〉。时差只表示两地钟点的差距，一段时间要用时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时差", "is_correct": true, "explanation": "正确：“一个小时的时差”指两地钟点相差一小时，与句意相符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“一个小时的电影”指片长，与两国之间的钟点差无关，句意不通。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程的长短与两国的钟点差无关，句意不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”不能用时间长度来修饰，“一个小时的人口”不成立。"}], "explanations": {"时差": "正确：“一个小时的时差”指两地钟点相差一小时，与句意相符。", "电影": "语义：“一个小时的电影”指片长，与两国之间的钟点差无关，句意不通。", "课程": "语义：课程的长短与两国的钟点差无关，句意不通。", "人口": "搭配：“人口”不能用时间长度来修饰，“一个小时的人口”不成立。"}, "sentence_index": 6, "correct_answer": "时差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆跑车的时差是每小时两百公里。", "explanation": "这里应该用〈时速〉。时差指两地钟点的差距，每小时行驶多少公里要用时速。"}, {"text": "我们一起度过了快乐的时差。", "explanation": "这里应该用〈时光〉。时差只指钟点之差，不能用来指一段美好的日子。"}, {"text": "我们约好的时差是下午三点。", "explanation": "这里应该用〈时间〉。时差是两地钟点的差距，约定的具体时间要用时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国和日本差一个小时的时差。", "corrected_sentence": "中国和日本有一个小时的时差。", "error_description": "搭配错误：“时差”本身已含“差”的意思，前面不能再用动词“差”，应说“有……的时差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个城市之间有三个小时的时差们。", "corrected_sentence": "这两个城市之间有三个小时的时差。", "error_description": "“时差”是抽象名词，不能加“们”表示复数，应直接说“时差”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
