INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22680, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指某个东西是专门的一个，不是别的。", "primary_collocate": null, "pronunciation": "tè dìng", "ipa": "tʰɤ˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种药只对特定的病有用。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只在特定的日子回家。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门需要特定的钥匙才能打开。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们为特定的客人准备了礼物。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词只用在特定的场合。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特定的时间，这里不让车进来。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在特定的地方等朋友。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件是给特定的人用的。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在特定的天气下，才能看到这种鸟。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书是为特定的学生写的。", "target_word": "特定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "特定的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "专门指定的，不是别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59cd57e6-a11a-4731-b10a-b0c4705d2478') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特定", "is_correct": true, "explanation": "正确：特定修饰「病」，表示专门的、某一种病，与语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：「高兴」形容人的心情，不能修饰病。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：「苗条」形容人的身材，不能用来修饰病。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：「温柔」形容人的性情，与病的种类无关。"}], "explanations": {"特定": "正确：特定修饰「病」，表示专门的、某一种病，与语境相符。", "高兴": "语义：「高兴」形容人的心情，不能修饰病。", "苗条": "体貌：「苗条」形容人的身材，不能用来修饰病。", "温柔": "语义：「温柔」形容人的性情，与病的种类无关。"}, "sentence_index": 0, "correct_answer": "特定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很特定，大家都爱来吃。", "explanation": "这里应该用〈特别〉。特定指专门指定、不是别的，不表示菜的好或特别之处。"}, {"text": "他的性格很特定，大家都觉得他很古怪。", "explanation": "这里应该用〈孤僻〉。特定只表示专门指定、不是别的，不能用来描述人的性格；性格怪僻、不合群要说孤僻。"}, {"text": "这个设计很特定，别的公司都没有。", "explanation": "这里应该用〈独特〉。特定只表示专门指定、不是别的，不用来形容设计的独特之处；表示与众不同要说独特。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特定", "is_correct": true, "explanation": "正确：特定修饰「地方」，表示专门指定的某个地点，与语境相符。"}, {"text": "英俊", "is_correct": false, "explanation": "体貌：「英俊」形容人的外貌，不能用来修饰地方。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：「慷慨」形容人的品质，不能用来修饰地方。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：「聪明」形容人的智力，地方不能聪明，与语境不符。"}], "explanations": {"特定": "正确：特定修饰「地方」，表示专门指定的某个地点，与语境相符。", "英俊": "体貌：「英俊」形容人的外貌，不能用来修饰地方。", "慷慨": "语义：「慷慨」形容人的品质，不能用来修饰地方。", "聪明": "语义：「聪明」形容人的智力，地方不能聪明，与语境不符。"}, "sentence_index": 6, "correct_answer": "特定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇的风景很特定，很多游客都来拍照。", "explanation": "这里应该用〈优美〉。特定只表示专门指定、不是别的，不用来形容风景的美。"}, {"text": "妈妈的手艺很特定，做的饭大家都爱吃。", "explanation": "这里应该用〈拿手〉。特定不能用来评价手艺的水平，技艺高超要说拿手。"}, {"text": "这首歌的旋律很特定，我每次听都会哭。", "explanation": "这里应该用〈动听〉。特定不用来评价旋律好不好听，旋律的好听要说动听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份名单只包括特定了的学生。", "corrected_sentence": "这份名单只包括特定的学生。", "error_description": "体标误用：形容词「特定」作定语时不能加「了」，应直接说「特定的学生」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们只在特定地时间开放。", "corrected_sentence": "我们只在特定的时间开放。", "error_description": "「特定地时间」错误，应改为「特定的时间」。「地」用于状语，修饰名词「时间」要用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
