INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家用强大的力量去欺负别的国家，让别的国家听它的话。", "primary_collocate": null, "pronunciation": "bà quán", "ipa": "pa˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "有的大国用霸权欺负小国，让他们听话。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上很多人反对霸权，不想让别人控制自己。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大国想在世界上搞霸权，别的国家很不满意。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家不会走霸权的路。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，只有平等的国家关系，才没有霸权。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为强国不应该用钱和武器来推行霸权。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国害怕大国的霸权，所以常常联合起来。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着，一百年前有国家靠霸权占了很多地方。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家力量很大，但是从不搞霸权。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人问什么是霸权，可以这样理解：大国欺负小国，让小国服从。", "target_word": "霸权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "霸權", "label": "繁体"}, {"form": "霸权主义", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词；强国欺负并支配其他国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "霸权", "is_correct": true, "explanation": "霸权：强国以力量支配他国，与“欺负小国，让他们听话”相合。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“用……欺负”的手段应是力量或权势，雨伞不能作为欺负他国的手段。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“用……欺负”的手段应是力量或权势，眼镜不能作为欺负的手段。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能用来强迫他国听话，与“欺负小国”的语境不合。"}], "explanations": {"霸权": "霸权：强国以力量支配他国，与“欺负小国，让他们听话”相合。", "雨伞": "搭配：“用……欺负”的手段应是力量或权势，雨伞不能作为欺负他国的手段。", "眼镜": "搭配：“用……欺负”的手段应是力量或权势，眼镜不能作为欺负的手段。", "椅子": "语义：椅子不能用来强迫他国听话，与“欺负小国”的语境不合。"}, "sentence_index": 0, "correct_answer": "霸权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脾气很霸权，一生气就摔东西。", "explanation": "这里应该用〈霸道〉。霸道形容人的性格蛮横，霸权用于国家之间的支配，不用于人的脾气。"}, {"text": "这只狗很霸权，谁都不敢靠近它。", "explanation": "这里应该说〈凶〉。霸权指国家之间的支配，不用来形容狗的凶猛。"}, {"text": "他跑步跑得很霸权，一下子就超过了别人。", "explanation": "霸权不修饰动作，跑步的快慢应该说〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "霸权", "is_correct": true, "explanation": "霸权：大国对小国的支配，是小国害怕并联合起来的原因。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐不构成威胁，小国不会因此害怕大国，与“联合起来”的语境不合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不构成威胁，无法让小国害怕并联合起来。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“害怕”的对象应是力量或威胁，“黑板”不能作为害怕的对象。"}], "explanations": {"霸权": "霸权：大国对小国的支配，是小国害怕并联合起来的原因。", "早餐": "语义：早餐不构成威胁，小国不会因此害怕大国，与“联合起来”的语境不合。", "花朵": "语义：花朵不构成威胁，无法让小国害怕并联合起来。", "黑板": "搭配：“害怕”的对象应是力量或威胁，“黑板”不能作为害怕的对象。"}, "sentence_index": 6, "correct_answer": "霸权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小国的霸权很强，连大国都怕它。", "explanation": "这里应该说〈实力〉。霸权指强国凭借优势支配他国，小国没有支配别国的能力；把“霸权”当成单纯的“力量”来用是误用。"}, {"text": "这块石头很霸权，挡住了整条路。", "explanation": "这里应该说〈大〉。霸权用于国家之间的支配，不用来形容石头的体积。"}, {"text": "今天的天气很霸权，突然下起了大雨。", "explanation": "这里应该说〈猛烈〉。霸权指强国用力量支配他国，不用来形容天气；把它当成“力量很大”的意思是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个大国想建立一只霸权。", "corrected_sentence": "那个大国想建立一种霸权。", "error_description": "错误形式：“一只霸权”；正确形式：“一种霸权”。〈只〉用于动物或成对物品中的一个，抽象的“霸权”应用〈种〉计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们从不吃霸权，只想和平相处。", "corrected_sentence": "他们从不搞霸权，只想和平相处。", "error_description": "错误形式：“从不吃霸权”；正确形式：“从不搞霸权”。“搞”可与“霸权”搭配，“吃”不能与抽象的“霸权”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22684, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显性", "is_correct": true, "explanation": "显性指明显、表现在外面，与「不明显、藏在里面」的意思相反。"}, {"text": "简单", "is_correct": false, "explanation": "简单形容事情不复杂，与隐性没有反义关系。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈形容情绪或场面高涨，与隐性没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外表好看，与隐性没有反义关系。"}], "correct_answer": "显性", "explanations": {"显性": "显性指明显、表现在外面，与「不明显、藏在里面」的意思相反。", "简单": "简单形容事情不复杂，与隐性没有反义关系。", "热烈": "热烈形容情绪或场面高涨，与隐性没有反义关系。", "漂亮": "漂亮形容外表好看，与隐性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
