INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22684, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不明显、藏在里面、不容易被看出来的。", "primary_collocate": null, "pronunciation": "yǐn xìng", "ipa": "in˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个病是隐性的，很难发现。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有一个隐性的问题，大家都没看出来。", "target_word": "隐性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给他的隐性收入比工资还多。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种隐性的错误最难找。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多隐性的费用，买东西时看不出来。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种隐性疾病，一开始没有症状。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隐性的矛盾比公开的吵架更麻烦。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子里有隐性的危险，要小心检查。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里有隐性的规定，新人一开始不知道。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店有隐性消费，付钱前要问清楚。", "target_word": "隐性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐性收入", "label": "复合"}, {"form": "隐性消费", "label": "复合"}], "register": "书面", "sense_fingerprint": "隐性：不明显、藏在里面、不容易被看出来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隐性", "is_correct": true, "explanation": "隐性 yǐn xìng 指不明显、藏在里面、不容易被看出来，是本词的意思。"}, {"text": "阴性", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，阴性指阴的性质，与隐性的意思不同。"}, {"text": "隐形", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，隐形指看不见，如隐形眼镜。"}, {"text": "硬性", "is_correct": false, "explanation": "yǐn 与 yìng 的韵母不同（in 与 ing），声调也不同，硬性指强硬、不易变动。"}], "explanations": {"隐性": "隐性 yǐn xìng 指不明显、藏在里面、不容易被看出来，是本词的意思。", "阴性": "yǐn（第三声）与 yīn（第一声）声调不同，阴性指阴的性质，与隐性的意思不同。", "隐形": "xìng（第四声）与 xíng（第二声）声调不同，隐形指看不见，如隐形眼镜。", "硬性": "yǐn 与 yìng 的韵母不同（in 与 ing），声调也不同，硬性指强硬、不易变动。"}, "sentence_index": null, "correct_answer": "隐性"}, "level_3": {"options": [{"text": "隐性", "is_correct": true, "explanation": "「这个病是隐性的」说明病不明显，与后句「很难发现」相合。"}, {"text": "明显", "is_correct": false, "explanation": "语义：「明显」与后句「很难发现」矛盾，不合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容人或物的外形，不能用来形容病。"}, {"text": "热情", "is_correct": false, "explanation": "语义：「热情」形容人的态度，不能用来形容病。"}], "explanations": {"隐性": "「这个病是隐性的」说明病不明显，与后句「很难发现」相合。", "明显": "语义：「明显」与后句「很难发现」矛盾，不合句意。", "高大": "体貌：「高大」形容人或物的外形，不能用来形容病。", "热情": "语义：「热情」形容人的态度，不能用来形容病。"}, "sentence_index": 0, "correct_answer": "隐性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵躲在隐性的山洞里。", "explanation": "这里应该用〈隐蔽〉。隐性说的是不易察觉的性质，形容地方要用隐蔽。"}, {"text": "他性格很隐性。", "explanation": "这里应该用〈内向〉。隐性用于不易察觉的事物，形容人的性格要用内向。"}, {"text": "这座城堡很隐性。", "explanation": "这里应该用〈神秘〉。隐性指不易察觉的性质，形容地方的气氛要用神秘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐性", "is_correct": true, "explanation": "「隐性的矛盾」指不公开、不易察觉的矛盾，与后句「比公开的吵架更麻烦」相合。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：「活泼」形容人或动物的性格，不能用来形容矛盾。"}, {"text": "圆形", "is_correct": false, "explanation": "体貌：「圆形」指物体的形状，不能用来形容矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：「漂亮」形容外表好看，不能用来形容矛盾。"}], "explanations": {"隐性": "「隐性的矛盾」指不公开、不易察觉的矛盾，与后句「比公开的吵架更麻烦」相合。", "活泼": "语义：「活泼」形容人或动物的性格，不能用来形容矛盾。", "圆形": "体貌：「圆形」指物体的形状，不能用来形容矛盾。", "漂亮": "语义：「漂亮」形容外表好看，不能用来形容矛盾。"}, "sentence_index": 6, "correct_answer": "隐性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他隐性地喊了一声。", "explanation": "这里应该用〈大声〉。隐性用于不易察觉的事物，声音响亮要用大声。"}, {"text": "他花了隐性的三天。", "explanation": "这里应该用〈整整〉。隐性指不易察觉，表示整段时间要用整整。"}, {"text": "这块蛋糕很隐性。", "explanation": "这里应该用〈甜〉。隐性指不易察觉的性质，形容味道要用甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种感染是隐性地，症状很轻。", "corrected_sentence": "这种感染是隐性的，症状很轻。", "error_description": "错误形式：「隐性地」；正确形式：「隐性的」。「是」后面接形容词作谓语时要加「的」；「地」是副词词尾，只修饰后面的动词，这里没有动词，应改为「隐性的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店有很隐性收费，付钱前要问清楚。", "corrected_sentence": "这家店有隐性收费，付钱前要问清楚。", "error_description": "错误形式：「很隐性收费」；正确形式：「隐性收费」。「隐性」作定语修饰名词「收费」时，前面不能再加「很」，否则要加「的」；这里应去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
