INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西拆开，看看它里面有什么。", "primary_collocate": null, "pronunciation": "jiě gòu", "ipa": "tɕjɛ˨˩˦ kou˥˩", "syllable_count": 2, "sentences": [{"text": "老师带我们解构这首诗。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢解构电影里的故事。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先解构这个问题，再找办法。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家常常解构老故事。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了学习，他把那首歌解构了一遍。", "target_word": "解构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解构一个广告，能看出它怎么吸引人。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一个下午解构了这篇文章。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们正在解构一个很难的句子。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "设计师先解构旧产品，再做新的。", "target_word": "解构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想懂这部小说，就要一层一层地解构它。", "target_word": "解构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解构了", "label": "体标（了）"}, {"form": "解构过", "label": "体标（过）"}, {"form": "解构着", "label": "体标（着）"}, {"form": "解構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "动词，指把作品、问题等拆开来分析其内部结构和内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解构", "is_correct": true, "explanation": "正确：解构指把东西拆开来分析内部结构。"}, {"text": "结构", "is_correct": false, "explanation": "结构（jiégòu）指事物各部分的组成方式。jié 与 jiě 声调不同。"}, {"text": "接口", "is_correct": false, "explanation": "接口（jiēkǒu）指连接的地方。jiē 与 jiě 声调不同，kǒu 与 gòu 声母、声调不同。"}, {"text": "解扣", "is_correct": false, "explanation": "解扣（jiěkòu）指解开纽扣。kòu 与 gòu 声母不同（k／g）。"}], "explanations": {"解构": "正确：解构指把东西拆开来分析内部结构。", "结构": "结构（jiégòu）指事物各部分的组成方式。jié 与 jiě 声调不同。", "接口": "接口（jiēkǒu）指连接的地方。jiē 与 jiě 声调不同，kǒu 与 gòu 声母、声调不同。", "解扣": "解扣（jiěkòu）指解开纽扣。kòu 与 gòu 声母不同（k／g）。"}, "sentence_index": null, "correct_answer": "解构"}, "level_3": {"options": [{"text": "解构", "is_correct": true, "explanation": "正确：“解构”可以拆开分析诗的内部结构，句意通顺。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修好坏了的东西，诗不能被修理。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”的对象是植物，不能说种诗。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是可以吃的东西，不能说吃这首诗。"}], "explanations": {"解构": "正确：“解构”可以拆开分析诗的内部结构，句意通顺。", "修理": "语义：“修理”指修好坏了的东西，诗不能被修理。", "种": "搭配：“种”的对象是植物，不能说种诗。", "吃": "搭配：“吃”的对象是可以吃的东西，不能说吃这首诗。"}, "sentence_index": 0, "correct_answer": "解构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大火解构了整个仓库。", "explanation": "这里应该用〈毁坏〉。解构是拆开来看内部结构、进行分析，不表示破坏。"}, {"text": "医生解构了他的病。", "explanation": "这里应该用〈治疗〉。解构指拆开分析，不表示给人治病。"}, {"text": "他一口气解构了三碗热汤。", "explanation": "这里应该用〈喝〉。解构指拆开分析，不表示喝下去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解构", "is_correct": true, "explanation": "正确：“解构”可以拆开分析文章，句意通顺。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说喝文章。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服等，不能说穿文章。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，不能施加于文章。"}], "explanations": {"解构": "正确：“解构”可以拆开分析文章，句意通顺。", "喝": "搭配：“喝”的对象是饮品，不能说喝文章。", "穿": "搭配：“穿”的对象是衣服等，不能说穿文章。", "哭": "语义：“哭”指流泪，不能施加于文章。"}, "sentence_index": 6, "correct_answer": "解构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友解构了伤心的他。", "explanation": "这里应该用〈安慰〉。解构不用于人，也不表示安慰。"}, {"text": "他正在大口解构新鲜空气。", "explanation": "这里应该用〈呼吸〉。解构指拆开分析，不表示吸入空气。"}, {"text": "大家热烈解构新同学。", "explanation": "这里应该用〈欢迎〉。解构指分析事物的内部结构，不表示接待或欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该先把解构这份报告，再提建议。", "corrected_sentence": "我们应该先解构这份报告，再提建议。", "error_description": "把字句残缺：“把”后缺少宾语，应去掉“把”，说“解构这份报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用两个小时被解构这本书。", "corrected_sentence": "他用两个小时解构这本书。", "error_description": "被字句误用：“被”后直接接动词加宾语不成立，应去掉“被”，说“解构这本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
