INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人说的话或问题做出回答。", "primary_collocate": null, "pronunciation": "huí fù", "ipa": "xweɪ̯˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "老师问了一个问题，我不知道怎么回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话让我很难回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对朋友的批评，她只是笑着回复了一句。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者的问题很多，他一一回复了。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在微信上问我想吃什么，我回复说都可以。", "target_word": "回复", "complexity_tier": "T3", "furigana": "Māma zài wēixìn shàng wèn wǒ xiǎng chī shénme, wǒ huífù shuō dōu kěyǐ.", "sentence_source": "generated"}, {"text": "对这个问题，你准备怎么回复他？", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的问题太突然了，我一时没法回复。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真地回复了每一位同学的提问。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等你回复这个建议。", "target_word": "回复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在微信上邀请我，我马上回复说好。", "target_word": "回复", "complexity_tier": "T3", "furigana": "Tā zài wēixìn shàng yāoqǐng wǒ, wǒ mǎshàng huífù shuō hǎo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "回复了", "label": "体标（了）"}, {"form": "回复过", "label": "体标（过）"}, {"form": "回覆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对别人说的话或提问作出回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确答案：回复 huí fù，指对别人的话或问题作出回答。"}, {"text": "回府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是回到住所。"}, {"text": "回顾", "is_correct": false, "explanation": "gù 与 fù 声母不同（g 与 f），意思是回头看、回想。"}, {"text": "回护", "is_correct": false, "explanation": "hù 与 fù 声母不同（h 与 f），意思是袒护、包庇。"}, {"text": "回路", "is_correct": false, "explanation": "lù 与 fù 声母不同（l 与 f），意思是电路或往返的路线。"}, {"text": "汇付", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是汇款付款。"}], "explanations": {"回复": "正确答案：回复 huí fù，指对别人的话或问题作出回答。", "回府": "fǔ（第三声）与 fù（第四声）声调不同，意思是回到住所。", "回顾": "gù 与 fù 声母不同（g 与 f），意思是回头看、回想。", "回护": "hù 与 fù 声母不同（h 与 f），意思是袒护、包庇。", "回路": "lù 与 fù 声母不同（l 与 f），意思是电路或往返的路线。", "汇付": "huì（第四声）与 huí（第二声）声调不同，意思是汇款付款。"}, "sentence_index": null, "correct_answer": "回复"}, "level_3": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确：“不知道怎么回复”指不知道如何答复老师的问题，与句中的提问相符。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：拍照与老师的提问无关，句意不通。"}, {"text": "点赞", "is_correct": false, "explanation": "搭配：“点赞”用于动态、帖子，不能用来回应一个问题。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：演唱与老师的提问没有联系，前后句意不通。"}], "explanations": {"回复": "正确：“不知道怎么回复”指不知道如何答复老师的问题，与句中的提问相符。", "拍照": "语义：拍照与老师的提问无关，句意不通。", "点赞": "搭配：“点赞”用于动态、帖子，不能用来回应一个问题。", "演唱": "语义：演唱与老师的提问没有联系，前后句意不通。"}, "sentence_index": 0, "correct_answer": "回复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被对方推了一把，立刻回复了一掌。", "explanation": "这里应该用〈回击〉。回复指答复，对推打的还击要用回击。"}, {"text": "他用微笑回复了我的帮助。", "explanation": "这里应该用〈回报〉。回复指答复，报答别人的帮助要用回报。"}, {"text": "朋友送了我礼物，我也回复了一份。", "explanation": "这里应该用〈回礼〉。回复指答复，回送礼物要用回礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回复", "is_correct": true, "explanation": "正确：前句说问题太突然，“一时没法回复”正是指无法立即答复。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与她突然提出的问题无关，句意不通。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是视频、音乐，不能用于问题。"}, {"text": "刷牙", "is_correct": false, "explanation": "语义：刷牙与问题毫无关系，句意不通。"}], "explanations": {"回复": "正确：前句说问题太突然，“一时没法回复”正是指无法立即答复。", "跳舞": "语义：跳舞与她突然提出的问题无关，句意不通。", "播放": "搭配：“播放”的对象是视频、音乐，不能用于问题。", "刷牙": "语义：刷牙与问题毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "回复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿饭的味道，我至今还在回复。", "explanation": "这里应该用〈回味〉。回复指答复，回想、品味过去的经历要用回味。"}, {"text": "这些旧报纸要回复利用。", "explanation": "这里应该用〈回收〉。回复指答复，把废品重新利用要用回收。"}, {"text": "他伤愈后终于回复了赛场。", "explanation": "这里应该用〈回归〉。回复不表示重新回到某处，运动员重返赛场要用回归。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没回复了老师的问题呢。", "corrected_sentence": "我还没回复老师的问题呢。", "error_description": "“没”字句中不能与“了”同用，“还没”后的动词应直接说“回复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经回复了了我的问题。", "corrected_sentence": "老师已经回复了我的问题。", "error_description": "“了”重复：“回复了”后只需一个“了”，不能在“回复了”后再加一个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "反思就是自己想想自己做得好不好，反思性就是喜欢这样想的特点。", "primary_collocate": null, "pronunciation": "fǎn sī xìng", "ipa": "fan²¹⁴ sz̩⁵⁵ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "他很有反思性，每天晚上都想想自己做得好不好。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小林的反思性很强，考试后会先找自己的问题。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有反思性的人，做错事以后不会怪别人。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子越来越有反思性了，会自己说错在哪里。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，我们需要有反思性的新同事。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的反思性让她每次都比上次做得更好。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记可以提高你的反思性。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有反思性，总是觉得错的是别人。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，教练夸他有反思性，没有找借口。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反思性强的学生，成绩常常进步得很快。", "target_word": "反思性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反思性思维", "label": "复合"}, {"form": "反思性实践", "label": "复合"}], "register": "中性", "sense_fingerprint": "喜欢想想自己做得好不好的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻击性", "is_correct": false, "explanation": "语义：“攻击性”指好斗、伤害他人的倾向，与“每天晚上想想自己做得好不好”无关。"}, {"text": "反思性", "is_correct": true, "explanation": "反思性指喜欢反省自己的特点，与“每天晚上想想自己做得好不好”一致。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指做事随便，与“每天晚上都想想自己做得好不好”相矛盾。"}, {"text": "形象性", "is_correct": false, "explanation": "搭配：“形象性”多用于艺术、语言作品，不说人“有形象性”。"}], "explanations": {"攻击性": "语义：“攻击性”指好斗、伤害他人的倾向，与“每天晚上想想自己做得好不好”无关。", "反思性": "反思性指喜欢反省自己的特点，与“每天晚上想想自己做得好不好”一致。", "随意性": "语义：“随意性”指做事随便，与“每天晚上都想想自己做得好不好”相矛盾。", "形象性": "搭配：“形象性”多用于艺术、语言作品，不说人“有形象性”。"}, "sentence_index": 0, "correct_answer": "反思性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子越来越有反思性了，总想赢过同学。", "explanation": "这里应该用〈竞争性〉。竞争性指争胜的特点；反思性指对自己的反省，与“想赢过同学”的意思不符。"}, {"text": "这种反应越来越有反思性了，不需要经过大脑。", "explanation": "这里应该用〈反射性〉。反射性指不经大脑的被动反应，反思性指主动思考，两者不能互换。"}, {"text": "这位评论家越来越有反思性了，专门挑别人作品的毛病。", "explanation": "这里应该用〈批判性〉。批判性指对别人或作品提出质疑，反思性指对自己的反省。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地方性", "is_correct": false, "explanation": "语义：“地方性”指地域特色，不指一个人的内在特点。"}, {"text": "反思性", "is_correct": true, "explanation": "反思性指反省自己的特点，“提高反思性”是常见搭配，符合句意。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指出乎意料的特点，不是人能靠写日记提高的能力。"}, {"text": "衰退性", "is_correct": false, "explanation": "搭配：“提高”是向上的变化，“衰退性”是向下的性质，二者不搭配。"}], "explanations": {"地方性": "语义：“地方性”指地域特色，不指一个人的内在特点。", "反思性": "反思性指反省自己的特点，“提高反思性”是常见搭配，符合句意。", "偶然性": "语义：“偶然性”指出乎意料的特点，不是人能靠写日记提高的能力。", "衰退性": "搭配：“提高”是向上的变化，“衰退性”是向下的性质，二者不搭配。"}, "sentence_index": 6, "correct_answer": "反思性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个旧问题的反思性很强，每年都会重新出现。", "explanation": "这里应该用〈反复性〉。反复性指同样的情况一再出现；反思性指对自己的反省，不能用来说问题。"}, {"text": "这种皮肤的反思性很强，一碰就发红。", "explanation": "这里应该用〈敏感性〉。敏感性指对刺激反应强烈；反思性指人的自省，不能用于皮肤。"}, {"text": "这条消息的反思性很强，今天就过期了。", "explanation": "这里应该用〈时效性〉。时效性指有效的时间长短，消息说的是时效，不是反思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很有的反思性，做错题后会认真分析原因。", "corrected_sentence": "他很有反思性，做错题后会认真分析原因。", "error_description": "“有”后直接接“的”，“很有的反思性”不成立；应为“很有反思性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班的学生都有很强反思性，遇到问题先找自己。", "corrected_sentence": "这个班的学生都有很强的反思性，遇到问题先找自己。", "error_description": "“很强”作定语修饰名词时，要在修饰语后加“的”，应为“很强的反思性”。漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
