INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "从表面到底部或最里面的距离。", "primary_collocate": null, "pronunciation": "shēn dù", "ipa": "ʂən˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这条河的深度是三米。", "target_word": "深度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你知道这个湖的深度吗？", "target_word": "深度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水的深度不到一米，孩子可以玩。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用尺子量了一下井的深度。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个洞的深度有五米，别靠近。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海的深度比我想的大得多。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游泳池的深度不适合小孩。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，河水的深度变大了。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子的深度是二十厘米。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生看了伤口的深度，说不用担心。", "target_word": "深度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "深度：从表面到底部的距离（水深、井深）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '461c370f-be46-4e41-96a9-fb0d343458d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深度", "is_correct": true, "explanation": "正确：指河从水面到河底的距离，与“三米”的数值相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不以长度计量，与河的深浅无关。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”以度计量，不用米计量河的深浅。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不与长度数值搭配，“河的味道是三米”说不通。"}], "explanations": {"深度": "正确：指河从水面到河底的距离，与“三米”的数值相合。", "颜色": "语义：“颜色”不以长度计量，与河的深浅无关。", "温度": "语义：“温度”以度计量，不用米计量河的深浅。", "味道": "搭配：“味道”不与长度数值搭配，“河的味道是三米”说不通。"}, "sentence_index": 0, "correct_answer": "深度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔的深度有一百米。", "explanation": "这里应该用〈高度〉。深度指从表面到底部的距离，说建筑从底到顶的高矮要用“高度”。"}, {"text": "这条路的深度有十公里，很远。", "explanation": "这里应该用〈长度〉。深度指从表面到底部的距离，道路的长短要用“长度”或“路程”。"}, {"text": "这块地的深度有一百平方米。", "explanation": "这里应该用〈面积〉。深度是距离，以米计量；说地的大小要用“面积”，以平方米计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深度", "is_correct": true, "explanation": "正确：指水池从水面到池底的距离，水太深才“不适合小孩”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的时间长短，不指游泳池的水深。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”只用于人，不能说游泳池的学历。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不用于游泳池。"}], "explanations": {"深度": "正确：指水池从水面到池底的距离，水太深才“不适合小孩”。", "年龄": "语义：“年龄”指存在的时间长短，不指游泳池的水深。", "学历": "搭配：“学历”只用于人，不能说游泳池的学历。", "体重": "搭配：“体重”用于人或动物，不用于游泳池。"}, "sentence_index": 6, "correct_answer": "深度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的深度有七十度，很烫。", "explanation": "这里应该用〈温度〉。深度指从表面到底部的距离，水的冷热要用“温度”，以“摄氏度”计量。"}, {"text": "他的深度一米八，很高。", "explanation": "这里应该用〈身高〉。深度指从表面到底部的距离，说人从脚到头的高矮要用“身高”。"}, {"text": "这个西瓜的深度有五公斤。", "explanation": "这里应该用〈重量〉。深度指从表面到底部的距离，西瓜有多重要用“重量”，以公斤计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这口井的深度有十只，村里人都知道。", "corrected_sentence": "这口井的深度有十米，村里人都知道。", "error_description": "错误：计量单位“只”；正确：“米”。深度是长度，要用“米”计量，“只”用于动物等，不能计量深度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖的深度有五十个，很少有人下水。", "corrected_sentence": "这个湖的深度有五十米，很少有人下水。", "error_description": "错误：计量单位“个”；正确：“米”。深度是长度，要用“米”计量，“个”不能计量长度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
