INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人听你的话，并按照你的要求去做。", "primary_collocate": null, "pronunciation": "guī xùn", "ipa": "kweɪ̯˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "父母总想规训自己的孩子。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用严格的规矩规训学生。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想规训新来的员工，让他们听话。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能这样规训别人，大家都有自己的想法。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练把队员规训得很听话。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想用批评来规训丈夫，结果吵了一架。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想规训员工，让大家按他的话做。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢规训晚辈，什么都要听他的。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用命令的口气规训同事，大家都不高兴。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长不应该用打骂的方法规训孩子。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "规训了", "label": "体标（了）"}, {"form": "规训过", "label": "体标（过）"}, {"form": "規訓", "label": "繁体"}], "register": "书面", "sense_fingerprint": "让别人听话并照自己的要求行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规训", "is_correct": true, "explanation": "正确：“规训”指让人听话、按要求去做，与“父母总想”和“自己的孩子”搭配，句意通顺。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，不能用来指父母对孩子的管束，句意不通。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的对象是石头、木材等材料，不能用于“孩子”。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指输出文件或图片，与父母想让孩子听话的意图无关。"}], "explanations": {"规训": "正确：“规训”指让人听话、按要求去做，与“父母总想”和“自己的孩子”搭配，句意通顺。", "翻译": "语义：“翻译”指转换语言，不能用来指父母对孩子的管束，句意不通。", "雕刻": "搭配：“雕刻”的对象是石头、木材等材料，不能用于“孩子”。", "打印": "语义：“打印”指输出文件或图片，与父母想让孩子听话的意图无关。"}, "sentence_index": 0, "correct_answer": "规训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教练每天规训队员的体能。", "explanation": "这里应该用〈训练〉。规训是让人服从要求，锻炼体能要用“训练”。"}, {"text": "他每天早上规训房间。", "explanation": "这里应该用〈打扫〉。规训的对象是人，不能用于整理房间。"}, {"text": "她每天规训衣服。", "explanation": "这里应该用〈缝补〉。规训的对象是人，缝补衣服要用“缝补”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规训", "is_correct": true, "explanation": "正确：“规训”指让员工服从老板的要求，与“让大家按他的话做”相符。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不说“饲养员工”。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”用于种子或田地，不能用于员工。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指制作面包糕点，与“让大家按他的话做”的语境无关。"}], "explanations": {"规训": "正确：“规训”指让员工服从老板的要求，与“让大家按他的话做”相符。", "饲养": "搭配：“饲养”用于动物，不说“饲养员工”。", "播种": "搭配：“播种”用于种子或田地，不能用于员工。", "烘焙": "语义：“烘焙”指制作面包糕点，与“让大家按他的话做”的语境无关。"}, "sentence_index": 6, "correct_answer": "规训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天规训晚饭。", "explanation": "这里应该用〈烹饪〉。规训的对象是人，不能用于做饭。"}, {"text": "他规训了坏掉的自行车。", "explanation": "这里应该用〈修理〉。规训不能用于机械设备，修车要用“修理”。"}, {"text": "农民每天规训庄稼。", "explanation": "这里应该用〈浇灌〉。规训的对象是人，浇灌庄稼要用“浇灌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把儿子规训很有礼貌。", "corrected_sentence": "他把儿子规训得很有礼貌。", "error_description": "缺补语标记“得”：动词后接状态补语时要用“得”，应说“规训得很有礼貌”，不能直接说“规训很有礼貌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前规训着新来的员工，让他们听话。", "corrected_sentence": "他以前规训过新来的员工，让他们听话。", "error_description": "体标错误：“以前”指过去的经历，应用经历体“过”，不能用表示持续的“着”，应说“规训过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人文意思是人类的文化和生活方式。", "primary_collocate": null, "pronunciation": "rén wén", "ipa": "ʐən˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "旅行时，我喜欢了解当地的人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的自然风景和人文都很有名。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客对中国的人文很感兴趣。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方和北方的人文很不一样。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条老街保留着很多人文特色。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志介绍世界各地的风景和人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去山区，不但看了风景，还体验了当地人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的人文风貌让游客着迷。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言也是在认识一个国家的人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了很多照片，记录下小城的人文风情。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人文主义", "label": "复合"}, {"form": "人文精神", "label": "复合"}, {"form": "人文学科", "label": "复合"}], "register": "书面", "sense_fingerprint": "一个地方或民族的文化与生活方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”与“旅行时喜欢了解当地”的语境不合，不能说“了解当地的作业”。"}, {"text": "人文", "is_correct": true, "explanation": "“当地的人文”指一地的文化与生活方式，正是旅行时想了解的内容。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是消费记录，与旅行时了解当地的兴趣不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“了解”的对象多是地方或人的情况，“体重”不能作“了解当地的”的宾语。"}], "explanations": {"作业": "语义：“作业”与“旅行时喜欢了解当地”的语境不合，不能说“了解当地的作业”。", "人文": "“当地的人文”指一地的文化与生活方式，正是旅行时想了解的内容。", "账单": "语义：“账单”是消费记录，与旅行时了解当地的兴趣不合。", "体重": "搭配：“了解”的对象多是地方或人的情况，“体重”不能作“了解当地的”的宾语。"}, "sentence_index": 0, "correct_answer": "人文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇的人文有三万。", "explanation": "这里应该用〈人口〉。“人文”指一地的文化与生活方式，不能用来表示人数。"}, {"text": "这个地方的人文很湿润。", "explanation": "这里应该用〈气候〉。“湿润”形容气候或空气，不能形容文化与生活方式。"}, {"text": "这里的人文很高。", "explanation": "这里应该用〈海拔〉。“人文”不能表示地势的高低，说高低要用“海拔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考勤", "is_correct": false, "explanation": "语义：“考勤”是单位的管理制度，与山区旅游的语境不合，不能说“体验了当地考勤”。"}, {"text": "人文", "is_correct": true, "explanation": "“当地人文”是山区的文化与生活方式，与“看了风景”形成对照，是要体验的内容。"}, {"text": "方程", "is_correct": false, "explanation": "语义：“方程”是数学概念，不能被“体验”，与旅行语境不合。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“体验”多接生活、文化、风土等，不说“体验当地工资”。"}], "explanations": {"考勤": "语义：“考勤”是单位的管理制度，与山区旅游的语境不合，不能说“体验了当地考勤”。", "人文": "“当地人文”是山区的文化与生活方式，与“看了风景”形成对照，是要体验的内容。", "方程": "语义：“方程”是数学概念，不能被“体验”，与旅行语境不合。", "工资": "搭配：“体验”多接生活、文化、风土等，不说“体验当地工资”。"}, "sentence_index": 6, "correct_answer": "人文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几天的人文很热，大家都想出门。", "explanation": "这里应该用〈天气〉。“天气”指一段时间内的冷暖阴晴，形容天热要用“天气”；“人文”指文化与生活方式，不能形容冷暖。"}, {"text": "他这学期的人文增加了三公斤。", "explanation": "这里应该用〈体重〉。“体重”指人身体的重量，增加几公斤要用“体重”；“人文”指文化与生活方式，不能计算重量。"}, {"text": "这盘菜的人文太咸了。", "explanation": "这里应该用〈味道〉。“味道”指食物的滋味，说咸要用“味道”；“人文”指文化与生活方式，不能形容滋味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这座城市里感受到一把独特的人文。", "corrected_sentence": "他在这座城市里感受到一种独特的人文。", "error_description": "量词错误：“人文”指一地的文化与生活方式，应用“种”，不能用“把”（“把”用于有柄的器具）。应改为“一种独特的人文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个古镇独特地人文很迷人。", "corrected_sentence": "这个古镇独特的人文很迷人。", "error_description": "结构助词错误：“独特”修饰名词“人文”，应用“的”，不能用“地”（“地”用在状语后面）。应改为“独特的人文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适度", "is_correct": true, "explanation": "反义：“适度”表示恰当、不超过限度，与“过度”的意思相反。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”与“过度”的任何意思都不构成反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”描述的是清洁状态，与“过度”的意思没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”描述的是光线或颜色，与“过度”的意思没有反义关系。"}], "correct_answer": "适度", "explanations": {"适度": "反义：“适度”表示恰当、不超过限度，与“过度”的意思相反。", "聪明": "无关：“聪明”与“过度”的任何意思都不构成反义关系。", "干净": "无关：“干净”描述的是清洁状态，与“过度”的意思没有反义关系。", "明亮": "无关：“明亮”描述的是光线或颜色，与“过度”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适度", "is_correct": true, "explanation": "反义：“适度”表示恰当、不超过限度，与“过度”的意思相反。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：“整齐”描述的是排列或外观，与“过度”的意思没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”描述的是声音或环境，与“过度”的意思没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”描述的是明白或分明的状态，与“过度”的意思没有反义关系。"}], "correct_answer": "适度", "explanations": {"适度": "反义：“适度”表示恰当、不超过限度，与“过度”的意思相反。", "整齐": "无关：“整齐”描述的是排列或外观，与“过度”的意思没有反义关系。", "安静": "无关：“安静”描述的是声音或环境，与“过度”的意思没有反义关系。", "清楚": "无关：“清楚”描述的是明白或分明的状态，与“过度”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "太多，超过了正常限度。", "primary_collocate": null, "pronunciation": "guò dù", "ipa": "kwo˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "过度喝酒对身体不好。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作过度劳累，生病了。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度玩手机会伤害眼睛。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动不能过度，不然会受伤。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度的紧张让她睡不着觉。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃糖过度，牙齿会坏。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对孩子过度保护。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度节食对身体没有好处。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为过度担心，一晚上没睡。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度用力会让手受伤。", "target_word": "过度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过度疲劳", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事或程度超过正常限度，太多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过度", "is_correct": true, "explanation": "过度表示超过正常限度，与“喝酒对身体不好”的句意相符，是正确答案。"}, {"text": "适度", "is_correct": false, "explanation": "语义：“适度”表示恰到好处、不超过限度，与“对身体不好”的句意相反。"}, {"text": "轻松", "is_correct": false, "explanation": "搭配：“轻松喝酒”不是常见说法，句子说的是过量饮酒的危害。"}, {"text": "精心", "is_correct": false, "explanation": "搭配：“精心”修饰的是细致做事，不能修饰“喝酒”，句意不通。"}], "explanations": {"过度": "过度表示超过正常限度，与“喝酒对身体不好”的句意相符，是正确答案。", "适度": "语义：“适度”表示恰到好处、不超过限度，与“对身体不好”的句意相反。", "轻松": "搭配：“轻松喝酒”不是常见说法，句子说的是过量饮酒的危害。", "精心": "搭配：“精心”修饰的是细致做事，不能修饰“喝酒”，句意不通。"}, "sentence_index": 0, "correct_answer": "过度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的人数过度，会场都坐不下了。", "explanation": "这里应该用〈过多〉。人数、数量用“过多”，“过度”多修饰做法、态度或程度，不说“人数过度”。"}, {"text": "他背的书包过度，压得肩膀都疼了。", "explanation": "这里应该用〈过重〉。物体的重量超出用“过重”，“过度”不用来修饰物体的重量。"}, {"text": "这件衣服的价格过度，我买不起。", "explanation": "这里应该用〈过高〉。价格的高低用“过高”，“过度”多修饰做法、行为或程度，不用来描述价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过度", "is_correct": true, "explanation": "过度表示超过正常限度，与“对孩子保护”的句意相符，是正确答案。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与“保护”的感情色彩相反，“对孩子冷淡保护”句意不通。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：“随意”不用来修饰“保护”这类动作，“随意保护孩子”不是常见说法。"}, {"text": "无奈", "is_correct": false, "explanation": "搭配：“无奈”表示心情，不能修饰“保护”，句意不通。"}], "explanations": {"过度": "过度表示超过正常限度，与“对孩子保护”的句意相符，是正确答案。", "冷淡": "语义：“冷淡”与“保护”的感情色彩相反，“对孩子冷淡保护”句意不通。", "随意": "搭配：“随意”不用来修饰“保护”这类动作，“随意保护孩子”不是常见说法。", "无奈": "搭配：“无奈”表示心情，不能修饰“保护”，句意不通。"}, "sentence_index": 6, "correct_answer": "过度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次检测中，水里的铅含量过度。", "explanation": "这里应该用〈超标〉。含量、指标超出标准用“超标”，“过度”不用来描述数值指标。"}, {"text": "这辆卡车过度了，不能上路。", "explanation": "这里应该用〈超载〉。车辆装载超出限度用“超载”，“过度”不直接修饰车辆的装载。"}, {"text": "这个班的进度过度，大家都跟不上。", "explanation": "这里应该用〈过快〉。进度的快慢用“过快”，“过度”指超过正常限度，不用来描述进度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这段时间工作过度很多，累病了。", "corrected_sentence": "他这段时间工作过度，累病了。", "error_description": "重复错误：“过度”已表示超出限度，不能再接“很多”，应删去“很多”，改为“工作过度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工作过度的，累病了。", "corrected_sentence": "他工作过度，累病了。", "error_description": "“的”错误：“过度”作谓语时后面不能加“的”，应说“工作过度”，加上“的”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
