INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "温度是表示物体有多热或者多冷的数字。", "primary_collocate": null, "pronunciation": "wēn dù", "ipa": "wən˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "天气预报说明天温度很低。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的温度到一百度就会开。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间温度太高了。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道今天的温度是多少吗？", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的温度常常超过三十五度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的温度很低。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度越高，冰化得越快。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机看外面的温度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的温度不冷也不热。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡水的温度刚刚好。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温度计", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示物体热或冷程度的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd79aa37-f94d-4d21-b269-7476dce0f4e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": true, "explanation": "“温度”指冷热的数字，“明天温度很低”说的是气温低，符合语境。"}, {"text": "人气", "is_correct": false, "explanation": "语义：人气指受欢迎的程度，天气预报不会说明人气的高低。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩指学习或比赛的结果，与天气无关。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“很低”不能修饰“面积”，面积一般说“大小”。"}], "explanations": {"温度": "“温度”指冷热的数字，“明天温度很低”说的是气温低，符合语境。", "人气": "语义：人气指受欢迎的程度，天气预报不会说明人气的高低。", "成绩": "语义：成绩指学习或比赛的结果，与天气无关。", "面积": "搭配：“很低”不能修饰“面积”，面积一般说“大小”。"}, "sentence_index": 0, "correct_answer": "温度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯糖水的温度很浓。", "explanation": "这里应该用〈浓度〉。温度只说冷热，溶液的甜淡、浓淡要用浓度，不能说“很浓”。"}, {"text": "这首歌现在的温度是多少呢？", "explanation": "这里应该用〈热度〉。温度不能用来表示歌曲受欢迎的程度。"}, {"text": "这篇文章的温度是三千字。", "explanation": "这里应该用〈字数〉。温度只说冷热，文章有多少字要用字数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": true, "explanation": "“温度越高”说明冷热的程度，温度越高冰化得越快，符合语境。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指明暗的程度，与冰化的快慢无关。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，与冰化无关。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“长度”通常说“越长”，不说“越高”，“长度越高”不成立。"}], "explanations": {"温度": "“温度越高”说明冷热的程度，温度越高冰化得越快，符合语境。", "亮度": "语义：亮度指明暗的程度，与冰化的快慢无关。", "音量": "语义：音量指声音的大小，与冰化无关。", "长度": "搭配：“长度”通常说“越长”，不说“越高”，“长度越高”不成立。"}, "sentence_index": 6, "correct_answer": "温度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的温度很长。", "explanation": "这里应该用〈长度〉。温度只说冷热，绳子的长短要用长度，不能说“很长”。"}, {"text": "这袋米的温度很重。", "explanation": "这里应该用〈重量〉。温度只说冷热，东西的轻重要用重量，不能说“很重”。"}, {"text": "这把椅子的温度很矮。", "explanation": "这里应该用〈高度〉。温度只说冷热，椅子的高矮要用高度，不能说“很矮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上的温度是十个。", "corrected_sentence": "早上的温度是十度。", "error_description": "“温度”的数值应使用单位“度”，说“十个”是错误的量词，应改为“十度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "温度降了到零下五度。", "corrected_sentence": "温度降到了零下五度。", "error_description": "“降到”是复合动词，“了”应放在“降到”之后，应说“降到了”，不说“降了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
