INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们想一些大问题，比如世界是什么，人为什么活着。", "primary_collocate": null, "pronunciation": "zhé xué", "ipa": "ʈʂɤ˧˥ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "哲学思考的是人为什么活着这样的问题。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后开始学哲学。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学常常问一些很大的问题。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢和朋友聊哲学，一聊就是几个小时。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界是什么？这是哲学要想的问题。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天买了一本讲哲学的书。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学不是数学，没有一个简单的答案。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学哲学的人喜欢问“为什么”。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明才十岁，就对哲学有兴趣了。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用故事给我们讲哲学。", "target_word": "哲学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哲学家", "label": "复合"}, {"form": "哲学系", "label": "复合"}, {"form": "哲學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "思考世界是什么、人为什么活着等大问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数学", "is_correct": false, "explanation": "语义：“数学”研究数量与图形，不是思考人为什么活着的学问。"}, {"text": "哲学", "is_correct": true, "explanation": "“哲学”思考的是世界与人生的大问题，与句中“人为什么活着”的问题相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，不是思考大问题的学问，句意不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：“足球”是体育运动，不是思考大问题的学问，句意不通。"}], "explanations": {"数学": "语义：“数学”研究数量与图形，不是思考人为什么活着的学问。", "哲学": "“哲学”思考的是世界与人生的大问题，与句中“人为什么活着”的问题相合。", "天气": "语义：“天气”是气象状况，不是思考大问题的学问，句意不通。", "足球": "语义：“足球”是体育运动，不是思考大问题的学问，句意不通。"}, "sentence_index": 0, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店的哲学很便宜。", "explanation": "这里应该用〈价格〉。“价格”指商品的售价，说便宜要用“价格”；“哲学”指思考根本问题的学问，不能用来说售价的高低。"}, {"text": "他的哲学一米八，比我高很多。", "explanation": "这里应该用〈身高〉。“身高”指人的高矮，说一米八要用“身高”；“哲学”指思考根本问题的学问，不能用来说身高。"}, {"text": "他的哲学很大，一个人能扛两百斤。", "explanation": "这里应该用〈力气〉。“力气”指身体的力量，说力大要用“力气”；“哲学”指学问，不能用来说体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”不是学问，不能与“数学”相比较，也不存在“没有简单答案”的问题。"}, {"text": "哲学", "is_correct": true, "explanation": "“哲学不是数学”指哲学与数学不同，它的问题没有简单答案，与后句相呼应。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不是学科，与“不是数学”的类比不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“不是数学”是把学科相比，“体重”不是学科，二者不能类比。"}], "explanations": {"西瓜": "语义：“西瓜”不是学问，不能与“数学”相比较，也不存在“没有简单答案”的问题。", "哲学": "“哲学不是数学”指哲学与数学不同，它的问题没有简单答案，与后句相呼应。", "地铁": "语义：“地铁”是交通工具，不是学科，与“不是数学”的类比不成立。", "体重": "搭配：“不是数学”是把学科相比，“体重”不是学科，二者不能类比。"}, "sentence_index": 6, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的哲学很低，一进门就觉得冷。", "explanation": "这里应该用〈温度〉。“温度”指冷热的程度，说低要用“温度”；“哲学”指学问，不能用来说冷热。"}, {"text": "这条河的哲学有三米，船可以过去。", "explanation": "这里应该用〈深度〉。“深度”指从上到下的距离，说水有三米要用“深度”；“哲学”指学问，不能用来说水深。"}, {"text": "他的哲学很亮，唱歌很好听。", "explanation": "这里应该用〈嗓子〉。“嗓子”指发声的器官和嗓音，说嗓音亮要用“嗓子”；“哲学”指学问，不能用来说嗓音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥送给我一把讲哲学的书。", "corrected_sentence": "哥哥送给我一本讲哲学的书。", "error_description": "量词错误：书要用“本”，不能用“把”（“把”用于有柄的器具）。应改为“一本讲哲学的书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她聊哲学聊很开心，常常忘了时间。", "corrected_sentence": "她聊哲学聊得很开心，常常忘了时间。", "error_description": "补语错误：“聊”后接补语时要用“得”，“聊哲学聊很开心”应改为“聊哲学聊得很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
