INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22706, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22706, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示表面看起来如此，实际上并非如此，相当于“其实”。", "primary_collocate": null, "pronunciation": "shí zé", "ipa": "ʂʐ̩˧˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他看起来很高兴，实则心里很难过。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事看似简单，实则很难做。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己不累，实则已经很累了。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店看着很小，实则里面很大。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他表面很冷，实则很关心别人。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家以为他会来，实则他早就走了。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法听起来不错，实则没有用。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己没钱，实则买了很多东西。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题看上去容易，实则有一个小问题。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说没事，实则一晚上没睡。", "target_word": "实则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "表示与表面不同的真实情况，相当于其实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反正", "is_correct": false, "explanation": "语义：“反正”表示无论如何、总之，不能用来揭示与表面相反的真相，与“看起来很高兴”的对照不符。"}, {"text": "实则", "is_correct": true, "explanation": "正确：“实则”引出与表面相反的真实情况，与“看起来很高兴”形成对照。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带做某事，与“看起来很高兴”和“心里很难过”的对照无关，句意不通。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”指紧接着发生的动作，不能与“心里很难过”这种持续的状态搭配。"}], "explanations": {"反正": "语义：“反正”表示无论如何、总之，不能用来揭示与表面相反的真相，与“看起来很高兴”的对照不符。", "实则": "正确：“实则”引出与表面相反的真实情况，与“看起来很高兴”形成对照。", "顺便": "语义：“顺便”表示附带做某事，与“看起来很高兴”和“心里很难过”的对照无关，句意不通。", "马上": "搭配：“马上”指紧接着发生的动作，不能与“心里很难过”这种持续的状态搭配。"}, "sentence_index": 0, "correct_answer": "实则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法看起来很好，实则很好。", "explanation": "这里应该用〈确实〉。实则要求表面与真实情况相反，这句里表面和实际都是“很好”，没有对照，只能用〈确实〉来确认。"}, {"text": "天气预报说会下雨，实则会下雨。", "explanation": "这里应该用〈果然〉。实则要求表面与真实情况相反，这句的预报与结果一致，没有对照，应该用〈果然〉表示与预料相符。"}, {"text": "他说他很累，实则他很累。", "explanation": "这里应该用〈真的〉。实则要求表面与真实相反，这句的说法与实际一致，没有对照，应该用〈真的〉来确认。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带，与“没有用”的结论不搭，“这个办法顺便没有用”句意不通。"}, {"text": "实则", "is_correct": true, "explanation": "正确：“实则”表示表面与真实情况相反，这里“听起来不错”与“没有用”正好形成对照。"}, {"text": "分别", "is_correct": false, "explanation": "语义：“分别”指各自、分开，与“没有用”的整体结论不搭，句意不通。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”指紧接着发生的动作，不能与“没有用”这种结论搭配。"}], "explanations": {"顺便": "语义：“顺便”表示附带，与“没有用”的结论不搭，“这个办法顺便没有用”句意不通。", "实则": "正确：“实则”表示表面与真实情况相反，这里“听起来不错”与“没有用”正好形成对照。", "分别": "语义：“分别”指各自、分开，与“没有用”的整体结论不搭，句意不通。", "立刻": "搭配：“立刻”指紧接着发生的动作，不能与“没有用”这种结论搭配。"}, "sentence_index": 6, "correct_answer": "实则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他既聪明，实则又勤奋。", "explanation": "这里应该用〈又〉或〈而且〉。实则表示表面与真相相对，这句只是并列两个优点，没有对照，因此不能用实则。"}, {"text": "我们吃完饭，实则去看了电影。", "explanation": "这里应该用〈然后〉。实则表示表面与真相相对，这句只是陈述先后顺序，没有对照，应该用〈然后〉连接两个动作。"}, {"text": "我们先写完作业，实则去打球。", "explanation": "这里应该用〈然后〉。实则表示表面与真相相对，这句只是说明先后两个动作，没有对照，应该用〈然后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他嘴上说没事，实则的已经很担心了。", "corrected_sentence": "他嘴上说没事，实则已经很担心了。", "error_description": "“实则”是副词，后面不能加“的”，应写作“实则已经很担心了”，“的”是多余的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说自己很好，实则的情况很糟。", "corrected_sentence": "他说自己很好，实则情况很糟。", "error_description": "“实则”是副词，后面不能加“的”来修饰名词，应写作“实则情况很糟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
