INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22708, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是马上能收到回话的聊天方法。", "primary_collocate": null, "pronunciation": "jí shí tōng xùn", "ipa": "tɕi³⁵ ʂɻ̩³⁵ tʰʊŋ⁵⁵ ɕyn⁵¹", "syllable_count": 4, "sentences": [{"text": "我和姐姐常用即时通讯聊天。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即时通讯可以马上收到回话，很快。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在地铁上用即时通讯回复朋友。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用即时通讯告诉我你几点到。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷不懂即时通讯，只会打电话。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用即时通讯聊天，比写信快多了。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班用即时通讯开了一个小会。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出国留学的女儿每天用即时通讯和我说话。", "target_word": "即时通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片通过即时通讯发给了同学。", "target_word": "即时通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即时通讯里的朋友马上回了我的话。", "target_word": "即时通讯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "即时通讯软件", "label": "复合词"}], "register": "中性", "sense_fingerprint": "发出消息后马上能收到回话的聊天方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即时通讯", "is_correct": true, "explanation": "正确：作“用”的宾语，指一种聊天工具，与“聊天”搭配自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是聊天的工具，句意不通。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“聊天”不能以报纸为工具，“用报纸聊天”搭配不当。"}, {"text": "拖拉机", "is_correct": false, "explanation": "语义：拖拉机是农用车辆，不能用来聊天，句意不通。"}], "explanations": {"即时通讯": "正确：作“用”的宾语，指一种聊天工具，与“聊天”搭配自然。", "冰箱": "语义：冰箱不是聊天的工具，句意不通。", "报纸": "搭配：“聊天”不能以报纸为工具，“用报纸聊天”搭配不当。", "拖拉机": "语义：拖拉机是农用车辆，不能用来聊天，句意不通。"}, "sentence_index": 0, "correct_answer": "即时通讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请在这份即时通讯后面签个名。", "explanation": "这里应该用〈合同〉。即时通讯是通信方式，不是需要签名的文件，“签名”应用于合同、协议等文件。"}, {"text": "我把即时通讯放进冰箱里了。", "explanation": "这里应该用〈牛奶〉。即时通讯是一种聊天方法，不是可以放进冰箱的东西。"}, {"text": "这台即时通讯屏幕太小了，我看不清字。", "explanation": "这里应该用〈手机〉。即时通讯是软件或服务，不是有屏幕的设备，“屏幕太小”只能形容手机等设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即时通讯", "is_correct": true, "explanation": "正确：作“用”的宾语，指通讯工具，可以用来开会。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不能用来开会，与“开了一个小会”的语义不合。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“用课本开会”搭配不当，课本不是开会的工具。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套与“开会”毫不相干，句子无法成立。"}], "explanations": {"即时通讯": "正确：作“用”的宾语，指通讯工具，可以用来开会。", "闹钟": "语义：闹钟不能用来开会，与“开了一个小会”的语义不合。", "课本": "搭配：“用课本开会”搭配不当，课本不是开会的工具。", "手套": "语义：手套与“开会”毫不相干，句子无法成立。"}, "sentence_index": 6, "correct_answer": "即时通讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个即时通讯天天迟到，很不守时。", "explanation": "这里应该用〈同学〉。即时通讯是通信方式，不是人，不能说它“迟到”，应指人。"}, {"text": "我把即时通讯寄给了老家的父母。", "explanation": "这里应该用〈包裹〉。即时通讯传送的是消息，不能被寄送；寄给老家父母的应是实物，如包裹。"}, {"text": "我买了一箱即时通讯送给妈妈。", "explanation": "这里应该用〈水果〉。即时通讯是软件或服务，不是可以装箱的商品，“一箱”只能用于水果等实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常用即时通讯的给姐姐发照片。", "corrected_sentence": "我常用即时通讯给姐姐发照片。", "error_description": "多余的“的”：“即时通讯”后面不能加“的”，“用即时通讯”应直接接动词短语，应说“用即时通讯给姐姐发照片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班用一只即时通讯布置了一个小作业。", "corrected_sentence": "我们班用一种即时通讯布置了一个小作业。", "error_description": "量词错误：“即时通讯”指通讯工具，应搭配“种”，“只”用于动物或成对的东西，应说“用一种即时通讯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
