INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22712, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "意思是事情的关键、原因或本质所在。", "primary_collocate": null, "pronunciation": "zài yú", "ipa": "tsaɪ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "学好汉语的关键在于多说。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的难处在于时间太短。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成功的原因在于每天练习。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快乐不在于钱多，而在于家人在一起。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题在于我们没有准备好。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法的好处在于简单。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "健康在于运动和睡眠。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个词的不同在于用法。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的特点在于东西便宜。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的意义在于大家一起玩。", "target_word": "在于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指出事情的关键、原因或本质是什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在于", "is_correct": true, "explanation": "在于：指事情的关键、原因或本质所在，即本词。"}, {"text": "带鱼", "is_correct": false, "explanation": "dài 与 zài 声母不同（d 与 z），意思是一种海鱼，不是在于。"}, {"text": "再遇", "is_correct": false, "explanation": "yù 与 yú 声调不同（第四声与第二声），意思是再次遇见。"}, {"text": "晒鱼", "is_correct": false, "explanation": "shài 与 zài 声母不同（sh 与 z），意思是把鱼晒干。"}], "explanations": {"在于": "在于：指事情的关键、原因或本质所在，即本词。", "带鱼": "dài 与 zài 声母不同（d 与 z），意思是一种海鱼，不是在于。", "再遇": "yù 与 yú 声调不同（第四声与第二声），意思是再次遇见。", "晒鱼": "shài 与 zài 声母不同（sh 与 z），意思是把鱼晒干。"}, "sentence_index": null, "correct_answer": "在于"}, "level_3": {"options": [{"text": "属于", "is_correct": false, "explanation": "配价：“属于”要求“A属于B”的所属结构，“关键”后不能直接接“多说”。"}, {"text": "在于", "is_correct": true, "explanation": "在于：指关键、原因所在，与“学好汉语的关键”搭配自然。"}, {"text": "等于", "is_correct": false, "explanation": "语义：“等于”表示数量或意义相等，“关键”和“多说”不是等同关系。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“关键”不是可以开始的动作，“开始”与句子的意思不符。"}], "explanations": {"属于": "配价：“属于”要求“A属于B”的所属结构，“关键”后不能直接接“多说”。", "在于": "在于：指关键、原因所在，与“学好汉语的关键”搭配自然。", "等于": "语义：“等于”表示数量或意义相等，“关键”和“多说”不是等同关系。", "开始": "语义：“关键”不是可以开始的动作，“开始”与句子的意思不符。"}, "sentence_index": 0, "correct_answer": "在于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书在于我。", "explanation": "这里应该用〈属于〉。“在于”表示关键或原因所在，表示归属要用“属于”。"}, {"text": "他在于老师。", "explanation": "这里应该用〈是〉。判断身份用“是”，“在于”只用来说明关键所在。"}, {"text": "我不在于钱。", "explanation": "这里应该用〈在乎〉。“在乎”表示放在心上，“在于”不表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”针对人或事的厌恶，“健康讨厌运动和睡眠”语义不通。"}, {"text": "在于", "is_correct": true, "explanation": "在于：指健康的关键或根源所在，与“健康”搭配自然。"}, {"text": "取代", "is_correct": false, "explanation": "语义：“取代”表示替换，健康不会去取代运动和睡眠。"}, {"text": "收费", "is_correct": false, "explanation": "搭配：“收费”针对服务，“健康”不是收费的对象。"}], "explanations": {"讨厌": "语义：“讨厌”针对人或事的厌恶，“健康讨厌运动和睡眠”语义不通。", "在于": "在于：指健康的关键或根源所在，与“健康”搭配自然。", "取代": "语义：“取代”表示替换，健康不会去取代运动和睡眠。", "收费": "搭配：“收费”针对服务，“健康”不是收费的对象。"}, "sentence_index": 6, "correct_answer": "在于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个想法在于朋友。", "explanation": "这里应该用〈来自〉。表示来源要用“来自”，“在于”不能表示来源。"}, {"text": "学校在于市中心。", "explanation": "这里应该用〈位于〉。表示地点要用“位于”，“在于”不能表示位置。"}, {"text": "这个数字在于一百。", "explanation": "这里应该用〈相当于〉。表示数量接近或相当要用“相当于”，“在于”不表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习的关键在于在坚持。", "corrected_sentence": "学习的关键在于坚持。", "error_description": "多加了一个“在”：“在于”后直接接说明关键的内容，不能再加“在”，应说“学习的关键在于坚持”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次失败的根本问题在于了我们准备不足。", "corrected_sentence": "这次失败的根本问题在于我们准备不足。", "error_description": "体标错误：“了”不能放在“在于”之后，“在于”后接的是说明关键的内容，句中不加“了”。正确说法是“根本问题在于我们准备不足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22714, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "反义：“分裂”指把原本合在一起的东西分开，与“统一”相对。"}, {"text": "购买", "is_correct": false, "explanation": "与“统一”没有反义关系，“购买”指花钱买东西。"}, {"text": "修理", "is_correct": false, "explanation": "与“统一”没有反义关系，“修理”指把坏的东西修好。"}, {"text": "欢迎", "is_correct": false, "explanation": "与“统一”没有反义关系，“欢迎”指热情接待。"}], "correct_answer": "分裂", "explanations": {"分裂": "反义：“分裂”指把原本合在一起的东西分开，与“统一”相对。", "购买": "与“统一”没有反义关系，“购买”指花钱买东西。", "修理": "与“统一”没有反义关系，“修理”指把坏的东西修好。", "欢迎": "与“统一”没有反义关系，“欢迎”指热情接待。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
