INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22714, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的东西合起来，让它们变成一样。", "primary_collocate": null, "pronunciation": "tǒng yī", "ipa": "tʰʊŋ˨˩˦ i˥", "syllable_count": 2, "sentences": [{"text": "学校统一了大家的上课时间。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先统一一下意见。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想统一大家的做法。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们统一了两个班的考试时间。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的想法很难统一。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司的标准终于统一了。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些表格的格式统一一下。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想统一各店的价格。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的看法终于统一了。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板统一了几个店的名字。", "target_word": "统一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "统一了", "label": "体标"}, {"form": "统一过", "label": "体标"}, {"form": "統一", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把不同的东西合成一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统一", "is_correct": true, "explanation": "统一：表示让大家的上课时间变得一致，与句意相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能接“上课时间”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能接“上课时间”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与“上课时间”毫无关系。"}], "explanations": {"统一": "统一：表示让大家的上课时间变得一致，与句意相符。", "煮": "搭配：“煮”的对象是食物，不能接“上课时间”。", "打扫": "搭配：“打扫”的对象是场所或物品，不能接“上课时间”。", "唱": "语义：“唱”指发出歌声，与“上课时间”毫无关系。"}, "sentence_index": 0, "correct_answer": "统一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他统一了三个数字的总和。", "explanation": "这里应该用〈计算〉。统一是使不同的东西变得一样，数字的总和要用计算得出。"}, {"text": "老师统一了我的问题。", "explanation": "这里应该用〈解答〉。统一指使多个对象变得一致，问题要用解答来处理。"}, {"text": "他统一了那台坏电脑。", "explanation": "这里应该用〈修理〉。统一用于使多个事物一致，把坏电脑修好要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统一", "is_correct": true, "explanation": "统一：表示使这些表格的格式变得一致，与“统一一下”的用法相符。"}, {"text": "讲述", "is_correct": false, "explanation": "语义：“讲述”指用语言叙述事情，与“格式”无关。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”的对象是具体的东西，不能接抽象的“格式”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与“格式”完全不搭。"}], "explanations": {"统一": "统一：表示使这些表格的格式变得一致，与“统一一下”的用法相符。", "讲述": "语义：“讲述”指用语言叙述事情，与“格式”无关。", "拆开": "搭配：“拆开”的对象是具体的东西，不能接抽象的“格式”。", "吃": "语义：“吃”指把食物咽下，与“格式”完全不搭。"}, "sentence_index": 6, "correct_answer": "统一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我统一了一座山。", "explanation": "这里应该用〈攀登〉。统一需要两个或两个以上的对象才能变得一致，攀登一座山是单独的动作，不能用“统一”。"}, {"text": "妈妈统一了一碗饭。", "explanation": "这里应该用〈吃〉。统一需要两个或两个以上的对象才能变得一致，吃一碗饭是单独的动作，不能用“统一”。"}, {"text": "老师统一了一支笔。", "explanation": "这里应该用〈削〉。统一需要两个或两个以上的对象，削一支铅笔不涉及多个对象的一致，不能用“统一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个班的考试时间还没统一了。", "corrected_sentence": "两个班的考试时间还没统一。", "error_description": "错误形式：“没统一了”；正确形式：“没统一”。用“没”否定“统一”时，后面不能再加表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这些书的版式统一着。", "corrected_sentence": "请把这些书的版式统一一下。", "error_description": "错误：“统一着”；正确：“统一一下”。“着”表示状态持续，不能用在要求对方完成动作的“请把……”句中，应用“一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
