INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "对事物变化容易有感觉。", "primary_collocate": null, "pronunciation": "mǐn gǎn xìng", "ipa": "min˨˩˦ kan˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "做设计的人要对颜色有很高的敏感性。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好记者对新闻的敏感性很强。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对别人情绪变化的敏感性很高。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常旅行能提高人对新环境的敏感性。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资的人需要对价格变化有敏感性。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家对声音高低的敏感性让人佩服。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生心情的敏感性很重要。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对时间的敏感性很差，常常迟到。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要培养对市场变化的敏感性。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对语言的敏感性在小时候最强。", "target_word": "敏感性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人对事物变化容易察觉、有感觉的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指明暗程度，不是对颜色的察觉能力，句意不符。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”指平面的大小，不能说对颜色有很高的面积。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：“硬度”指物体坚硬的程度，与设计人对颜色的察觉能力无关。"}, {"text": "敏感性", "is_correct": true, "explanation": "“敏感性”指对颜色变化容易察觉的能力，符合设计人的语境。"}], "explanations": {"亮度": "语义：“亮度”指明暗程度，不是对颜色的察觉能力，句意不符。", "面积": "搭配：“面积”指平面的大小，不能说对颜色有很高的面积。", "硬度": "语义：“硬度”指物体坚硬的程度，与设计人对颜色的察觉能力无关。", "敏感性": "“敏感性”指对颜色变化容易察觉的能力，符合设计人的语境。"}, "sentence_index": 0, "correct_answer": "敏感性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的敏感性很快。", "explanation": "这里应该用〈速度〉。敏感性指察觉变化的能力，不用于说车速。"}, {"text": "这家店的顾客敏感性很多。", "explanation": "这里应该用〈数量〉。敏感性不能用来计算多少。"}, {"text": "这条路的敏感性很大，一直延伸到山里。", "explanation": "这里应该用〈长度〉。敏感性指对变化的感觉，不用于描述道路的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”与学生的心情无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，不能用来说对心情的察觉。"}, {"text": "容积", "is_correct": false, "explanation": "搭配：“容积”指容器能容纳的空间，不能说学生心情的容积。"}, {"text": "敏感性", "is_correct": true, "explanation": "“敏感性”指对他人情绪变化容易察觉的能力，与“老师对学生心情的”搭配。"}], "explanations": {"价格": "语义：“价格”与学生的心情无关，句意不通。", "体重": "语义：“体重”指人或物的重量，不能用来说对心情的察觉。", "容积": "搭配：“容积”指容器能容纳的空间，不能说学生心情的容积。", "敏感性": "“敏感性”指对他人情绪变化容易察觉的能力，与“老师对学生心情的”搭配。"}, "sentence_index": 6, "correct_answer": "敏感性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的敏感性很大。", "explanation": "这里应该用〈尺寸〉。敏感性不描述物体的大小。"}, {"text": "今天的敏感性很高。", "explanation": "这里应该用〈温度〉。敏感性不用于说气温。"}, {"text": "这箱苹果的敏感性很重。", "explanation": "这里应该用〈重量〉。敏感性不描述物体的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位司机对路况的变化有很高地敏感性。", "corrected_sentence": "这位司机对路况的变化有很高的敏感性。", "error_description": "“敏感性”前的修饰语应用“的”，不用“地”（“地”用于修饰动词、形容词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子对声音有一只很强的敏感性。", "corrected_sentence": "这个孩子对声音有一种很强的敏感性。", "error_description": "“敏感性”是抽象名词，量词应用“种”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
