INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现代性指现在这个时代的样子。", "primary_collocate": null, "pronunciation": "xiàn dài xìng", "ipa": "ɕjɛn˥˩ taɪ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这座城市有很强的现代性。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部手机的外形充满了现代性。", "target_word": "现代性", "complexity_tier": "T3", "furigana": "zhè bù shǒujī de wàixíng chōngmǎn le xiàndàixìng", "sentence_source": "generated"}, {"text": "他喜欢这栋楼的现代性。", "target_word": "现代性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个设计很简单，也很有现代性。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套家具的颜色和线条很有现代性。", "target_word": "现代性", "complexity_tier": "T3", "furigana": "zhè tào jiājù de yánsè hé xiàntiáo hěn yǒu xiàndàixìng", "sentence_source": "generated"}, {"text": "老师给我们讲了现代性的特点。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店的现代性让老人觉得不习惯。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代性就是现在这个时代的样子。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新机场的现代性给游客留下了很深的印象。", "target_word": "现代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家想在画里表现现代性。", "target_word": "现代性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "现在这个时代的样子和特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代性", "is_correct": true, "explanation": "这里指城市的整体风格和特征，与“很强的”搭配，句意通顺。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“很强的”修饰抽象特征，不能修饰雨伞这样的具体物品。"}, {"text": "食盐", "is_correct": false, "explanation": "语义：食盐是调味品，与城市的风格和特征无关。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的练习，不能说城市“有很强的作业”。"}], "explanations": {"现代性": "这里指城市的整体风格和特征，与“很强的”搭配，句意通顺。", "雨伞": "搭配：“很强的”修饰抽象特征，不能修饰雨伞这样的具体物品。", "食盐": "语义：食盐是调味品，与城市的风格和特征无关。", "作业": "语义：作业是学生的练习，不能说城市“有很强的作业”。"}, "sentence_index": 0, "correct_answer": "现代性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一本现代性，每天都读它。", "explanation": "这里应该用〈书〉。现代性是抽象的时代特点，不能买来阅读；能“买一本”“每天读”的应是书。"}, {"text": "这个房间的现代性很好闻。", "explanation": "“好闻”只用于描述气味，现代性指风格和特征，不是气味，这里用法不当。"}, {"text": "我们在花园里种了很多现代性。", "explanation": "“种”的对象应是植物等可以生长的东西，现代性是抽象概念，不能种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代性", "is_correct": true, "explanation": "这里指商店的风格和特征，与“让老人觉得不习惯”的语境相符。"}, {"text": "恐龙", "is_correct": false, "explanation": "语义：恐龙是远古动物，不能作为商店的特征让老人觉得不习惯。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能用来描述商店的特征让老人觉得不习惯。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学体裁，与商店的特征无关。"}], "explanations": {"现代性": "这里指商店的风格和特征，与“让老人觉得不习惯”的语境相符。", "恐龙": "语义：恐龙是远古动物，不能作为商店的特征让老人觉得不习惯。", "数学": "语义：数学是学科，不能用来描述商店的特征让老人觉得不习惯。", "诗歌": "语义：诗歌是文学体裁，与商店的特征无关。"}, "sentence_index": 6, "correct_answer": "现代性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座博物馆展示的是三千年前的现代性。", "explanation": "这里应该用〈古代的样子〉。现代性指现在这个时代的样子，不能用来指三千年前的事物；展示三千年前的内容，应说古代的样子。"}, {"text": "这座城市的现代性每天都要吃三顿饭。", "explanation": "这里应该用〈居民〉。现代性是抽象的时代样子，不能吃饭；吃饭的应是人。"}, {"text": "他每天都用现代性刷牙。", "explanation": "这里应该用〈牙膏〉。现代性是抽象的时代样子，不能用来刷牙；刷牙要用具体的牙膏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋大楼很现代性。", "corrected_sentence": "这栋大楼很有现代性。", "error_description": "“现代性”是名词，不能直接受“很”修饰，需要加动词“有”，应说“很有现代性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套家具有一只很强的现代性。", "corrected_sentence": "这套家具有一种很强的现代性。", "error_description": "“现代性”是抽象名词，量词应用“种”。错误形式用了“只”，“只”多用于动物或成对物品中的个体，正确形式是“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
