INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用线或毛线做东西。", "primary_collocate": null, "pronunciation": "biān zhī", "ipa": "pjɛn˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "奶奶正在用毛线编织一条围巾。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给孙子编织了一顶小帽子。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈坐在窗边，编织着一件毛衣。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学习编织毛衣，送给爸爸。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，外婆每天都编织毛衣。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她编织过很多漂亮的围巾。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用红毛线编织了一个小包。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条毯子是妈妈用白毛线编织的。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习用彩线编织手链。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边看电视，一边用毛线编织。", "target_word": "编织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编织了", "label": "体标"}, {"form": "编织着", "label": "体标"}, {"form": "编织过", "label": "体标"}, {"form": "编织袋", "label": "复合"}], "register": "中性", "sense_fingerprint": "用毛线、草等交叉着织成东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "编织", "is_correct": true, "explanation": "“编织”（biān zhī）是本词，指用线、草等交叉着做成东西。"}, {"text": "便知", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是就能知道。"}, {"text": "变质", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）、zhì（第四声）与 zhī（第一声）声调都不同，意思是食物等起化学变化而变坏。"}, {"text": "贬值", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）、zhí（第二声）与 zhī（第一声）声调都不同，意思是价值降低。"}], "explanations": {"编织": "“编织”（biān zhī）是本词，指用线、草等交叉着做成东西。", "便知": "biàn（第四声）与 biān（第一声）声调不同，意思是就能知道。", "变质": "biàn（第四声）与 biān（第一声）、zhì（第四声）与 zhī（第一声）声调都不同，意思是食物等起化学变化而变坏。", "贬值": "biǎn（第三声）与 biān（第一声）、zhí（第二声）与 zhī（第一声）声调都不同，意思是价值降低。"}, "sentence_index": null, "correct_answer": "编织"}, "level_3": {"options": [{"text": "编织", "is_correct": true, "explanation": "“编织”表示用线交叉做成东西，“用毛线编织一条围巾”符合语境。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”表示切断，用毛线“剪”出一条围巾说不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”表示清洁，用毛线“洗”围巾与制作的意思不合。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”接植物，不说“种一条围巾”。"}], "explanations": {"编织": "“编织”表示用线交叉做成东西，“用毛线编织一条围巾”符合语境。", "剪": "语义：“剪”表示切断，用毛线“剪”出一条围巾说不通。", "洗": "语义：“洗”表示清洁，用毛线“洗”围巾与制作的意思不合。", "种": "搭配：“种”接植物，不说“种一条围巾”。"}, "sentence_index": 0, "correct_answer": "编织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在编织一个新程序。", "explanation": "这里应该用〈编写〉。编织指用线、草等交叉做成物品，程序要用编写。"}, {"text": "他编织了一份春游的预算。", "explanation": "这里应该用〈编制〉。编织指用线等交叉做成物品，预算要用编制。"}, {"text": "这家出版社编织了很多书。", "explanation": "这里应该用〈编辑〉。编织指用线做成物品，书籍的编排和整理要用编辑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编织", "is_correct": true, "explanation": "“编织”表示用线做成东西，“用红毛线编织了一个小包”符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与用线做包的意思毫不相关，“吃了一个小包”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不说“唱一个小包”。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文件印出来，与用红毛线做包的意思不合。"}], "explanations": {"编织": "“编织”表示用线做成东西，“用红毛线编织了一个小包”符合语境。", "吃": "语义：“吃”与用线做包的意思毫不相关，“吃了一个小包”说不通。", "唱": "搭配：“唱”的宾语应是歌曲，不说“唱一个小包”。", "打印": "语义：“打印”指把文件印出来，与用红毛线做包的意思不合。"}, "sentence_index": 6, "correct_answer": "编织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈编织了一个蛋糕。", "explanation": "这里应该用〈制作〉。编织只用于线、草等材料，蛋糕要用制作。"}, {"text": "工厂里编织了一台电脑。", "explanation": "这里应该用〈组装〉。编织只用于线材，电脑的零件要用组装。"}, {"text": "爸爸编织了这间卧室。", "explanation": "这里应该用〈装修〉。编织只用于线材，房间的布置和改造要用装修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她正在编织了一顶毛线帽子。", "corrected_sentence": "她正在编织一顶毛线帽子。", "error_description": "时态冲突：“正在”表示动作正在进行，不能与表示完成的“了”同用，应说“正在编织”，不能说“正在编织了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件毛衣她编织很漂亮。", "corrected_sentence": "这件毛衣她编织得很漂亮。", "error_description": "漏掉了“得”：引出程度补语要用“动词+得+补语”，应说“编织得很漂亮”，不能说“编织很漂亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
