INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间尺度就是用来量时间长短的尺子，比如一天、一年。", "primary_collocate": null, "pronunciation": "shí jiān chǐ dù", "ipa": "ʂɻ̩˧˥ tɕjɛn˥ ʈʂʰɻ̩˨˩˦ tu˥˩", "syllable_count": 4, "sentences": [{"text": "一天是一个常用的时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年是比一天更大的时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画出了时间尺度，从一天到一年。", "target_word": "时间尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划的时候，要选对时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友还不懂什么是时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秒和分钟是比较小的时间尺度。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事的时间尺度是一个星期。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用一个月作为时间尺度记录体重。", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作用小时，旅行用天，这是不同的时间尺度。", "target_word": "时间尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我，这张表的时间尺度是什么？", "target_word": "时间尺度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "時間尺度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来量时间长短的尺子，如一天、一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a14a5b5-fb1c-4d38-a80a-0291bb9dc678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间尺度", "is_correct": true, "explanation": "这里指用来量时间长短的单位，“一天是一个常用的”说的正是时间尺度。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固体的水，不能作为衡量时间长短的单位。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋是穿在脚上的鞋，与衡量时间无关。"}, {"text": "画笔", "is_correct": false, "explanation": "搭配：“一天”不能与“常用的画笔”搭配，句子的主语和谓语不相配。"}], "explanations": {"时间尺度": "这里指用来量时间长短的单位，“一天是一个常用的”说的正是时间尺度。", "冰块": "语义：冰块是固体的水，不能作为衡量时间长短的单位。", "拖鞋": "语义：拖鞋是穿在脚上的鞋，与衡量时间无关。", "画笔": "搭配：“一天”不能与“常用的画笔”搭配，句子的主语和谓语不相配。"}, "sentence_index": 0, "correct_answer": "时间尺度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做衣服的时候，要选对时间尺度。", "explanation": "这里应该用〈尺寸〉。做衣服要选尺寸，尺寸指物体的大小；时间尺度衡量的是时间长短，不能用来做衣服。"}, {"text": "我们买了一台时间尺度，放在厨房。", "explanation": "量词“台”用于机器等具体物品，时间尺度是抽象概念，这里的量词用法不当。"}, {"text": "我爸爸每天都喝时间尺度。", "explanation": "这里把时间尺度当成〈饮料〉来喝。时间尺度是量时间长短的尺子，不能喝；能喝的应是饮料或水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间尺度", "is_correct": true, "explanation": "这里指故事的时间范围，“是一个星期”说的正是时间跨度。"}, {"text": "主角", "is_correct": false, "explanation": "语义：主角是故事中的人物，不能用“是一个星期”来表示。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是食物或气味的特性，与故事的时间无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”指人或动物的温度，不能作为故事的属性。"}], "explanations": {"时间尺度": "这里指故事的时间范围，“是一个星期”说的正是时间跨度。", "主角": "语义：主角是故事中的人物，不能用“是一个星期”来表示。", "味道": "语义：味道是食物或气味的特性，与故事的时间无关。", "体温": "搭配：“体温”指人或动物的温度，不能作为故事的属性。"}, "sentence_index": 6, "correct_answer": "时间尺度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请告诉我，这块地的时间尺度是多少？", "explanation": "这里应该用〈面积〉。问地的大小用面积，面积衡量空间大小；时间尺度衡量时间，不能用来问地块的大小。"}, {"text": "我们用时间尺度给这只猫起名字。", "explanation": "这里把时间尺度当成给猫命名用的〈名称〉。时间尺度是量时间长短的尺子，不能用来给猫定名称。"}, {"text": "请告诉我，他的时间尺度是多少？", "explanation": "这里应该用〈年龄〉。问人的岁数用年龄，时间尺度不能用来表示一个人的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想用一个很短时间尺度来记录。", "corrected_sentence": "我们想用一个很短的时间尺度来记录。", "error_description": "修饰语“很短”与名词“时间尺度”之间需要“的”。错误形式漏掉了“的”，正确形式是“很短的时间尺度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们选了一只常用的时间尺度。", "corrected_sentence": "我们选了一种常用的时间尺度。", "error_description": "“时间尺度”是抽象名词，量词应用“种”。错误形式用了“只”，“只”多用于动物等个体，正确形式是“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ffb4509-4d1f-4cf1-9d08-57db6ee59f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
