INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方或多方一起商量，把一件事谈妥。", "primary_collocate": null, "pronunciation": "xié shāng", "ipa": "ɕjɛ˧˥ ʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "两家公司正在协商价格。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我们可以坐下来慢慢协商。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东和我协商了房租的问题。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方经过协商，终于签了合同。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题要先协商，不要吵架。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们协商好了活动的时间。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你协商一下搬家的日期。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们协商了很久，还是没有结果。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格可以协商，你想要多少钱？", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们协商着怎样打扫院子。", "target_word": "协商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协商了", "label": "完成体"}, {"form": "协商着", "label": "持续体"}, {"form": "协商过", "label": "经历体"}, {"form": "協商", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双方或多方一起商量，把事情谈好，如协商价格、协商解决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "协商", "is_correct": true, "explanation": "正确。“两家公司正在协商价格”中，协商表示双方商量，与“价格”搭配自然。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：制造常与产品或问题搭配，不能说制造价格。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏析美好事物，用于价格与语境不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理用于器物或设备，不能说修理价格。"}], "explanations": {"协商": "正确。“两家公司正在协商价格”中，协商表示双方商量，与“价格”搭配自然。", "制造": "搭配：制造常与产品或问题搭配，不能说制造价格。", "欣赏": "语义：欣赏指赏析美好事物，用于价格与语境不符。", "修理": "搭配：修理用于器物或设备，不能说修理价格。"}, "sentence_index": 0, "correct_answer": "协商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人协商了这件事。", "explanation": "这里应该用〈考虑〉或〈决定〉。协商需要双方或多方一起商量，只有一个人时不能用协商。"}, {"text": "他们协商了那件新衣服。", "explanation": "这里应该用〈挑选〉。协商的对象是价格、条款等事项，衣服这样的具体物品不能协商。"}, {"text": "这块石头协商了价格。", "explanation": "这里应该用〈标价〉。协商的主体必须是人，石头不能与人协商价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协商", "is_correct": true, "explanation": "正确。“我想和你协商一下搬家的日期”中，协商表示双方商量，与“和你”衔接。"}, {"text": "寄", "is_correct": false, "explanation": "语义：寄指邮寄或托付，不能用于商量日期。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢表示谢意，与搬家的日期没有关系。"}, {"text": "赶", "is_correct": false, "explanation": "搭配：赶多指追赶或赶上，不能说赶日期。"}], "explanations": {"协商": "正确。“我想和你协商一下搬家的日期”中，协商表示双方商量，与“和你”衔接。", "寄": "语义：寄指邮寄或托付，不能用于商量日期。", "感谢": "语义：感谢表示谢意，与搬家的日期没有关系。", "赶": "搭配：赶多指追赶或赶上，不能说赶日期。"}, "sentence_index": 6, "correct_answer": "协商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们把这本书协商完了。", "explanation": "这里应该用〈读完〉。协商指双方商量事项，书是要读的，不能协商，应说读完。"}, {"text": "他们把这顿饭协商过了。", "explanation": "这里应该用〈品尝〉。协商的对象是要商定的事项，饭要吃，不能协商，应说品尝过。"}, {"text": "大家协商了天气。", "explanation": "这里应该用〈谈论〉。天气无法商量决定，协商的对象应是双方要商定的事项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "双方正在协商了付款的时间。", "corrected_sentence": "双方协商了付款的时间。", "error_description": "错误：“正在协商了”，正确：“协商了”。“正在”表示动作进行中，与“了”表示完成相冲突，应去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人协商着了合作的细节。", "corrected_sentence": "两人协商了合作的细节。", "error_description": "错误：“协商着了”，正确：“协商了”。“着”表示持续，“了”表示完成，二者不能同时用在“协商”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
