INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22740, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用船把人或东西从河的一边送到另一边。", "primary_collocate": null, "pronunciation": "bǎi dù", "ipa": "pai˨˩˦ tu˥˩", "syllable_count": 2, "sentences": [{"text": "江上没有桥，只有船夫摆渡。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在河边摆渡，送人去对岸。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老船夫摆渡了三十年。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把我们摆渡到河对面，好吗？", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船一次能摆渡五个人。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，没有人再摆渡了。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的村子靠摆渡来往。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在黄河边摆渡过。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着船夫摆渡，觉得很有意思。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船夫把一车菜摆渡到河对岸。", "target_word": "摆渡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆渡了", "label": "体标"}, {"form": "摆渡过", "label": "体标"}, {"form": "摆渡船", "label": "复合"}, {"form": "摆渡人", "label": "复合"}, {"form": "擺渡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划船把人或东西从河这边送到那边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a94ae4-79af-4eab-97ed-f48899b3b919') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摆渡", "is_correct": true, "explanation": "摆渡（bǎi dù）：用船把人或东西从河的一边送到另一边，是本词的正确答案。"}, {"text": "拜读", "is_correct": false, "explanation": "拜读（bài dú）两个音节的声调都与摆渡（bǎi dù）不同，意思是恭敬地阅读。"}, {"text": "摆脱", "is_correct": false, "explanation": "摆脱（bǎi tuō）与摆渡的第二个音节声母不同（t 与 d），声调也不同，意思是挣脱、摆开。"}, {"text": "拜托", "is_correct": false, "explanation": "拜托（bài tuō）第一个音节声调不同（第四声），第二个音节声母不同（t 与 d），意思是请别人帮忙。"}, {"text": "摆布", "is_correct": false, "explanation": "摆布（bǎi bù）第二个音节声母不同（b 与 d），意思是支配、控制。"}], "explanations": {"摆渡": "摆渡（bǎi dù）：用船把人或东西从河的一边送到另一边，是本词的正确答案。", "拜读": "拜读（bài dú）两个音节的声调都与摆渡（bǎi dù）不同，意思是恭敬地阅读。", "摆脱": "摆脱（bǎi tuō）与摆渡的第二个音节声母不同（t 与 d），声调也不同，意思是挣脱、摆开。", "拜托": "拜托（bài tuō）第一个音节声调不同（第四声），第二个音节声母不同（t 与 d），意思是请别人帮忙。", "摆布": "摆布（bǎi bù）第二个音节声母不同（b 与 d），意思是支配、控制。"}, "sentence_index": null, "correct_answer": "摆渡"}, "level_3": {"options": [{"text": "摆渡", "is_correct": true, "explanation": "摆渡：用船把人或东西送过河，此处指船夫用船送人过江。"}, {"text": "修补", "is_correct": false, "explanation": "语义：修补指修理破损的东西，与江上没有桥时的运送无关。"}, {"text": "飞翔", "is_correct": false, "explanation": "语义：飞翔指鸟类或飞行器在空中飞行，船夫不能飞翔，与语境相悖。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”只接乐器或乐曲，不能用来指船夫送人过江。"}], "explanations": {"摆渡": "摆渡：用船把人或东西送过河，此处指船夫用船送人过江。", "修补": "语义：修补指修理破损的东西，与江上没有桥时的运送无关。", "飞翔": "语义：飞翔指鸟类或飞行器在空中飞行，船夫不能飞翔，与语境相悖。", "演奏": "搭配：“演奏”只接乐器或乐曲，不能用来指船夫送人过江。"}, "sentence_index": 0, "correct_answer": "摆渡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察摆渡那个犯人去法院。", "explanation": "这里应该用〈护送〉。摆渡必须借船跨越水面，陆上押送犯人不能说摆渡。"}, {"text": "他把花瓶摆渡到窗台上。", "explanation": "这里应该用〈摆放〉。摆渡指借船运送人或物过水，把东西放到某处只能说摆放。"}, {"text": "警方把罪犯摆渡回国。", "explanation": "这里应该用〈引渡〉。摆渡指借船把人或物运过河，把罪犯移交回国要说引渡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摆渡", "is_correct": true, "explanation": "摆渡：借船把人或东西送过河，此处指村子靠船往来两岸。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与村子往来两岸的意思无关。"}, {"text": "冶炼", "is_correct": false, "explanation": "语义：冶炼指从矿石中提取金属，与往来两岸的意思无关。"}, {"text": "辟谣", "is_correct": false, "explanation": "搭配：“辟谣”只针对谣言，不能用来指两岸的往来。"}], "explanations": {"摆渡": "摆渡：借船把人或东西送过河，此处指村子靠船往来两岸。", "烹饪": "语义：烹饪指做饭，与村子往来两岸的意思无关。", "冶炼": "语义：冶炼指从矿石中提取金属，与往来两岸的意思无关。", "辟谣": "搭配：“辟谣”只针对谣言，不能用来指两岸的往来。"}, "sentence_index": 6, "correct_answer": "摆渡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师每天摆渡学生的问题。", "explanation": "这里应该用〈解答〉。摆渡只指借船把人或可搬运的东西运过河，不能用来处理抽象的问题，这里应说解答。"}, {"text": "我们在马路上摆渡了一整天。", "explanation": "这里应该用〈步行〉。摆渡必须借船跨越水面，马路上没有河流，不能用摆渡，陆上行走应说步行。"}, {"text": "工人把一座大楼摆渡到了对岸。", "explanation": "这里应该用〈移建〉。摆渡只指借船运送人或可搬运的东西，固定的大楼不能被摆渡，应说移建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渡口的老人用一条木船村民摆渡过了江。", "corrected_sentence": "渡口的老人用一条木船把村民摆渡过了江。", "error_description": "“村民”是被摆渡的对象，原句把它直接接在“木船”之后，两个名词连成一串，结构不清。应说“用一条木船把村民摆渡过了江”（把字句），或“用一条木船摆渡村民过了江”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老船夫一车鱼摆渡到对岸去了。", "corrected_sentence": "老船夫把一车鱼摆渡到对岸去了。", "error_description": "“一车鱼”是被摆渡的对象，原句把它直接接在“老船夫”之后，两个名词连成一串，结构不清。应说“老船夫把一车鱼摆渡到对岸去了”（把字句），或“老船夫摆渡一车鱼到对岸去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22742, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慌张", "is_correct": true, "explanation": "慌张：慌乱、不镇定，与“从容”的态度相反。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指明白、不模糊，与“从容”的态度无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：指质地柔和，与“从容”无关。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线或眼神明亮，与“从容”的态度无关。"}], "correct_answer": "慌张", "explanations": {"慌张": "慌张：慌乱、不镇定，与“从容”的态度相反。", "清楚": "清楚：指明白、不模糊，与“从容”的态度无关。", "柔软": "柔软：指质地柔和，与“从容”无关。", "明亮": "明亮：指光线或眼神明亮，与“从容”的态度无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22742, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慌张", "is_correct": true, "explanation": "慌张：慌乱、不镇定，与“从容”的态度相反。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：指表面不光滑，与“从容”无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝：指反应慢，不是“从容”的反义词。"}, {"text": "浑浊", "is_correct": false, "explanation": "浑浊：指水或空气不清澈，与“从容”无关。"}], "correct_answer": "慌张", "explanations": {"慌张": "慌张：慌乱、不镇定，与“从容”的态度相反。", "粗糙": "粗糙：指表面不光滑，与“从容”无关。", "迟钝": "迟钝：指反应慢，不是“从容”的反义词。", "浑浊": "浑浊：指水或空气不清澈，与“从容”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22742, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不着急，很冷静。", "primary_collocate": null, "pronunciation": "cóng róng", "ipa": "tsʰʊŋ˧˥ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "火车快开了，他还是很从容。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发生火灾时，她从容地带大家离开。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话从容，声音不快也不慢。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然比赛很难，她打得很从容。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生从容地检查了病人。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别慌，深呼吸，从容地做准备。", "target_word": "从容", "complexity_tier": "T3", "furigana": "cóng róng", "sentence_source": "generated"}, {"text": "他从容地走进教室，坐在第一排，神色平静。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人从容地喝着茶，看着窗外。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到危险，我们要保持从容。", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从容地笑了笑，说：“没关系。”", "target_word": "从容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從容", "label": "繁体"}, {"form": "从容不迫", "label": "复合"}], "register": "中性", "sense_fingerprint": "从容：不着急，很冷静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '461c370f-be46-4e41-96a9-fb0d343458d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从容", "is_correct": true, "explanation": "从容：不着急、很冷静，与“火车快开了”形成对照，符合句意。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：沙哑形容嗓音，“他还是很沙哑”不说人的神态，与镇定的态度无关。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：柔软指质地，不用于形容人的态度。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮多形容光线、眼神，不用来形容人的镇定。"}], "explanations": {"从容": "从容：不着急、很冷静，与“火车快开了”形成对照，符合句意。", "沙哑": "搭配：沙哑形容嗓音，“他还是很沙哑”不说人的神态，与镇定的态度无关。", "柔软": "语义：柔软指质地，不用于形容人的态度。", "明亮": "搭配：明亮多形容光线、眼神，不用来形容人的镇定。"}, "sentence_index": 0, "correct_answer": "从容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯从容地上升。", "explanation": "这里应该用〈平稳〉。从容形容人的镇定态度，电梯的运行要用“平稳”，不宜用来形容机器。"}, {"text": "山谷里很从容。", "explanation": "这里应该用〈寂静〉。从容形容的是人的不着急和冷静，不用来形容山谷。"}, {"text": "这间教室很从容。", "explanation": "这里应该用〈安静〉。从容说的是人的态度，教室是地点，应说“很安静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从容", "is_correct": true, "explanation": "从容：不着急、很冷静，与“走进教室，坐在第一排”的平和情景相合。"}, {"text": "鬼鬼祟祟", "is_correct": false, "explanation": "语义：鬼鬼祟祟带有偷偷摸摸的意思，与“坐在第一排”的光明正大相冲突。"}, {"text": "急急忙忙", "is_correct": false, "explanation": "语义：“神色平静”与“急急忙忙”的匆忙之态相冲突，句意不符。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：嘈杂形容声音或环境，不修饰“走进”的样子。"}], "explanations": {"从容": "从容：不着急、很冷静，与“走进教室，坐在第一排”的平和情景相合。", "鬼鬼祟祟": "语义：鬼鬼祟祟带有偷偷摸摸的意思，与“坐在第一排”的光明正大相冲突。", "急急忙忙": "语义：“神色平静”与“急急忙忙”的匆忙之态相冲突，句意不符。", "嘈杂": "搭配：嘈杂形容声音或环境，不修饰“走进”的样子。"}, "sentence_index": 6, "correct_answer": "从容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古镇的夜晚很从容。", "explanation": "这里应该用〈宁静〉。从容形容人的态度，夜晚的景色不能用它来形容。"}, {"text": "这块石头很从容。", "explanation": "这里应该用〈坚硬〉。从容形容人不着急、很冷静，不能用来形容石头的质地。"}, {"text": "这碗汤很从容。", "explanation": "这里应该用〈清淡〉。从容说的是人的态度，汤的味道不能用它来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
