INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说话很从容得，不急不慢。", "corrected_sentence": "她说话很从容，不急不慢。", "error_description": "错误：“很从容得，不急不慢”；正确：“很从容，不急不慢”。句中“得”后没有补语，多余，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e160aa02-16fd-42b8-aa62-5cea8c835703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
