INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22746, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嘴巴是脸上用来吃东西和说话的地方。", "primary_collocate": null, "pronunciation": "zuǐ ba", "ipa": "tswei̯ pa", "syllable_count": 2, "sentences": [{"text": "我的嘴巴很小，吃不下这么大的饺子。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴巴里有东西，说话听不清楚。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把嘴巴闭上，听老师说。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的嘴巴动个不停，一直在说话。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，我用纸擦了擦嘴巴。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个娃娃的嘴巴是红色的。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼的嘴巴一张一张的，在水里吃东西。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙以后，嘴巴里很干净。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴巴里塞满了糖，不能说话。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟用小小的嘴巴吃虫子。", "target_word": "嘴巴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "大嘴巴", "label": "复合"}], "register": "口语", "sense_fingerprint": "脸上用来吃东西和说话的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘴巴", "is_correct": true, "explanation": "正确：“我的嘴巴很小”说的是吃饺子的器官，与句意相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不参与吃饺子，句中的因果关系需要进食器官。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子不参与吃东西，吃不下饺子与鼻子大小无关。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不参与吃东西，“吃不下饺子”与耳朵的大小无关。"}], "explanations": {"嘴巴": "正确：“我的嘴巴很小”说的是吃饺子的器官，与句意相合。", "眼睛": "语义：眼睛不参与吃饺子，句中的因果关系需要进食器官。", "鼻子": "语义：鼻子不参与吃东西，吃不下饺子与鼻子大小无关。", "耳朵": "语义：耳朵不参与吃东西，“吃不下饺子”与耳朵的大小无关。"}, "sentence_index": 0, "correct_answer": "嘴巴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子的嘴巴动个不停，一直在跑。", "explanation": "这里应该用〈腿〉。跑要用腿，嘴巴不能跑。"}, {"text": "孩子的嘴巴转个不停，一直在看。", "explanation": "这里应该用〈眼睛〉。看要用眼睛，嘴巴不能看。"}, {"text": "她有一只很大的嘴巴，笑起来很好看。", "explanation": "这里应该用〈张〉作量词。嘴巴的量词是“张”，不说“一只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘴巴", "is_correct": true, "explanation": "正确：鱼一张一张地在水里吃东西，指的是嘴巴。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：尾巴不参与吃东西，句中一张一张的是嘴。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：鱼没有翅膀，不会一张一张地开合。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“一张一张”用于嘴，眼睛要说“眨”，不能说一张一张的。"}], "explanations": {"嘴巴": "正确：鱼一张一张地在水里吃东西，指的是嘴巴。", "尾巴": "语义：尾巴不参与吃东西，句中一张一张的是嘴。", "翅膀": "语义：鱼没有翅膀，不会一张一张地开合。", "眼睛": "搭配：“一张一张”用于嘴，眼睛要说“眨”，不能说一张一张的。"}, "sentence_index": 6, "correct_answer": "嘴巴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸟用嘴巴飞，飞得很高。", "explanation": "这里应该用〈翅膀〉。飞要靠翅膀，嘴巴不能用来飞。"}, {"text": "她用嘴巴听音乐，听得很入迷。", "explanation": "这里应该用〈耳朵〉。听音乐要用耳朵，嘴巴不能用来听。"}, {"text": "她用嘴巴搂住孩子，很温暖。", "explanation": "这里应该用〈胳膊〉。搂抱要用胳膊，嘴巴不能用来搂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个娃娃有一只红红的嘴巴。", "corrected_sentence": "这个娃娃有一张红红的嘴巴。", "error_description": "错误：“一只嘴巴”；正确：“一张嘴巴”。嘴巴的量词是“张”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条鱼有一只大大的嘴巴，在水里吃东西。", "corrected_sentence": "这条鱼有一张大大的嘴巴，在水里吃东西。", "error_description": "错误：“一只嘴巴”；正确：“一张嘴巴”。嘴巴的量词是“张”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
