INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "人因为困或累，嘴巴张大，深深吸一口气，然后很快呼出来。", "primary_collocate": "打", "pronunciation": "hā qian", "ipa": "xa˥ tɕʰjɛn", "syllable_count": 2, "sentences": [{"text": "我昨天没睡好，一直打哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打了一个大哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课的时候，很多同学都在打哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到别人打哈欠，我也想打哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用手捂住嘴，小声打了个哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子困了，不停地打哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太累的时候，人容易打哈欠。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸打着哈欠走进了厨房。", "target_word": "哈欠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看见我打哈欠，笑了笑。", "target_word": "哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他连着打了三个哈欠，真的太困了。", "target_word": "哈欠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "通俗说法：人困或累时张大嘴深吸一口气再呼出", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哈欠", "is_correct": true, "explanation": "正确：“一直打哈欠”指因没睡好而不停地张口深吸气，符合句意。"}, {"text": "雷", "is_correct": false, "explanation": "语义：人不能“打雷”，句子描述的是“我”没睡好的状态。"}, {"text": "桩", "is_correct": false, "explanation": "语义：“打桩”是建筑施工，与“没睡好、一直”的描写无关。"}, {"text": "谷", "is_correct": false, "explanation": "搭配：“打谷”指脱粒，不能用来描写困倦的状态，不说“一直打谷”。"}], "explanations": {"哈欠": "正确：“一直打哈欠”指因没睡好而不停地张口深吸气，符合句意。", "雷": "语义：人不能“打雷”，句子描述的是“我”没睡好的状态。", "桩": "语义：“打桩”是建筑施工，与“没睡好、一直”的描写无关。", "谷": "搭配：“打谷”指脱粒，不能用来描写困倦的状态，不说“一直打谷”。"}, "sentence_index": 0, "correct_answer": "哈欠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫在阳光下伸了个哈欠。", "explanation": "这里应该用〈懒腰〉。猫伸懒腰是伸展身体，哈欠是张口吸气的动作，不能用“伸”来带“哈欠”。"}, {"text": "他听到巨响，吓得打了个哈欠。", "explanation": "这里应该用〈冷战〉。受惊时会打冷战，哈欠是困倦或疲劳时张口吸气的动作，惊吓不会引起哈欠。"}, {"text": "她被烟呛得打了个哈欠。", "explanation": "这里应该用〈喷嚏〉。被烟呛到通常打喷嚏，哈欠是困倦时的动作，两者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哈欠", "is_correct": true, "explanation": "正确：“太累的时候，人容易打哈欠”符合常识，“哈欠”与语境吻合。"}, {"text": "铁", "is_correct": false, "explanation": "语义：“打铁”是锻造金属的劳动，与人在太累时的状态不搭。"}, {"text": "井", "is_correct": false, "explanation": "语义：“打井”是挖掘动作，不是人在困累时的表现，句意不通。"}, {"text": "蜡", "is_correct": false, "explanation": "搭配：“打蜡”用于器物表面，不能说“人容易打蜡”。"}], "explanations": {"哈欠": "正确：“太累的时候，人容易打哈欠”符合常识，“哈欠”与语境吻合。", "铁": "语义：“打铁”是锻造金属的劳动，与人在太累时的状态不搭。", "井": "语义：“打井”是挖掘动作，不是人在困累时的表现，句意不通。", "蜡": "搭配：“打蜡”用于器物表面，不能说“人容易打蜡”。"}, "sentence_index": 6, "correct_answer": "哈欠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃得太饱，打了个哈欠。", "explanation": "这里应该用〈饱嗝〉。吃得太饱会打饱嗝，哈欠是困倦时张口吸气的动作。"}, {"text": "外面太冷，他冷得打了个哈欠。", "explanation": "这里应该用〈寒战〉。受冷时身体发抖叫打寒战，哈欠是困倦时的动作。"}, {"text": "他用绳子打了个哈欠，把箱子绑好。", "explanation": "这里应该用〈结〉。用绳子要打结，哈欠是人困倦时的动作，不能用绳子打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一边听课，一边打了着哈欠。", "corrected_sentence": "他一边听课，一边打着哈欠。", "error_description": "“了”和“着”重复标记：“打着”已表示动作正在进行，中间不应再加“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲到一半，他忍不住把打了个哈欠。", "corrected_sentence": "老师讲到一半，他忍不住打了个哈欠。", "error_description": "“把”字句要求“把”后有宾语，此处“把”后直接接动词，没有宾语，应删去“把”，写作“忍不住打了个哈欠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
