INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22764, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟着就是走在别人后面或和别的人一起去。", "primary_collocate": null, "pronunciation": "gēn zhe", "ipa": "kən˥ tʂɤ", "syllable_count": 2, "sentences": [{"text": "小狗跟着我走回了家。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着老师走进教室。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跟着我，别走丢了。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟着爸爸去公园玩儿。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客跟着导游参观博物馆。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在前面走，我在后面跟着。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家跟着我，不要说话。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总是跟着哥哥，哪儿都想去。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们跟着前面的车开到了山上。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟着朋友一起去了北京。", "target_word": "跟着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟", "label": "基本形式"}], "register": "中性", "sense_fingerprint": "走在别人后面，或和别人一起行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟着", "is_correct": true, "explanation": "正确。“跟着”表示走在别人后面，符合“小狗跟着我走回了家”的句意。"}, {"text": "抱", "is_correct": false, "explanation": "语义：小狗不能抱着人走路，与句意不合。"}, {"text": "躲着", "is_correct": false, "explanation": "语义：“躲着”与一起走回家的意思相反。"}, {"text": "扶", "is_correct": false, "explanation": "搭配：“扶”多用于人扶人，不说小狗扶人走路。"}], "explanations": {"跟着": "正确。“跟着”表示走在别人后面，符合“小狗跟着我走回了家”的句意。", "抱": "语义：小狗不能抱着人走路，与句意不合。", "躲着": "语义：“躲着”与一起走回家的意思相反。", "扶": "搭配：“扶”多用于人扶人，不说小狗扶人走路。"}, "sentence_index": 0, "correct_answer": "跟着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跟着一把伞出门，以防下雨。", "explanation": "这里应该用〈带着〉。跟着表示跟随某人同行，不能跟随物品，随身携带东西要说带着。"}, {"text": "他跟着一瓶水去公园玩儿。", "explanation": "这里应该用〈带着〉。跟着表示跟随某人同行，不能跟随物品，随身拿东西要说带着。"}, {"text": "他跟着一袋米回家。", "explanation": "这里应该用〈扛着〉。跟着表示跟随某人同行，不能跟随物品，扛东西要说扛着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟着", "is_correct": true, "explanation": "正确。“请大家跟着我，不要说话”表示大家走在我后面，符合句意。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”与请别人跟随自己的意思相反，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与请大家跟着自己走的语境不合。"}, {"text": "伺候", "is_correct": false, "explanation": "搭配：“伺候”多指照顾别人的生活，不用于带领大家行动。"}], "explanations": {"跟着": "正确。“请大家跟着我，不要说话”表示大家走在我后面，符合句意。", "欺骗": "语义：“欺骗”与请别人跟随自己的意思相反，句意不通。", "嘲笑": "语义：“嘲笑”与请大家跟着自己走的语境不合。", "伺候": "搭配：“伺候”多指照顾别人的生活，不用于带领大家行动。"}, "sentence_index": 6, "correct_answer": "跟着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跟着一个行李箱去了北京。", "explanation": "这里应该用〈拖着〉。跟着表示跟随某人同行，不能跟随物品，拖行行李箱要说拖着。"}, {"text": "她跟着病去了北京。", "explanation": "这里应该用〈带病〉。跟着表示跟随某人同行，不能说病跟随人，带病的状态要说带病。"}, {"text": "她跟着朋友的钱去了北京。", "explanation": "这里应该用〈花〉。跟着指跟随同行，不能表示用别人的钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直跟着姐姐着上学。", "corrected_sentence": "他一直跟着姐姐上学。", "error_description": "“着”多加了一个，写成“姐姐着上学”。“跟着”已含“着”，“着”不能再接在“姐姐”后面，应去掉多余的“着”，即“跟着姐姐上学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们跟了着老师走出了教室。", "corrected_sentence": "孩子们跟着老师走出了教室。", "error_description": "“跟着”是一个词，“了”不能插在中间。“跟了着老师”不成立，应为“跟着老师走出了教室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
