INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22772, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不是一直，是有些时候。", "primary_collocate": null, "pronunciation": "yǒu shí hou", "ipa": "joʊ˨˩˦ ʂɨ˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "我平时骑车，有时候坐地铁。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有时候很安静，有时候很爱说话。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的春天有时候会刮大风。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有时候忘了带手机。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我有时候在家看书，有时候出去玩。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭很好吃，有时候也会太咸。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟有时候一天只吃两顿饭。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里夏天很热，有时候晚上也不凉快。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不常迟到，只是有时候起晚了。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有时候走路去学校，有时候坐车去。", "target_word": "有时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有時候", "label": "繁体"}], "register": "口语", "sense_fingerprint": "表示某种情况不是总发生，只在部分时间发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有时候", "is_correct": true, "explanation": "正确。“有时候”表示只在部分时间如此，与“平时骑车”形成对比，符合句意。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示一直如此，与“平时骑车”的习惯相矛盾，句子读不通。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立即，不能与“平时”这种表示习惯的词搭配。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示必然，与“平时骑车”同时成立会造成矛盾，不符合句中的对比。"}], "explanations": {"有时候": "正确。“有时候”表示只在部分时间如此，与“平时骑车”形成对比，符合句意。", "总是": "语义：“总是”表示一直如此，与“平时骑车”的习惯相矛盾，句子读不通。", "马上": "搭配：“马上”表示立即，不能与“平时”这种表示习惯的词搭配。", "一定": "语义：“一定”表示必然，与“平时骑车”同时成立会造成矛盾，不符合句中的对比。"}, "sentence_index": 0, "correct_answer": "有时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有时候每天都坐地铁上班。", "explanation": "这里应该用〈总是〉。“有时候”表示不是每次都发生，和“每天都”意思矛盾。"}, {"text": "我昨天有时候去了超市。", "explanation": "“有时候”表示经常性或不定期的情况，不能用于昨天这样确定的一次，这里应删去“有时候”。"}, {"text": "我有时候总是忘了带手机。", "explanation": "这里“有时候”用错了，应该用〈经常〉。“有时候”指并非每次都发生，这句说的是经常忘带，与它的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有时候", "is_correct": true, "explanation": "正确。“有时候”表示只在某些时候如此，与“一天只吃两顿饭”的描述相符。"}, {"text": "一边", "is_correct": false, "explanation": "语义：「一边」要求两个同时进行的动作，句中没有第二个动作，不能用于此处。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生不久，与“一天只吃两顿饭”这种长期习惯不符。"}, {"text": "很快", "is_correct": false, "explanation": "搭配：“很快”多用于即将发生的变化，不与“一天只吃两顿饭”这种习惯搭配。"}], "explanations": {"有时候": "正确。“有时候”表示只在某些时候如此，与“一天只吃两顿饭”的描述相符。", "一边": "语义：「一边」要求两个同时进行的动作，句中没有第二个动作，不能用于此处。", "刚刚": "语义：“刚刚”指刚发生不久，与“一天只吃两顿饭”这种长期习惯不符。", "很快": "搭配：“很快”多用于即将发生的变化，不与“一天只吃两顿饭”这种习惯搭配。"}, "sentence_index": 6, "correct_answer": "有时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她有时候每天都走路去学校。", "explanation": "这里“有时候”用错了，应该用〈总是〉。“有时候”指部分时间，和“每天都”意思矛盾。"}, {"text": "她有时候考了一次满分。", "explanation": "这里应该用〈曾经〉。“有时候”指反复出现的情况，这句说的是某一次已经发生的事。"}, {"text": "她每次有时候走路去学校。", "explanation": "这里“有时候”用错了，应该用〈总是〉。“有时候”指并非每次都发生，这句要说的是每回都如此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的有时候迟到。", "corrected_sentence": "他有时候迟到。", "error_description": "“的”不能加在主语“他”后面：“有时候”是副词，应直接放在动词前，说“他有时候迟到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟很有时候吃面条。", "corrected_sentence": "我弟弟有时候吃面条。", "error_description": "“很”是程度副词，不能修饰“有时候”，应删去“很”，说“我弟弟有时候吃面条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
