INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "张开手臂抱住别人，表示喜欢。", "primary_collocate": null, "pronunciation": "yōng bào", "ipa": "jʊŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小女孩跑过来，紧紧拥抱住妈妈。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他张开手臂，拥抱了自己的好朋友。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拥抱一下刚回国的姐姐。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹一见到表姐，就高兴地拥抱了她。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到老师，孩子高兴地拥抱了她。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷拥抱着孙子，脸上全是笑容。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生日那天，我送上礼物，还拥抱了他。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她难过的时候，我会轻轻拥抱她。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子一见面就互相拥抱。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出差回来，先拥抱了妈妈。", "target_word": "拥抱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥抱了", "label": "体标"}, {"form": "拥抱着", "label": "体标"}, {"form": "拥抱过", "label": "体标"}, {"form": "擁抱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "张开手臂抱住人，表示喜欢、亲近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fc4ee6-6dc8-4fd3-8f85-e321ebdc3c7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥抱", "is_correct": true, "explanation": "正确：“紧紧拥抱住”表示亲热地抱住人，与“跑过来”的亲近动作相符。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”表示用力使人离开，与“跑过来”的亲近动作相反。"}, {"text": "夹", "is_correct": false, "explanation": "语义：“夹”表示挤压，与“紧紧”带有亲热的语境不符。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”表示压住不让动，与“跑过来”的亲近动作矛盾。"}], "explanations": {"拥抱": "正确：“紧紧拥抱住”表示亲热地抱住人，与“跑过来”的亲近动作相符。", "推": "语义：“推”表示用力使人离开，与“跑过来”的亲近动作相反。", "夹": "语义：“夹”表示挤压，与“紧紧”带有亲热的语境不符。", "按": "语义：“按”表示压住不让动，与“跑过来”的亲近动作矛盾。"}, "sentence_index": 0, "correct_answer": "拥抱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上拥抱牙齿。", "explanation": "这里应该用〈刷〉。“拥抱”是张开手臂抱住人，刷牙要用“刷”。"}, {"text": "他用力拥抱开了门。", "explanation": "这里应该用〈推〉。“拥抱”指张开手臂抱住人，开门要用“推”。"}, {"text": "妈妈用刀拥抱西瓜。", "explanation": "这里应该用〈切〉。“拥抱”指张开手臂抱住人，用刀切西瓜要用“切”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": true, "explanation": "正确：“还拥抱了他”表示亲热地抱住人，与生日送礼物的语境相符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与“送上礼物”的语境无关。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指制作食品，不能用于“他”这样的人。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物品或场所，不能用于人。"}], "explanations": {"拥抱": "正确：“还拥抱了他”表示亲热地抱住人，与生日送礼物的语境相符。", "翻译": "语义：“翻译”指转换语言，与“送上礼物”的语境无关。", "烘焙": "语义：“烘焙”指制作食品，不能用于“他”这样的人。", "装饰": "搭配：“装饰”用于物品或场所，不能用于人。"}, "sentence_index": 6, "correct_answer": "拥抱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人一起把桌子拥抱到楼上。", "explanation": "这里应该用〈抬〉。“拥抱”是用双臂抱住人，表示亲近，搬桌子上楼要用“抬”。"}, {"text": "她拥抱短了头发。", "explanation": "这里应该用〈剪〉。“拥抱”的动作对象是人，剪头发要用“剪”。"}, {"text": "妈妈每天拥抱地。", "explanation": "这里应该用〈扫〉。“拥抱”的对象是人，扫地要用“扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想拥抱你一个，别难过。", "corrected_sentence": "我想拥抱你一下，别难过。", "error_description": "量词错误：表示动作次数的补语应用“一下”，不能用量词“个”，应说“拥抱你一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一下车就拥抱着了等在门口的母亲。", "corrected_sentence": "她一下车就拥抱了等在门口的母亲。", "error_description": "“着”与“了”混用：“着”表示动作持续，“了”表示动作完成，两者不能并用。动作已完成，应说“拥抱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92f6e03d-fbbe-4c50-96e9-612e29e2a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
