INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "科学家是研究自然世界、做实验和发明东西的人。", "primary_collocate": null, "pronunciation": "kē xué jiā", "ipa": "kʰɤ˥ ɕɥe˧˥ tɕja˥", "syllable_count": 3, "sentences": [{"text": "这位科学家每天都在实验室里工作。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我长大以后想当科学家。", "target_word": "科学家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家正在研究怎样让海水变干净。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱因斯坦是一位很有名的科学家。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那名年轻的科学家做了一个有趣的实验。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用望远镜观察月亮。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明说：“我爸爸是科学家，他研究植物。”", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家发明了新机器，帮农民种地。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "许多科学家来到南极，研究冰和天气。", "target_word": "科学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是一位科学家，一直研究海洋里的小动物。", "target_word": "科学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女科学家", "label": "复合"}, {"form": "科學家", "label": "繁体"}], "register": "通用", "sense_fingerprint": "科学家：从事科学研究、做实验的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学家", "is_correct": true, "explanation": "正确。科学家指从事科学研究的人，与“每天在实验室里工作”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民主要在田间劳动，与“在实验室里工作”不符。"}, {"text": "花", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“花”，花也不能在实验室里工作。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机的工作场所在路上，与“在实验室里工作”不符。"}], "explanations": {"科学家": "正确。科学家指从事科学研究的人，与“每天在实验室里工作”相符。", "农民": "语义：农民主要在田间劳动，与“在实验室里工作”不符。", "花": "搭配：量词“位”只用于人，不能修饰“花”，花也不能在实验室里工作。", "司机": "语义：司机的工作场所在路上，与“在实验室里工作”不符。"}, "sentence_index": 0, "correct_answer": "科学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个实验很科学家。", "explanation": "这里应该用〈科学〉。〈科学家〉指人，不能用来形容实验，应说“很科学”。"}, {"text": "这位科学家负责设计这座大桥的结构。", "explanation": "这里应该用〈工程师〉。〈科学家〉研究自然规律、做实验，设计桥梁结构属于工程师的工作。"}, {"text": "这位科学家每天在厨房里做四十份菜。", "explanation": "这里应该用〈厨师〉。〈科学家〉指研究自然世界的人，每天在厨房做菜属于厨师的工作，不能用〈科学家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学家", "is_correct": true, "explanation": "正确。“我爸爸是科学家”与后句“他研究植物”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，与“他研究植物”不符。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员的工作是表演，与“他研究植物”不符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“是”后接的人物身份名词要指人，“面包”不能作父亲的身份。"}], "explanations": {"科学家": "正确。“我爸爸是科学家”与后句“他研究植物”相符。", "厨师": "语义：厨师的工作是做饭，与“他研究植物”不符。", "演员": "语义：演员的工作是表演，与“他研究植物”不符。", "面包": "搭配：“是”后接的人物身份名词要指人，“面包”不能作父亲的身份。"}, "sentence_index": 6, "correct_answer": "科学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的研究方向是科学家。", "explanation": "这里应该用〈科学〉。〈科学〉指学问领域，〈科学家〉指人，不能作研究方向。"}, {"text": "这位科学家每天在医院为病人做手术。", "explanation": "这里应该用〈医生〉。〈科学家〉指做实验、研究自然的人，为病人做手术属于医生的工作。"}, {"text": "这位科学家在法庭上为客人辩护。", "explanation": "这里应该用〈律师〉。〈科学家〉指研究自然世界的人，在法庭为人辩护属于律师的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈希望我以后成为一只科学家。", "corrected_sentence": "妈妈希望我以后成为一名科学家。", "error_description": "量词错误：“科学家”指人，应用“名”或“位”，不能用“只”。正确的说法是“一名科学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的邻居是一名科学家们，他在大学工作。", "corrected_sentence": "我的邻居是一名科学家，他在大学工作。", "error_description": "复数标记错误：“们”不能与数量词“一名”连用，“科学家”后不能加“们”，应为“一名科学家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
