INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22780, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "累就是身体很累，想休息。", "primary_collocate": null, "pronunciation": "lèi", "ipa": "leɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我今天走了很多路，真累。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸工作了一天，很累。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了就休息一下吧。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑了十公里，累得说不出话。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩儿了一天，累坏了。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不累，还可以再走一会儿。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天加班到很晚，今天特别累。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带着孩子逛街，妈妈觉得很累。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累了，想回家睡觉。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬了一下午的东西，大家都累了。", "target_word": "累", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "累了", "label": "体标"}, {"form": "累坏了", "label": "补语"}], "register": "中性", "sense_fingerprint": "身体疲劳，想要休息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "累", "is_correct": true, "explanation": "正确：累（lèi）表示身体疲劳、想休息。"}, {"text": "雷", "is_correct": false, "explanation": "léi（第二声）与 lèi（第四声）声调不同，雷是打雷的雷。"}, {"text": "内", "is_correct": false, "explanation": "nèi 与 lèi 声母不同（n/l），内表示里面。"}, {"text": "蕾", "is_correct": false, "explanation": "lěi（第三声）与 lèi（第四声）声调不同，蕾指花蕾。"}], "explanations": {"累": "正确：累（lèi）表示身体疲劳、想休息。", "雷": "léi（第二声）与 lèi（第四声）声调不同，雷是打雷的雷。", "内": "nèi 与 lèi 声母不同（n/l），内表示里面。", "蕾": "lěi（第三声）与 lèi（第四声）声调不同，蕾指花蕾。"}, "sentence_index": null, "correct_answer": "累"}, "level_3": {"options": [{"text": "累", "is_correct": true, "explanation": "正确。累表示身体疲劳，符合“走了很多路，真累”的语境。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”与走了很多路的疲劳感相反，句意矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”说整洁，不用来形容走路后的身体状态。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”指排列或外表规整，与走路的感受无关。"}], "explanations": {"累": "正确。累表示身体疲劳，符合“走了很多路，真累”的语境。", "轻松": "语义：“轻松”与走了很多路的疲劳感相反，句意矛盾。", "干净": "搭配：“干净”说整洁，不用来形容走路后的身体状态。", "整齐": "语义：“整齐”指排列或外表规整，与走路的感受无关。"}, "sentence_index": 0, "correct_answer": "累"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很累，搬不动。", "explanation": "这里应该用〈重〉。累指人身体疲劳，石头的分量要说重。"}, {"text": "他摔了一跤，脚踝很累。", "explanation": "这里应该用〈疼〉。累指身体疲劳，脚踝受伤的感觉要说疼。"}, {"text": "我一上午没吃东西，肚子很累。", "explanation": "这里应该用〈饿〉。累指身体疲劳，没吃东西的感觉要说饿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "累", "is_correct": true, "explanation": "正确。“昨天加班到很晚，今天特别累”说明加班后身体疲劳，符合句意。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体的质地，不用来说人的身体状态。"}, {"text": "浅", "is_correct": false, "explanation": "语义：“浅”指深度，与加班后的疲劳无关。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”指颜色，与句中的疲劳状态无关。"}], "explanations": {"累": "正确。“昨天加班到很晚，今天特别累”说明加班后身体疲劳，符合句意。", "硬": "搭配：“硬”形容物体的质地，不用来说人的身体状态。", "浅": "语义：“浅”指深度，与加班后的疲劳无关。", "白": "语义：“白”指颜色，与句中的疲劳状态无关。"}, "sentence_index": 6, "correct_answer": "累"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喝累了，连路都走不稳。", "explanation": "这里应该用〈醉〉。喝多了酒走不稳是醉，累表示身体疲劳，不能用于喝酒后的状态。"}, {"text": "一上午没喝水，他的嘴很累。", "explanation": "这里应该用〈渴〉。累指身体疲劳，没喝水的感觉要说渴。"}, {"text": "看见蛇，他累得直哭。", "explanation": "这里应该用〈吓〉。累表示身体疲劳，害怕的反应要说吓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次搬家，他累得坏了。", "corrected_sentence": "这次搬家，他累坏了。", "error_description": "“累坏了”是“累”加结果补语，中间不用“得”。“累得坏了”不成立，应为“累坏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天真的累很。", "corrected_sentence": "我今天真的很累。", "error_description": "副词“很”应放在“累”前面，写成“很累”。“累很”的语序不成立，应为“真的很累”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
