INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空气是周围的气体，我们看不见它，但能呼吸它。", "primary_collocate": null, "pronunciation": "kōng qì", "ipa": "kʰʊŋ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "山里的空气很新鲜。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每天都需要呼吸空气。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，让新鲜空气进来。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的空气不太好，天空是灰色的。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他深深吸了一口空气。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，空气里有青草的味道。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的空气太热，我想开空调。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树多的地方，空气更干净。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看不见空气，但是能感觉到风。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂关门以后，这里的空气变好了。", "target_word": "空气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口", "label": "量词"}, {"form": "股", "label": "量词"}, {"form": "空气污染", "label": "复合"}], "register": "中性", "sense_fingerprint": "周围能呼吸的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": true, "explanation": "“新鲜”可以形容空气，“山里的空气很新鲜”自然。"}, {"text": "帐篷", "is_correct": false, "explanation": "语义：帐篷不能被说成“新鲜”，句子的描述说不通。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥没有“新鲜”的属性，句子无法成立。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是可以“新鲜”的事物，句子说不通。"}], "explanations": {"空气": "“新鲜”可以形容空气，“山里的空气很新鲜”自然。", "帐篷": "语义：帐篷不能被说成“新鲜”，句子的描述说不通。", "水泥": "语义：水泥没有“新鲜”的属性，句子无法成立。", "电脑": "语义：电脑不是可以“新鲜”的事物，句子说不通。"}, "sentence_index": 0, "correct_answer": "空气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的空气很大，可以放三张床。", "explanation": "这里应该用〈空间〉。空气是气体，看不见，不能用“大”来形容；房间的大小要说空间。"}, {"text": "窗外下起了空气。", "explanation": "这里应该用〈雪〉。“下”用于雨、雪，空气看不见，不能说“下”。"}, {"text": "医院里给病人输空气。", "explanation": "这里应该用〈氧气〉。给病人输的是氧气，空气不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": true, "explanation": "房间里的空气闷热，所以需要开空调，符合“太热”的描述。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不会“太热”，句子说不通。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不能用“太热”来形容，与温度的描述不合。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“太热”形容温度，“味道”宜说“太香”或“太浓”。"}], "explanations": {"空气": "房间里的空气闷热，所以需要开空调，符合“太热”的描述。", "课本": "语义：课本不会“太热”，句子说不通。", "歌声": "语义：歌声不能用“太热”来形容，与温度的描述不合。", "味道": "搭配：“太热”形容温度，“味道”宜说“太香”或“太浓”。"}, "sentence_index": 6, "correct_answer": "空气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的空气很低。", "explanation": "这里应该用〈气温〉。温度的高低说“气温”，空气本身不分高低。"}, {"text": "房间里开着空气。", "explanation": "这里应该用〈空调〉。“开”用于空调、灯等设备，空气不能“开”。"}, {"text": "纸上有很多空气。", "explanation": "这里应该用〈空白〉。纸上的空处要说“空白”，空气是气体，不能指纸上的空白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外的空气们很干净。", "corrected_sentence": "窗外的空气很干净。", "error_description": "错误：多加了“们”。正确：去掉“们”。“空气”是不可数名词，不能加“们”，“们”只用于指人的名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早上我们在山上深深吸了一只空气。", "corrected_sentence": "早上我们在山上深深吸了一口空气。", "error_description": "量词错误：吸进的空气用量词“口”（如“吸了一口空气”），不能用“只”。正确：“一口空气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": true, "explanation": "正确：“冷”与“热”是温度上的反义词，“冷”表示温度低。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“热”不构成反义，“慢”说的是速度。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”与“热”不构成反义，“硬”说的是质地。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“热”不构成反义，“快”说的是速度。"}], "correct_answer": "冷", "explanations": {"冷": "正确：“冷”与“热”是温度上的反义词，“冷”表示温度低。", "慢": "“慢”与“热”不构成反义，“慢”说的是速度。", "硬": "“硬”与“热”不构成反义，“硬”说的是质地。", "快": "“快”与“热”不构成反义，“快”说的是速度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": true, "explanation": "正确：“冷”与“热”是温度上的反义词，句中“天气热了”的反面是“冷”。"}, {"text": "远", "is_correct": false, "explanation": "“远”与“热”不构成反义，“远”说的是距离。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“热”不构成反义，“深”说的是深浅。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”与“热”不构成反义，“轻”说的是重量。"}], "correct_answer": "冷", "explanations": {"冷": "正确：“冷”与“热”是温度上的反义词，句中“天气热了”的反面是“冷”。", "远": "“远”与“热”不构成反义，“远”说的是距离。", "深": "“深”与“热”不构成反义，“深”说的是深浅。", "轻": "“轻”与“热”不构成反义，“轻”说的是重量。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像火或太阳一样，让人感觉温度高的。", "primary_collocate": null, "pronunciation": "rè", "ipa": "ɻɤ˥˩", "syllable_count": 1, "sentences": [{"text": "今天天气很热。", "target_word": "热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的中午特别热。", "target_word": "热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "屋子里太热，我想开窗。", "target_word": "热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我跑完步，觉得身上很热。", "target_word": "热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里不冷也不热，很舒服。", "target_word": "热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面又热又晒，别出去了。", "target_word": "热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的太阳大，沙子也很热。", "target_word": "热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火很大，站在旁边觉得热。", "target_word": "热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教室里人太多，大家都觉得热。", "target_word": "热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气热了，我们开了空调。", "target_word": "热", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "热热的", "label": "重叠"}, {"form": "熱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "热：温度高，让人感觉像火或太阳那样热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "热", "is_correct": true, "explanation": "正确：“热”（rè）指温度高，是这个词的本义。"}, {"text": "乐", "is_correct": false, "explanation": "lè（第四声）与 rè 声母不同（l/r），意思是快乐。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 rè 韵母不同（i/e），意思是太阳、日子。"}, {"text": "惹", "is_correct": false, "explanation": "rě（第三声）与 rè 声调不同，意思是招惹。"}, {"text": "任", "is_correct": false, "explanation": "rèn（第四声）比 rè 多一个韵尾 n，意思是任务、担任。"}], "explanations": {"热": "正确：“热”（rè）指温度高，是这个词的本义。", "乐": "lè（第四声）与 rè 声母不同（l/r），意思是快乐。", "日": "rì（第四声）与 rè 韵母不同（i/e），意思是太阳、日子。", "惹": "rě（第三声）与 rè 声调不同，意思是招惹。", "任": "rèn（第四声）比 rè 多一个韵尾 n，意思是任务、担任。"}, "sentence_index": null, "correct_answer": "热"}, "level_3": {"options": [{"text": "热", "is_correct": true, "explanation": "正确：“热”说温度高，与“天气很”搭配，符合句意。"}, {"text": "大", "is_correct": false, "explanation": "搭配：“大”多用于风、雨，不说“天气很大”。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量沉，与天气的温度无关。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，天气不能“快”。"}], "explanations": {"热": "正确：“热”说温度高，与“天气很”搭配，符合句意。", "大": "搭配：“大”多用于风、雨，不说“天气很大”。", "重": "语义：“重”说分量沉，与天气的温度无关。", "快": "语义：“快”说速度，天气不能“快”。"}, "sentence_index": 0, "correct_answer": "热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的交通很热，车子走得很慢。", "explanation": "这里应该用〈繁忙〉。“热”表示温度高，形容车流多、交通忙要用“繁忙”或“拥挤”。"}, {"text": "这幅油画的颜色很热，看起来很舒服。", "explanation": "这里应该用〈暖〉。颜色的冷暖要说“暖”或“冷”，“热”只用于温度高。"}, {"text": "这块蛋糕的味道很热，孩子都不爱吃。", "explanation": "这里应该用〈甜〉或〈辣〉。“热”表示温度高，不用来形容味道，味道的甜、辣等要用对应的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "热", "is_correct": true, "explanation": "正确：“热”（rè）指温度高。"}, {"text": "课", "is_correct": false, "explanation": "kè（第四声）与 rè 仅声母不同（k/r），意思是功课、课程。"}, {"text": "入", "is_correct": false, "explanation": "rù（第四声）与 rè 韵母不同（u/e），意思是进入。"}, {"text": "认", "is_correct": false, "explanation": "rèn（第四声）比 rè 多一个韵尾 n，意思是认识。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 rè 仅声母不同（g/r），意思是量词“个”。"}], "explanations": {"热": "正确：“热”（rè）指温度高。", "课": "kè（第四声）与 rè 仅声母不同（k/r），意思是功课、课程。", "入": "rù（第四声）与 rè 韵母不同（u/e），意思是进入。", "认": "rèn（第四声）比 rè 多一个韵尾 n，意思是认识。", "个": "gè（第四声）与 rè 仅声母不同（g/r），意思是量词“个”。"}, "sentence_index": null, "correct_answer": "热"}, "level_3": {"options": [{"text": "热", "is_correct": true, "explanation": "正确：“热”与前句“太阳大”相呼应，表示温度高。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”与前句“太阳大”矛盾，太阳大时沙子不会冷。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不能说沙子很慢。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”说距离，不能说沙子很远。"}], "explanations": {"热": "正确：“热”与前句“太阳大”相呼应，表示温度高。", "冷": "语义：“冷”与前句“太阳大”矛盾，太阳大时沙子不会冷。", "慢": "搭配：“慢”说速度，不能说沙子很慢。", "远": "搭配：“远”说距离，不能说沙子很远。"}, "sentence_index": 6, "correct_answer": "热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的声音很热，邻居都被吵醒了。", "explanation": "这里应该用〈响〉。“热”表示温度高，不用来形容声音，声音大要说“响”。"}, {"text": "这次考试的分数很热，全班都很高兴。", "explanation": "这里应该用〈高〉。分数的多少说“高”或“低”，“热”不能用来描述分数。"}, {"text": "这件衣服的价钱很热，我买不起。", "explanation": "这里应该用〈贵〉。价格高要说“贵”，“热”不能用来描述价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子热很，我们开了窗。", "corrected_sentence": "这间屋子很热，我们开了窗。", "error_description": "语序错误：程度副词“很”应放在形容词“热”前面，“热很”不对，应为“很热”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个房间很很热，我们开了空调。", "corrected_sentence": "这个房间很热，我们开了空调。", "error_description": "副词重复错误：“很”只用一次，应说“很热”，不能说“很很热”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
