INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动物是能动的、会吃东西的生物。", "primary_collocate": null, "pronunciation": "dòng wù", "ipa": "tʊŋ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "狗和猫都是常见的动物。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去公园看动物。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象是陆地上最大的动物。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很喜欢动物，家里养了两只猫。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物需要吃东西，也需要喝水。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼是生活在水里的动物。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，有些动物会睡很久。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要给动物吃人的东西。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有很多动物，比如鹿和鸟。", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我：“鸟是不是动物？”", "target_word": "动物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "动物园", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指能自己活动、需要进食的生物，如狗、鱼、鸟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物", "is_correct": true, "explanation": "动物：本句的答案，指能自己活动、需要进食的生物，狗和猫属于此类。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：狗和猫是活的生物，不是玩具，“玩具”与句子的分类不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：狗和猫不是植物，植物不能自己活动，与句子的分类矛盾。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“常见的”后接的类别不包括“家具”，狗和猫与家具不是同类事物。"}], "explanations": {"动物": "动物：本句的答案，指能自己活动、需要进食的生物，狗和猫属于此类。", "玩具": "语义：狗和猫是活的生物，不是玩具，“玩具”与句子的分类不符。", "植物": "语义：狗和猫不是植物，植物不能自己活动，与句子的分类矛盾。", "家具": "搭配：“常见的”后接的类别不包括“家具”，狗和猫与家具不是同类事物。"}, "sentence_index": 0, "correct_answer": "动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "细菌是一种很小的动物，只有显微镜才能看到。", "explanation": "这里应该用〈微生物〉。细菌属于微生物，不属于动物，动物专指能自己活动、需要进食的生物。"}, {"text": "公园里种了很多动物。", "explanation": "这里应该用〈植物〉。“种”用于植物，不用于动物，动物不能说“种”。"}, {"text": "妈妈做了很多好吃的动物，我们一起吃晚饭。", "explanation": "这里应该用〈菜〉。妈妈做好、可以吃的是菜，动物指能自己活动、需要进食的生物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物", "is_correct": true, "explanation": "动物：本句的答案，指能在冬天进入长时间睡眠的生物。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”没有睡觉的能力，不能说“有些食物会睡很久”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能睡觉，“会睡很久”只能用于有生命的生物。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指外表样子，不能“睡很久”，与句子的主语不符。"}], "explanations": {"动物": "动物：本句的答案，指能在冬天进入长时间睡眠的生物。", "食物": "语义：“食物”没有睡觉的能力，不能说“有些食物会睡很久”。", "石头": "语义：“石头”不能睡觉，“会睡很久”只能用于有生命的生物。", "外貌": "语义：“外貌”指外表样子，不能“睡很久”，与句子的主语不符。"}, "sentence_index": 6, "correct_answer": "动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种动物很结实，用了很多年。", "explanation": "这里应该用〈家具〉。动物是能动、会吃东西的生物，不能用“用了很多年”来形容。"}, {"text": "水是一种动物。", "explanation": "这里应该用〈物质〉。动物指能自己活动的生物，水不属于动物。"}, {"text": "这种动物运行得很好。", "explanation": "这里应该用〈机器〉。“运行”用于机器等装置，不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在公园里看见了两位动物。", "corrected_sentence": "我在公园里看见了两只动物。", "error_description": "量词错误：“动物”应与量词“只”搭配，说“两只动物”；“位”用于人，不能用来数动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该保护野动物。", "corrected_sentence": "我们应该保护野生动物。", "error_description": "词语错误：“野生动物”是固定搭配，“野动物”不成词，应补上“生”，写作“野生动物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
