INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛看见人、东西或地方。", "primary_collocate": null, "pronunciation": "kàn dào", "ipa": "kʰan˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在路上看到一只小狗。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看到我的书了吗？", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗外看到了雪。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看到老师就跑过去。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我看到你妈妈了。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上能看到很远的地方。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看到他进来。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到蛋糕，高兴极了。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地铁里，我看到过一位明星。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太黑，我没看到路。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看到了", "label": "完成体"}, {"form": "看到过", "label": "经历体"}, {"form": "看不到", "label": "否定可能式"}], "register": "中性", "sense_fingerprint": "眼睛看见了人、东西或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看到", "is_correct": true, "explanation": "正确：“看到”表示眼睛看见，“在路上看到一只小狗”正合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，小狗不能被煮，句子说的是看见，句意不通。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”只用于文件、照片等，不能说“打印一只小狗”。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”指打开包装，用于一只小狗不合常理，句子不通。"}], "explanations": {"看到": "正确：“看到”表示眼睛看见，“在路上看到一只小狗”正合句意。", "煮": "语义：“煮”是烹饪，小狗不能被煮，句子说的是看见，句意不通。", "打印": "搭配：“打印”只用于文件、照片等，不能说“打印一只小狗”。", "拆开": "语义：“拆开”指打开包装，用于一只小狗不合常理，句子不通。"}, "sentence_index": 0, "correct_answer": "看到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都看到一阵暖意。", "explanation": "这里应该用〈感到〉。暖意是身体的感觉，不能用看到。"}, {"text": "我看到了一段美妙的音乐。", "explanation": "这里应该用〈听到〉。音乐要用耳朵听，“看到”只用于视觉对象。"}, {"text": "我看到了饭菜的香味。", "explanation": "这里应该用〈闻到〉。香味要用鼻子闻，不能说看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看到", "is_correct": true, "explanation": "正确：“看到”表示眼睛看见，“我没看到他进来”正合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理，不能表示看见他进门，句子不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，与看见他进门无关，句意不通。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”是指出别人的错误，不能与“进来”组合表示感知。"}], "explanations": {"看到": "正确：“看到”表示眼睛看见，“我没看到他进来”正合句意。", "打扫": "语义：“打扫”是清理，不能表示看见他进门，句子不通。", "翻译": "语义：“翻译”是转换语言，与看见他进门无关，句意不通。", "批评": "搭配：“批评”是指出别人的错误，不能与“进来”组合表示感知。"}, "sentence_index": 6, "correct_answer": "看到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜，我看到了甜味。", "explanation": "这里应该用〈尝到〉。甜味要靠舌头品尝，不能说看到。"}, {"text": "花园里，我看到了花香。", "explanation": "这里应该用〈嗅到〉。花香要用鼻子嗅，不能说看到。"}, {"text": "风吹过来，我看到了一阵凉意。", "explanation": "这里应该用〈感到〉。凉意是身体的感觉，不能用看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在超市看到了了一个熟人。", "corrected_sentence": "我在超市看到了一个熟人。", "error_description": "“看到了”后面不能再加一个“了”，应为「看到了一个熟人」，只用一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天不看到那辆车。", "corrected_sentence": "我昨天没看到那辆车。", "error_description": "表示已经发生的“没看见”要用否定词“没”，说“没看到”，不能用“不”，应为「我没看到那辆车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像线一样的东西，用来传递信息，让身体能感觉和动。", "primary_collocate": null, "pronunciation": "shén jīng", "ipa": "ʂən³⁵ tɕiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "神经把信息传给大脑。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的神经受伤了，他拿不住杯子。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身体里有很多神经。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我的神经。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经让我们的手能感觉到冷和热。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛里的神经很细。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药对神经有好处。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿神经受了伤，走路很疼。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经坏了，手就感觉不到东西。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑和神经一起管着身体。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经系统", "label": "复合"}, {"form": "神经细胞", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体里传递信息、管感觉和动作的细线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经", "is_correct": true, "explanation": "“神经”是传递信息的组织，与“把信息传给大脑”搭配，句意通顺。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏负责输送血液，不传递信息，句子说的“把信息传给大脑”不合。"}, {"text": "血管", "is_correct": false, "explanation": "语义：血管运送血液，不负责传递信息，句意不通。"}, {"text": "肌肉", "is_correct": false, "explanation": "搭配：“把信息传给大脑”要用能传递信息的器官，“肌肉”不这样搭配。"}], "explanations": {"神经": "“神经”是传递信息的组织，与“把信息传给大脑”搭配，句意通顺。", "心脏": "语义：心脏负责输送血液，不传递信息，句子说的“把信息传给大脑”不合。", "血管": "语义：血管运送血液，不负责传递信息，句意不通。", "肌肉": "搭配：“把信息传给大脑”要用能传递信息的器官，“肌肉”不这样搭配。"}, "sentence_index": 0, "correct_answer": "神经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的神经很结实，每天都锻炼身体。", "explanation": "这里应该用〈肌肉〉。“结实”形容肌肉、骨头，神经不这样形容。"}, {"text": "他手臂受伤了，血从神经里一直流出来。", "explanation": "这里应该用〈血管〉。神经传递信息，血液要在血管里流，不能说“血从神经里流”。"}, {"text": "他手上受伤的是一只神经。", "explanation": "这里的量词用错了。“只”用于动物，神经细长，应该用“根”或“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经", "is_correct": true, "explanation": "“神经”是身体里传递信息的组织，药物对神经有好处，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：药物对人和动植物有益，对石头没有好处，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：药不能对手机起作用，“有好处”一般指生物。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“对……有好处”一般接人或生物，不接房子。"}], "explanations": {"神经": "“神经”是身体里传递信息的组织，药物对神经有好处，句意通顺。", "石头": "语义：药物对人和动植物有益，对石头没有好处，句意不通。", "手机": "语义：药不能对手机起作用，“有好处”一般指生物。", "房子": "搭配：“对……有好处”一般接人或生物，不接房子。"}, "sentence_index": 6, "correct_answer": "神经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说他腿上有一颗神经受了伤。", "explanation": "这里的量词用错了。“颗”用于圆粒状的东西，神经细长，应该用“根”或“条”。"}, {"text": "他的神经堵住了，呼吸很困难。", "explanation": "这里应该用〈气管〉。神经传递信息，不会堵塞；呼吸困难是气管堵住了，应该说气管。"}, {"text": "他的神经很聪明，学习很快。", "explanation": "这里应该用〈大脑〉。“聪明”形容大脑的思考能力，神经不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在手术中小心地保护了这只神经。", "corrected_sentence": "医生在手术中小心地保护了这根神经。", "error_description": "错误形式：“这只神经”。正确形式：“这根神经”。“只”多用于动物，神经细长如线，应该用量词“根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个病人的一块神经受了伤。", "corrected_sentence": "这个病人的一根神经受了伤。", "error_description": "错误形式：“一块神经”。正确形式：“一根神经”。“块”用于成块的东西，神经细长如线，应该用量词“根”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
