INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用耳朵去感受声音。", "primary_collocate": null, "pronunciation": "tīng", "ipa": "tʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "我喜欢在晚上听音乐。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听，外面在下雨。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上听新闻。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在教室里听老师讲课。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她戴着耳机听歌。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再听一遍这个句子。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷晚上常常听广播。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在房间里听到了小鸟的声音。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听，是谁在唱歌？", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边走路一边听音乐。", "target_word": "听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听了", "label": "体标"}, {"form": "听着", "label": "体标"}, {"form": "听过", "label": "体标"}, {"form": "听听", "label": "重叠"}, {"form": "听见", "label": "复合"}], "register": "通用", "sense_fingerprint": "用耳朵听声音、音乐、讲话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fb865e3-8ed5-4241-8c43-69bb91bb5b7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”（tīng）：用耳朵去感受声音。此处指听音乐。"}, {"text": "亭", "is_correct": false, "explanation": "tíng（第二声）与 tīng（第一声）声调不同，意思是亭子。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 tīng 韵母不同（ang 与 ing），声调相同，意思是汤。"}, {"text": "丁", "is_correct": false, "explanation": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是丁。"}], "explanations": {"听": "“听”（tīng）：用耳朵去感受声音。此处指听音乐。", "亭": "tíng（第二声）与 tīng（第一声）声调不同，意思是亭子。", "挺": "tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。", "汤": "tāng 与 tīng 韵母不同（ang 与 ing），声调相同，意思是汤。", "丁": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是丁。"}, "sentence_index": null, "correct_answer": "听"}, "level_3": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”表示用耳朵感受声音，与“音乐”搭配，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是身体或物品，不能与“音乐”搭配。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责骂，与喜欢音乐的语境完全不符。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的宾语是球或物体，不能与“音乐”搭配。"}], "explanations": {"听": "“听”表示用耳朵感受声音，与“音乐”搭配，符合句意。", "洗": "搭配：“洗”的宾语是身体或物品，不能与“音乐”搭配。", "骂": "语义：“骂”是责骂，与喜欢音乐的语境完全不符。", "踢": "搭配：“踢”的宾语是球或物体，不能与“音乐”搭配。"}, "sentence_index": 0, "correct_answer": "听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很香，你听一听它的味道。", "explanation": "这里应该用〈尝〉。“听”只用于声音，品尝味道要用“尝”。"}, {"text": "你听一听这块布软不软。", "explanation": "这里应该用〈摸〉。“听”只用于声音，感觉软硬要用手“摸”。"}, {"text": "这朵花很香，你听一听。", "explanation": "这里应该用〈闻〉。“听”只用于声音，闻气味要用“闻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22792, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”（tīng）：用耳朵去感受声音。此处指听广播。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 tīng（第一声）声调不同，意思是停止。"}, {"text": "艇", "is_correct": false, "explanation": "tǐng（第三声）与 tīng（第一声）声调不同，意思是小船。"}, {"text": "盯", "is_correct": false, "explanation": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是注视。"}, {"text": "庭", "is_correct": false, "explanation": "tíng（第二声）与 tīng（第一声）声调不同，意思是庭院。"}], "explanations": {"听": "“听”（tīng）：用耳朵去感受声音。此处指听广播。", "停": "tíng（第二声）与 tīng（第一声）声调不同，意思是停止。", "艇": "tǐng（第三声）与 tīng（第一声）声调不同，意思是小船。", "盯": "dīng 与 tīng 声母不同（d 与 t），声调相同，意思是注视。", "庭": "tíng（第二声）与 tīng（第一声）声调不同，意思是庭院。"}, "sentence_index": null, "correct_answer": "听"}, "level_3": {"options": [{"text": "听", "is_correct": true, "explanation": "“听”表示用耳朵接收广播的声音，与“广播”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能与“广播”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后不能直接接“广播”作宾语，表示播放节目的说法不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与爷爷收听广播的日常活动不符。"}], "explanations": {"听": "“听”表示用耳朵接收广播的声音，与“广播”搭配，符合句意。", "吃": "搭配：“吃”的宾语是食物，不能与“广播”搭配。", "唱": "搭配：“唱”后不能直接接“广播”作宾语，表示播放节目的说法不通。", "扔": "语义：“扔”表示丢弃，与爷爷收听广播的日常活动不符。"}, "sentence_index": 6, "correct_answer": "听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边走路，一边听地图。", "explanation": "这里应该用〈看〉。“听”只用于声音，看地图要用“看”。"}, {"text": "这张画很美，你听一听它的颜色。", "explanation": "这里应该用〈看〉。“听”只用于声音，颜色要用“看”。"}, {"text": "她轻轻听了听小狗的头。", "explanation": "这里应该用〈摸〉。“听”只用于声音，用手接触要用“摸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在车上听着新闻着。", "corrected_sentence": "他在车上听着新闻。", "error_description": "错误在句末：“着”紧跟动词“听”即可，句末多出的“着”应删去，应为“听着新闻”。正确句：“他在车上听着新闻。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听过过这首歌。", "corrected_sentence": "我听过这首歌。", "error_description": "错误在“过”的重复：“听过”的“过”已表示经历，动词后不能再加一个“过”，应删去多余的“过”。正确句：“我听过这首歌。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
