INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "根据外表或迹象来判断，给人的样子或印象是怎样的。", "primary_collocate": null, "pronunciation": "kàn qǐ lái", "ipa": "kʰan˥˩ tɕʰi˨˩˦ lai˧˥", "syllable_count": 3, "sentences": [{"text": "他看起来很累，我们让他休息吧。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气看起来不太好。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕看起来很好吃。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来比我小几岁。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看起来有点不高兴，怎么了？", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事看起来很容易，做起来很难。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭馆看起来很干净。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看起来明天会下雨，带上伞吧。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看起来很饿，一直看着我。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来像个老师，其实是医生。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "看起来：根据外表或迹象判断，给人的样子是某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5414130c-939f-47d2-a1d8-a425c962efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
